// netlify/functions/get-devotional-plan.js
//
// Serves the full content (all 52 days) of one of the 6 "52 Bible
// Verses" devotional plans (Hope, Miracles, New Believer, Kids, Men,
// Youth) as JSON, one plan per request.
//
// This used to be a single ~257KB object literal embedded directly in
// app.html (const DEVOTIONAL_PLANS), which meant every visitor
// downloaded and parsed all 312 days across all 6 books on every app
// load, whether or not they ever opened a devotional plan -- that one
// block alone was roughly a third of the entire app.html file. Moved
// here so app.html only keeps a tiny manifest (title/subtitle/cover per
// plan) and fetches a specific plan's full days array only when someone
// actually opens it (see loadDevoPlanFull in app.html), the same
// on-demand pattern get-blog-posts.js and get-nature-photo.js already
// use for other content that doesn't need to ship on every load.
//
// Deploy: this file must live at netlify/functions/get-devotional-plan.js
// in a Netlify site connected to a Git repo (or deployed via the
// Netlify CLI) -- functions do NOT work with a plain Netlify Drop of
// static files. Once deployed, it's reachable at:
//   https://<your-site>.netlify.app/.netlify/functions/get-devotional-plan?plan=hope
//
// Deliberately stores only the verse REFERENCE for each day, not the
// verse text printed in the source books, since those quote NIV (and
// ESV/MSG for New Believer) -- all copyrighted, commercially-licensed
// translations. The verse itself is still fetched live from
// bible-api.com's WEB translation (public domain) client-side, exactly
// as before -- this function only changes WHERE the reference/devotion/
// questions/confession text lives, not how the verse itself is sourced.

const DEVOTIONAL_PLANS = {
    hope: {
      title: '52 Bible Verses on Hope',
      subtitle: 'Fifty two devotionals that will inspire hope',
      cover: '/assets/plan-cover-hope.jpg',
      days: [
        { day: 1, reference: 'Psalm 37:34', devotion: 'Great hope is found on God’s path. When we follow the Bible, we’ll find that we can be safe and secure in what we do. You may want to be hopeful, but if we don’t follow His path, we’ll find ourselves slipping. You may even wonder why God is doing this to you; it’s because while we said we trust God, we didn’t obey His Word. If you put your hope in God and follow His ways, you’ll inherit the land (Psalm 37:9)! The way of the wicked will always end in death, but you can trust that God’s path always leads to victory.', questions: 'Have you started reading the Bible? Consider starting a Bible reading plan. The Bible gives us the best path for life. What new habits from the Bible are you wanting to apply to your life?', confession: 'I will carefully live according to God’s ways. He will elevate and establish my life.' },
        { day: 2, reference: 'Psalm 42:5', devotion: 'King David ruled over ancient Israel and was known as a great writer of prayers and songs throughout his life. In this verse, King David articulates the battle of being led by our emotions rather than by God’s character. He asks a great question of himself: “Why are you so depressed?” Rather than just being led by his internal emotions, he challenges and questions them and calls himself back to the truth. Rather than losing hope, he stirs it back up and tells it where to rest. He’s challenging himself to put his hope back in God rather than the circumstances or the person that had hurt or wronged him. It takes intentionality to retrain your mind!', questions: 'Take time to evaluate the state of your soul. Are you feeling full of joy or overwhelmed? How are you keeping your soul and body refreshed?', confession: 'I will not be led by my emotions; I will put my hope in God.' },
        { day: 3, reference: 'Psalm 9:17-19', devotion: 'God is the hope of the afflicted! God isn’t just interested in you when you win and are on top of the world. Sometimes in life, we can find ourselves being so performance-driven that we wonder if God is just the hope of the heroes and the happy, but He is also your hope when you feel like you’ve reached the end of your rope. God does not shy away from our mess and challenges,[^c10] but He is available to heal you and respond to your cry for help.', questions: 'When have you experienced a loss or failure? Share how you felt and how God comforted you. How have you learned to heal and regain your hope?', confession: 'Even if I fail, God will protect me and never forget me.' },
        { day: 4, reference: 'Psalm 33:16-18', devotion: 'What are you putting your hope in? What are you resting your confidence and trust in? Is it in the modern-day version of the horse, which would be our careers, education, or family ties? On this side of eternity, while we need protection and security, ultimately our salvation comes from God. So many times in Israel’s history, they were outmanned and overpowered, but God gave them victory. Keep building and expanding your skills and abilities, but put your hope in God.', questions: 'Have you ever felt overpowered? Have you ever put your trust in the wrong person or skill or job? What happened?', confession: 'My trust is not in the strength of my hand but in the power of my God!' },
        { day: 5, reference: 'Psalm 33:19-21', devotion: 'You can put your hope in God no matter the season you find yourself in. Even in a famine, God is able. If we’re not careful, we’ll say we trust God, and then when we see a news story or the stock market update, we go to fear. It’s as if we’re assuming that God can help us only when the economy is good. But God is Lord over all of the elements and nations. Keep fighting to put your hope in God in the good seasons and the difficult seasons. Whether the doctor’s report or the financial report is good or bad, return to God and put your trust in Him.', questions: 'What’s the most difficult time you’ve found yourself in? How did God help you through it? What difficulty do you need God to redeem or heal right now?', confession: 'I wait in great expectation for God’s deliverance!' },
        { day: 6, reference: '2 Kings 4:27-28', devotion: '“Don’t get your hopes up” is a phrase that we often hear in our culture. It’s an attempt to stop our risk of disappointment and pain. But this phrase is a trick of the enemy to rob your life. God calls us to great faith, and the devil is always going to tempt you to play it small and safe. Hope is the building block that purpose and potential are built on, so the devil is going to try to steal your hope. Even when you’re facing what might seem like the death of your dream, don’t lose hope! Remember, God is faithful.', questions: 'What dream or promise has God given you? Have you walked through a season where your dream was lost? Share about it.', confession: 'I will keep my hopes up because my hope is in God!' },
        { day: 7, reference: 'Job 13:14-16', devotion: 'Job is a man in the Bible who was very prosperous but experienced severe trials and lost everything, including his family. The journey Job walks through is almost unimaginable! Yet through it all, he maintains an unshakable view of God’s ultimate goodness. Even though Job is seeing a steady stream of evil coming his way, he anchors his hope in God’s track record of goodness toward the godly. This verse is also a testament to Job’s surrender to God’s wisdom and insight being beyond his own. Why would Job say, “Even if He kills me, I’ll hope in Him”? Because he’s saying, “I may not understand it all, but I will trust Him.”', questions: 'When is a time that God has been good and blessed your life? Is there any area of your life that you still need to surrender to God?', confession: 'I will put my hope in God even when I don’t understand everything He’s doing.' },
        { day: 8, reference: 'Psalm 52:9', devotion: 'God is good! This is a truth we know by how God has revealed Himself to us in the Bible and throughout human history. But, it’s also the key thing that the devil is always trying to challenge. With Adam and Eve, the devil tried to say that God was holding out on them. And he continues to repeat that lie. However, not only is God good, but He is working out good for you and has been working toward good from the beginning of time. Take time to reflect on the good that He’s done in your life and those around you, and watch how hope begins to rise in your heart again!', questions: 'What are three things you are thankful for? And what are three things you are worried about that you could turn over to God? Write them down.', confession: 'You are a good God! All you say and do can be trusted.' },
        { day: 9, reference: 'Psalm 62:5', devotion: 'From time to time you may feel like you don’t even have the ability to hope anymore. But that’s how good God is—not only is He the one that we want to put our hope in, but He is also the giver of hope. When you’re up against a wall and feeling overwhelmed, lean into and spend time with Jesus. He will pour hope into your heart once again! Notice how King David, the author of this psalm, commands his soul: you don’t have to be run by your emotions; tell your soul where to go for hope!', questions: 'Are you taking time to rest? If not, make it a priority to carve out some time for resting and spending time in prayer and reading the Bible. How can you become more consistent in church attendance, Bible reading, and prayer?', confession: 'God is where my soul truly finds rest and refreshing. My hope comes from God.' },
        { day: 10, reference: 'Psalm 65:5', devotion: 'This verse reminds us that He is an answering God. He’s not distant and silent and uninterested; He’s present and answering in abundant fashion. Also, notice that God is not just our hope in whatever nation you’re reading this, but God is the hope of all people in all nations. It is the heart and desire of heaven to have all nations in relationship with God and for everyone to experience His hope.', questions: 'What is a recent prayer God answered that you can stop and be thankful for? What’s one situation that you need wisdom, healing, or help from God?', confession: 'God loves to hear from me and will answer my prayer. You are the hope of the nations!' },
        { day: 11, reference: 'Psalm 71:5', devotion: 'You may not have known God since your youth, but you can be confident that no matter when you connected with God, He will be faithful through every age—just like a parent to a child. Each season of our development is going to need something different from a parent, and God is ready to meet each need in your life through all of the seasons. Also note that if God has been faithful to King David since his youth, that means God is gracious with our immaturities and issues and will walk through it all, upholding His goodness even when we fail.', questions: 'Was there a time as a child that you felt alone? Talk about that. When has God felt close to you?', confession: 'God is personally walking with me in all seasons of life! I will put my hope in His faithfulness!' },
        { day: 12, reference: 'Psalm 71:13-15', devotion: 'Why is King David, the writer of this psalm, declaring hope? Because he understands the nature of God. While God judges and condemns the wicked, David also knows that God blesses and strengthens the righteous. His hope is in God and His ability and desire to bless and strengthen you. Even when evil is coming against you, don’t fear because God is working toward your good. I love that in this verse, David declares, “I will always have hope.” He’s saying, “No matter what the future holds, I am secure because I know who holds the future!”', questions: 'Did you grow up believing that God wanted to bless you? Do you see God as tolerating you or as available to save and rescue you?', confession: 'I will always have hope because God is always with me!' },
        { day: 13, reference: 'Proverbs 24:14', devotion: 'We see here that hope is a by-product of wisdom. Hope is not a feeling that’s disconnected from reality; it’s a feeling and expectation that flows from a life of wisdom. When I know that I’m living right and according to God’s Word, it gives me hope and confidence that the outcome of what I’m going after will be successful. The more wisdom and counsel that you embrace, the greater the hope of victory is and the greater the faith you can take on the future with. You don’t have to live in dread of what will or could happen, but you can have great hope because you are walking in wisdom.', questions: 'Have you asked God for wisdom? What is He saying? Who can you set an appointment with to seek counsel from?', confession: 'God, I will seek your wisdom and find hope!' },
        { day: 14, reference: 'Psalm 119:81', devotion: 'Sometimes we’re afraid to be honest about where we’re at in life. But King David shows us how to be vulnerable with the heaviness or pain that we’re walking through. He then directs himself back to hope in God. And right now, no matter what you may be facing, you may feel like David, where you’re about to faint—but don’t let your feelings tell you where to hope; put your hope in God today!', questions: 'When was a time you almost quit, but you made it through? Do you have a favorite inspirational quote or expression? Identify two or three Bible verses you can learn and repeat often to build your faith.', confession: 'Even when I feel tired, God will remain faithful.' },
        { day: 15, reference: 'Psalm 119:147', devotion: 'Is your daily routine intentional? King David gives us a window into how he keeps a life full of hope. Instead of waking up aimlessly or waking up and focusing on the negative, he wakes up and cries out to God right away! If you create a rhythm of getting in your daily Bible reading and prayer as the first thing, you’ll set up your day to thrive. There are principles of first and focus. What you put your focus on first will set the flow for the rest of your day.', questions: 'What’s one thing you need to add to your daily routine? What’s one thing you need to remove from your daily habits?', confession: 'I will daily call out to the Lord and put my hope in Him!' },
        { day: 16, reference: 'Psalm 130:7', devotion: 'Are you calling others to hope? There’s a lot packed into this verse, but let’s focus on the fact that King David is directing and challenging his nation to put their hope in God. We’re often made to believe that we just need to pause and focus on ourselves and then help others later once we’re good. But, throughout the Bible, we see that God uses us even as we’re walking through difficulty. We get strengthened as we serve others. God called and activated Gideon before he felt strong.[^c27] (Judges 6) The Apostle Paul said God’s strength is made perfect in my weakness (2 Corinthians 12:9).', questions: 'Who can you encourage to put their hope in God today? Who can you add value to?', confession: 'I will call people to put their hope in the unfailing love of God!' },
        { day: 17, reference: 'Psalm 147:11', devotion: 'When you decide to honor and fear the Lord, it sets the rest of your life in order. The book of Proverbs teaches us that trusting the Lord is the beginning of wisdom (Proverbs 9:10). The words *hope* and *trust* are strongly linked. When I put my trust and hope in the Lord, I will live with a greater sense of peace and mercy in my life. The end of this verse is where all the confidence lies: “his unfailing love.” God’s love is eternal, never-ending, and unfailing. Even if I fail, He won’t.', questions: 'Do you find it difficult to trust the Bible? Why or why not? Is there a section of the Bible that you’re currently having a difficult time with?', confession: 'I will submit my life fully to God! His ways are higher and more reliable than mine. My hope is in His love.' },
        { day: 18, reference: 'Proverbs 11:7', devotion: 'Where is your hope placed today? Is it in the temporary or the eternal? Often to get the right view of something, we have to elevate our perspective. We need to see it from above. When you’re down in the weeds of life, it’s easy to get overwhelmed and to lose sight of where you’re going. This is why we put our hope in God rather than humans. It’s only in God, who has the elevated and eternal view, that we can be assured and confident of the wisdom and insight that we’re getting. Trust in God’s Word.', questions: 'Was there a time when you determined to trust God’s Word over your own? Explain. What wisdom do you need from God right now?', confession: 'God, you are sure and reliable! When I trust you, I won’t be disappointed.' },
        { day: 19, reference: 'Proverbs 13:12', devotion: 'Many are disheartened and discouraged because of unfulfilled hopes and dreams. But we see clearly that God loves to see your desires fulfilled. You’re not fighting against God to do and accomplish what’s in your heart; you’re working with Him. If you’re currently experiencing delays in your dream, get some outside counsel or coaching to help you determine if you need to maintain course and stay faithful or if you need to change and adjust how you’re thinking or acting to see your hopes fulfilled.', questions: '', confession: 'I will thank God for hopes fulfilled, and I will trust God when dreams are delayed.' },
        { day: 20, reference: 'Psalm 119:43', devotion: 'King David knew how essential God’s Word is. So much so that he says, “Never take your word from my mouth.” The way he describes his hope in God’s Word is powerful. He knows where to put his hope. Often we’re caught in trouble because we’re putting our hope and trust in all the wrong things. It’s a good reminder that if you’re feeling tired or weary, it could be an indicator that you’ve placed your trust in the natural rather than the supernatural power and principles of God.', questions: 'How often are you engaging with the Bible? What’s one of your favorite verses and why?', confession: 'God’s Word is powerful and gives me hope! I will daily speak the truth from the Bible.' },
        { day: 21, reference: 'Ecclesiastes 9:4', devotion: 'If you’re still breathing, you have reason to hope. We love the strength of lions and the majesty that they carry. We can often look at our own lives and feel a lack of hope or strength because we’re not the lion or because we see ourselves more like the dog in comparison. But if you’re alive, you have a chance for victory. Don’t worry if you’re the lion or the dog; just be concerned with if you’re breathing. God can do anything He wants with your life. He used a small teenager to defeat a giant warrior and to save a nation (1 Samuel 17: 1-58). Don’t doubt what God can do in and through your life!', questions: 'Have you allowed comparison to rob you of your purpose? Who inspires you?', confession: 'I will honor God with every breath that I have. As long as I am living, I have purpose and potential!' },
        { day: 22, reference: 'Isaiah 40:28-31', devotion: 'The Bible says that the joy of the Lord is our strength (Nehemiah 8:10). Hope is in the same vein as joy. When our hope disappears, we’ll find ourselves tired and losing the strength, both physically and mentally, to take on the adventures and challenges of life. The encouraging thing about this verse is that if your hope has weakened, it can be strengthened again. It is renewable. And God is the source of the supply of that hope. Look to Jesus and your hope will return, and with that hope, strength will be renewed in you!', questions: '', confession: 'I may get weary, but my strength will be renewed as I put my hope in God!' },
        { day: 23, reference: 'Jeremiah 14:22', devotion: 'God is our source of life and provision. Take inventory of the things you’ve been putting your confidence in – is it giving you good results? Look to the fruit and results of God’s Word and promises. Jesus encouraged us to judge a tree by its fruit. Jesus said that He is the vine and we are the branches (John 15:5). This means that we must stay connected to Him to be fresh, alive, and producing results. If you’re finding your life, relationships, work and health are suffering, take the time to make sure you’re connect to the vine which is Jesus.', questions: 'What miracles have you seen God do in your life or in the lives of those around you? What provision do you need right now that you can begin to pray about?', confession: 'My hope is in God, the source of blessing and provision!' },
        { day: 24, reference: 'Jeremiah 29:11', devotion: 'God’s plan is for your good! Don’t buy into the lie that God wants you to suffer or be in lack. He may take you through a valley or a storm, but He’s always leading toward peace and the blessing of God. This verse is a promise that we must learn to hold onto with all that we have to help us each day. Even if the current circumstance isn’t good, when God is working through the duration of your life, He’s always leading toward green pastures—for your good and His glory.', questions: 'Did you grow up thinking that God wanted good for your life? Or how did you see Him? Is there a good desire in your heart that you need to chase again?', confession: 'God has intentional plans to bring good into my life!' },
        { day: 25, reference: 'Lamentations 3:20-22', devotion: 'If we’re going to be overflowing with hope, we have to learn how to call to mind the right things. We are constantly bombarded with the wrong thoughts and negative messaging that drain our strength. So, learn to identify when the wrong thoughts are coming your way, and direct your mind and heart toward what is good. One of the key things to keep focused on that will bring hope is the love of God. It’s because of His love that we are not consumed. His love and grace hold us together.', questions: '', confession: 'The love of God is great and never-ending! I will put my hope in His faithfulness.' },
        { day: 26, reference: 'Ezekiel 37:10-12', devotion: 'We must learn to declare and prophesy the Word of God over our lives rather than echoing the words of our culture. In this valley, the dry bones were the reality. Sometimes we come face-to-face with the deadness of our circumstances, feeling like all hope is lost. But we must go to God and His Word, find His promises for our lives, and hold onto them. Things may look dry, but if you have a promise from God, begin to speak that out and declare it. God’s Word can bring hopeless things back to life! This is the power of God’s Word in your mouth!', questions: '', confession: 'God can bring dry and dead things back to life. I will prophesy God’s Word over my life!' },
        { day: 27, reference: 'Matthew 12:20-22', devotion: 'Jesus is the hope of all people in all nations. He is and always will be the true and only solution to the brokenness of mankind. But Jesus’ sacrifice is sufficient for everyone. The enemy thought that he would be able to break and end the prophetic fulfillment of the Messiah, but in crucifying Jesus, the full strength of the power of the blood of Jesus was released to heal and save. Today, put your hope in the name of Jesus!', questions: 'What are the biggest challenges facing your city? How can you do your part to bring Jesus and biblical principles into your city?', confession: 'I will put my hope in the God of justice and mercy!' },
        { day: 28, reference: 'Acts 2:25-27', devotion: 'We often underestimate the toll that life can have on us. Work, family, the economy, school, and the news can all begin to drain our energy. When we put our hope in Jesus, it affects our heart and emotions; it changes how we speak; and it impacts the physical body’s ability to rest. When we learn to set our minds on the faithfulness of God, it will allow us to enter into greater levels of rest. The Bible says that He grants sleep to those He loves (Psalm 127:2). You don’t need to run the planet or solve all the problems; allow God to run the universe, and choose to entrust your life into His hands.', questions: 'Do you have a good rhythm of rest? What’s something God has spoken to you during your devotional time?', confession: 'I am unshakable because my hope is in the unshakable God!' },
        { day: 29, reference: 'Romans 4:18[^c49]', devotion: 'What a powerful verse! Against all odds, Abraham goes all in! Abraham was over eighty and had no children, but God promised to make a huge nation from his descendents and Abraham believed God! So now we know him as the father of the faith. That title came because he chose to stare fear in the face and keep trusting God. Much of your calling and breakthrough is on the other side of what seems hopeless. But the only situation that is truly hopeless is when God isn’t involved. When the doctor says there’s nothing they can do or the bank says there’s no way, that’s when you lean in even harder to the promises of God and keep believing!', questions: 'What is the most daring thing or mission you’ve ever attempted? When did you trust God and go for it even when it seemed impossible?', confession: 'No matter what circumstances look like in the natural, I will put my hope in the promise-keeping God!' },
        { day: 30, reference: 'Romans 5:3-5', devotion: 'When you trust God, hope is an end product of life’s trials. Instead of these circumstances taking us out, they begin to produce perseverance and character that shape our hope. It says hope doesn’t disappoint. What does that mean? The kind of hope that is shaped over trials and time isn’t a weak hope. It’s a sure and solid hope that is built on the track record of God. This kind of hope will not disappoint when you’re facing trials. Stay in the game, don’t give up, and watch God faithfully fulfill His promises to you.', questions: '', confession: 'Patience produces godly character and a sure hope!' },
        { day: 31, reference: 'Romans 8:24', devotion: 'We’re being challenged here—in a good way! The Apostle Paul, who wrote this verse, [^c52]is saying that if your hope is in just what you can see in the natural world, that’s not true hope and faith. Hope is a trust in the God of the universe’s ability to keep His Word. Jesus often commended those who trusted before seeing or even without seeing. God can truly work through the individual willing to take Him at His Word. If God promised it to you in the Bible and by His Spirit but you’re not seeing it yet, keep trusting and hoping in Jesus.', questions: '', confession: 'My hope isn’t built on circumstances but on God’s faithfulness.' },
        { day: 32, reference: 'Romans 12:12', devotion: 'Worship while you wait! While you’re waiting for that thing you’re hoping for, keep praising. All through Scripture God highlights worship and thankfulness. When Jesus heals ten lepers and only one comes back to say thank you, Jesus asks where the rest of them are (Luke 17:17). For the thankful one, Jesus both heals and brings salvation. King David calls us to enter into God’s presence with thanksgiving and praise (Psalm 95:2). Are we going to complain while we wait, or are we going to be joyful in hope?', questions: 'When’s the last time you thanked God without being prompted? What is an over-the-top offering you could bring God to thank and praise Him?', confession: 'I will be thankful and worship while I wait for the promises of God to be fulfilled.' },
        { day: 33, reference: 'Romans 15:4', devotion: 'Take trips back in time to remember the faithfulness of God in your life and the lives of others. The Bible is written to give you hope. When I revisit the stories of God’s power, faithfulness, grace, and provision, it calls me toward hope. The Bible teaches us that faith comes by hearing (Romans 10:17), and so does hope. Hope stirs up and increases faith in my heart the more I remember how He has carried the men and women of faith in the Bible and modern history. Become a student of God’s goodness to others, and it will give you hope to believe for it to be repeated in your life!', questions: 'Take time to read the first four books of the New Testament, also known as the Gospels, to be reminded of Jesus’ desire to forgive, heal, and set you free! What’s one thing you’ve learned in the waiting?', confession: 'My hope increases when I endure and stay faithful!' },
        { day: 34, reference: 'Romans 15:13', devotion: 'A life of hope in God produces joy and peace. The Holy Spirit causes us to overflow with hope. In modern self-help teaching, it’s purely up to you to make all of the happiness and hope happen. But we see that hope is more of a flow from the Holy Spirit that produces that life of joy and peace than it is about you trying to be happy in yourself. Have you invited the Holy Spirit to come and fill you and empower you? Learning to surrender to the Holy Spirit is central to this life of hope! Hope is from Him.', questions: '', confession: 'He is the God of hope. I will walk in joy and peace as I trust Him!' },
        { day: 35, reference: '1 Corinthians 9:10', devotion: 'The principle of seedtime and harvest has been established by God. He teaches us to expect a harvest from our seed. And in your life, He wants you to live with an expectant hope of the fruits of your labors. You don’t have to do what’s right without any hope that good will come of it. When dreams and harvest get delayed, we get discouraged and that is a killer of hope. God has designed and determined that you have a hope of reward for your investment.', questions: 'What are you expecting God to do in this season? What are you hoping to see happen in your life, work, and areas of service in the next few months?', confession: 'I will share the rewards of my work. I will reap what I sow.' },
        { day: 36, reference: '1 Corinthians 13:1-8', devotion: 'Our relationships thrive on love and hope. True love always hopes for the best and wants the best for you. When the people in your life can sense that you are believing the best about them and hoping for good for them, it’s an empowering and freeing thing. Have you lost hope for a friend? Have you lost hope for your marriage? If you feel something getting dry or difficult, add some faith into it and watch it come alive. Just like a plant that is wilting because it’s low on water, a relationship without hope will begin to wilt.', questions: 'Read over the verse multiple times this week. What is God highlighting to you? In what ways could you show more love and hope in your relationships?', confession: 'I will choose to hope and believe the best about the people in my life. I will speak life over them!' },
        { day: 37, reference: '1 Corinthians 15:19', devotion: 'Your hope is not temporary. Your hope in Jesus is not just a feel-good fairy tale that numbs the pain of earth. Your hope is eternal. The Apostle Paul says if we’re just doing religion for this life, people should feel sorry for us. But our hope is for life and the life to come. Jesus came for both here and now and then and there. And while we’re here, Jesus tells us to pray for His kingdom to come on earth (Matthew 6:10)! Christianity is to impact every part of your life. It’s for the physical and the natural day-to-day that we all face. God has answers for every day.', questions: '', confession: 'My hope is Jesus so my hope is eternal!' },
        { day: 38, reference: '2 Corinthians 3:12', devotion: 'My hope in Jesus gives me courage! Because I know who’s behind me, I’m full of hope. It reminds me of the story of David and Goliath; although he was young and much smaller, David had confidence that he could beat the giant Goliath, because God was on David’s side. In your life, you’ll know that you’re starting to live and walk in greater hope when you begin to live with less fear and more courage. Courage in what you say and in what you do should be a by-product of knowing God more. The Old Testament prophet, Daniel, who faced his fears in the lions’ den, said that the people who know their God will be mighty (Daniel 11:32)!', questions: 'What’s the difference between arrogance and boldness? What past victory has God given you that gives you boldness to take on the future?', confession: 'I will put my hope in God and walk in boldness!' },
        { day: 39, reference: 'Galatians 5:5', devotion: 'The Holy Spirit continues to be a theme connected to the topic of hope. Through Him, we are encouraged and given the ability to wait for the hope to be fulfilled. The more we lean into the voice of the Holy Spirit, the more at peace we will be in our day-to-day lives. The Bible calls us to keep in step with the Spirit (Galatians 5:25). When He steps, you step. He will guide and direct you onto the right path. It’s the Holy Spirit that walks with us on earth toward out ultimate salvation and heaven.', questions: '', confession: 'The Holy Spirit is perfecting me. I walk in the righteousness that Jesus gave me.' },
        { day: 40, reference: 'Ephesians 1:17-19', devotion: 'What a great hope we have been called to! Often we forget to reflect on His goodness. Our hope in Jesus is of eternal significance! Because of our sin, we had been condemned to hell and eternal separation from God. We were lost and without hope. But, because of Jesus, we have overcome this unpayable debt. Jesus came as the perfect Lamb of God to become the eternal and once-for-all sacrifice for the sin of humanity. If we put our hope in Him, we’ll be saved, healed, forgiven, and set completely free from the grip that Satan had on us.', questions: 'Have you given your life to Jesus? What are you most thankful for about your relationship with God?', confession: 'I will walk in the fullness of all that Jesus paid for on the cross.' },
        { day: 41, reference: 'Ephesians 2:12', devotion: 'The purest form of hopelessness isn’t that things are difficult but that Jesus is not present. No matter the circumstance, if God is with you, you don’t need to feel hopeless. If you’ve found Christ, then you’ve found pure hope. Look around you today and ask God to give you eyes to see others in your family, work, or community who are away from Jesus and without hope. How can you reach out today and invite them to come to church with you? Our world is dealing with all kinds of depression and anxiety from a lack of hope. And Jesus is the true answer to the pain and longing of their hearts.', questions: 'Who in your world needs Jesus? What was the moment that led you to Christ?', confession: 'I have great hope! Jesus paid the debt of my sin.' },
        { day: 42, reference: 'Colossians 1:23', devotion: 'We live in an instant world. We enjoy most things right away with little wait. But most of the calling and purpose that God has for you is going to be birthed over time. And in that process of time is where your character development happens. It’s also where we can tend to get weary and lose hope. But, in all of the seasons and trials of life, keep holding onto the hope that Jesus holds out to us—which is that He loves us so much that He came to be with us and bring us close to Him! He’s holding out the hope, but are you receiving it?', questions: 'Are you frustrated with delays or patient with the process? What’s something that was worth the wait?', confession: 'I will continue in faith. I will put my hope in the good news of Jesus!' },
        { day: 43, reference: '1 Thessalonians 1:3', devotion: 'Cause and effect are happening in this verse. Faith produces work, love prompts serving, and hope in Jesus gives strength to endure. It was the same for Jesus. He was able to endure the cross because he knew it was the only way to save people like us and that brought him joy (Hebrews 12:2). Our ability to keep our eyes on Jesus and continue to put our trust in Him will determine our ability to endure. What’s driving you? Is it just the good feelings in the moment? If so, then that can also stop you. God’s Word consistently calls us to set, place, and fix our eyes on Him. We need to focus on the hope that transcends the current moments.', questions: 'What work do you feel that faith and love are prompting you to do right now? How is hope giving you the endurance to keep going and not stop?', confession: 'I will walk in the faith, hope, and love of God!' },
        { day: 44, reference: '1 Thessalonians 4:13', devotion: 'Losing loved ones is difficult. Depending on how close we were to the individual, it may be more difficult, but regardless, loss requires times of grieving. Because of God’s promise of salvation and resurrection for those who are believers in Jesus, we do not have to mourn like those who have no hope. Because we are fully human, we’re going to experience all of the human emotions, but because of Jesus, we don’t have to drown in those emotions. We can grieve with peace. How? When you experience loss of life, look to Jesus.', questions: 'Share about a time when you lost a loved one. How was your grieving process? What helped you find hope again?', confession: 'I will have hope even in death. I will see in heaven all those who follow Christ on earth!' },
        { day: 45, reference: '1 Thessalonians 5:8', devotion: 'Hope is a helmet. Hope is an insulation against the mental attack of the enemy. One of the main ways that the enemy attacks us is through our minds—getting us to think in a way that is destructive to our lives and future. But, just like a helmet protects your physical head from injury, hope in Jesus protects your mind from the attack of the enemy. This is why the devil is always going to try to steal your hope and leave you unprotected. If the enemy can get us thinking hopeless thoughts, he’ll start getting you to live that way. Like the Bible says, take every thought captive (2 Corinthians 10:5)!', questions: 'Why does the Bible describe faith and hope as armor? How can you remain in hope despite all of the bad news?', confession: 'God will guard my heart and mind as I put my hope in Him!' },
        { day: 46, reference: '1 Timothy 6:17', devotion: 'We should work hard and create wealth like the Bible tells us we’ve been given the power to do. But where is your hope and trust? Is it in the economy? Is it in the latest stock market strength? Is it in the housing market? Or is your hope in Jesus? The truth is that even if you make all the right moves financially, there’s going to be difficult seasons and an economy you can’t control. Should that make you afraid? No, because your stability isn’t found in those factors but in the reliability of God’s economy. God can give you a strategy to be blessed even in famine.', questions: 'Have you experienced sudden loss? How did you recover? How can you make sure you have money rather than money having you?', confession: 'I will not put my hope in money. I will trust in God.' },
        { day: 47, reference: 'Hebrews 6:18-20', devotion: 'Hope is an anchor! An anchor grounds us, stabilizes us, and keeps us from being tossed back and forth by the wind and the waves. We can be tossed by things above and below the surface, but the anchor holds us securely. Today, get your life anchored in Christ. How? By getting connected to the church community. In the house of God, you get around like-minded followers of Christ who are letting down their anchor into Christ. In the world, we’re getting told not to put too much hope or trust in the Bible, but this lack of certainty is creating pain and confusion. Choose to drop the anchor of trust into Jesus and His Word today.', questions: 'What’s a lie that the culture is trying to force you to accept? How has trusting Jesus changed your life?', confession: 'I am secure because my hope is anchored in Jesus!' },
        { day: 48, reference: 'Hebrews 10:23', devotion: 'Let’s focus on the profession of your hope! Are you speaking and declaring hope? What are you actually saying out loud? What are you consistently confessing and professing over your life? That’s why we wrote a confession for each devotional to get your confessions infused with hope. You may need to write the promises of God on your mirror or post them around your home—whatever you need to do to be sure you hold unswervingly to the hope of Jesus. Biblical confession transforms your heart and mind, which then transforms your life!', questions: '', confession: 'I will declare the promises of God over my life!' },
        { day: 49, reference: 'Hebrews 11:1', devotion: 'Hope is the vehicle that faith rides in on. Hope is the atmosphere for faith, and faith brings heaven to earth. What are you hoping for right now? What are you stretching for in faith? God wants you to trust Him for the dream, calling, and promises that are beyond your reach. The promises that God gave to Abraham, to build a nation from his offspring when he had no children, were so far beyond him. [^c67]When Abraham would get off track because of doubt and delays, God would call him back to remember His promises. Those God encounter moments would renew his hope and cause him to trust God again!', questions: 'What are you believing God for that you don’t see yet? What role does hope play in your faith?', confession: 'Hope is the foundation of faith, and Jesus is the reason for my hope.' },
        { day: 50, reference: '1 Peter 1:3', devotion: 'Often when people talk about church, they think of religion and rules, but God calls us into a living and alive relationship with Him. Your salvation isn’t into a dead religion but a living hope. Have you ever been looking at an instruction manual and realized it’s for an older model of vehicle? That manual isn’t going to be able to help you because it’s outdated. But when God gave us His Word in written form, these are not dusty history lessons that are outdated; they are fresh and living and relevant for our lives today.', questions: 'What has God been doing in your heart as you’ve studied through these verses on hope? What has God brought back to life in you that felt hopeless?', confession: 'My hope is alive in Jesus! I do not fear because He is with me!' },
        { day: 51, reference: '1 Peter 1:13', devotion: 'Did you know you have a hope bank? And you have a choice where to set and invest that hope. Set your hope on God’s grace. His grace is so powerful because His grace isn’t dependent on my performance or what I say; it’s based on Him. The stock market rises and falls based on issues of the day. But God continues to show us kindness no matter our issues and challenges. And it’s on this unearned grace that we put our hope. So, my hope is sure and strong because I don’t have to worry if God is different today than He will be next week or next year.', questions: 'How have you learned to receive the grace of God in the middle of your failures? How are you daily choosing hope?', confession: 'God’s grace allows me to continue in hope even when I fail.' },
        { day: 52, reference: '1 Peter 3:14-16', devotion: 'We’ll wrap up these fifty-two verses on hope by calling all of us to continue to spread love and hope to the world around us. You have encountered the hope that is in Jesus. Now, are you ready to give a reason for that hope? Why are you hopeful? Why are you full of joy? Why did you give your life to that hope? When you’re sharing your hope, begin with just sharing your story about how Jesus changed your life. You don’t have to have all the right words; just share your personal experience with Christ. When you share that story, you’ll invite others into the journey, and they will want the hope that you have. Or the Hope that has you!', questions: '', confession: 'I will be ready to give the reason for this great hope!' },
      ]
    },
    miracles: {
      title: '52 Bible Verses on Miracles',
      subtitle: 'Devotionals to build your faith for healing, deliverance, and provision',
      cover: '/assets/plan-cover-miracles.jpg',
      days: [
        { day: 1, reference: 'Genesis 1:1-3 NIV', devotion: 'We begin our study of miracles, reminding ourselves that the one we look to is not a human with limitations or a false idol that people worship, but we’re looking to the one who created the heavens and earth! God sits above it all and holds everything together by His Word! When we need healing, provision, wisdom, deliverance, or anything else, we often get discouraged because we compare the difficulty of the miracle to our limited human perspective rather than to the bigness of God! Our Heavenly Father is the creator and Lord of all that we see and is more than able to do and fulfill everything that we ask for according to His Will! Turn your focus from your situation to the power of God!', questions: '', confession: 'Nothing is too difficult for God! He is the Creator and sustainer of all life! Miracles are released in His Name!' },
        { day: 2, reference: 'Jeremiah 29:11 NIV', devotion: 'To believe for God’s supernatural intervention, you must begin with the revelation that God is good and He has good in mind for you. Without that as our foundation, the devil will always be able to get us second-guessing if God wants to do good for us. Most of us are convinced that He can, but we must have a deep conviction that He wants to. God’s Word is packed with the truth that God loves us and created the best for us, from the abundant Garden to His Salvation on the cross. It’s clear that our perfect Heavenly Father intends the best for His children; we need to meditate on that until we believe it!', questions: '', confession: 'God is good, and He has good plans for me! I can confidently pray for a miracle because He’s good!' },
        { day: 3, reference: 'Matthew 6:10 NIV', devotion: 'Jesus calls us to pray that the Kingdom of Heaven will invade this earth. This is powerful when it comes to believing for miracles. We know that the Kingdom of Heaven has no sickness and disease, no poverty, and no demonic oppression. When we see anything in this life that doesn’t align with the Kingdom of Heaven, we can and should pray for God’s will and purpose to overtake Earth. When you need something or want something to change, stop and ask if it’s consistent with the Heavenly Kingdom; if not, you have the authority to come against that circumstance and bring Kingdom order to it! We are ambassadors and carriers of His purpose on Earth!', questions: '', confession: 'Lord, let your Kingdom come in my family, work, city, nation, and everywhere I have influence.' },
        { day: 4, reference: 'Matthew 7:7-11 NIV', devotion: 'These verses remind us of two major factors: first, God wants you to ask and keep asking until the answer comes, and second, God wants to give us good things. How often do we quit and stop short in prayer because we get fatigued with the delays or assume God is uninterested? However, we see here that Jesus calls us to ask, seek, and knock! Don’t get tired of seeking, and don’t assume you’re a bother to God. He wants to engage with you and give good things to those who ask. What have you stopped praying for that you need to pick back up again? Deepen your resolve to pray through until God comes through! Keep asking!', questions: '', confession: 'God is good and loves to give us good things! I will ask according to His will and keep seeking and knocking until the answer comes!' },
        { day: 5, reference: 'Matthew 14:14-21 NIV', devotion: 'God is more than enough! This miraculous provision is recorded in all Gospels and is performed a couple times by Jesus. He has people that need to be fed; they don’t have enough in the natural; in faith, they hand over the little they have to Jesus, and He blesses it and multiplies it, and there’s always some leftover! We don’t have to come to Jesus with a “just enough” mentality. God does the miraculous and then goes beyond what is needed. This is to showcase that we serve an abundant God! What do you need from God? Even when you feel like you don’t have enough, surrender your little to God and watch Him do the impossible! He multiplies what you sacrifice!', questions: '', confession: 'I will put my trust in the supernatural power of God! He can multiply what I have into overflow!' },
        { day: 6, reference: 'Luke 5:5-8 NIV', devotion: 'In obedience, Peter takes the word of Jesus about His business, and God performs a miracle. Maybe you are like Peter, who assumed that God’s Word and power only applied to spiritual or church things, but God’s Word, wisdom, and power are available for all areas of your life. Do you need a financial provision miracle? Do you need wisdom in your business or field of expertise? Go to Jesus! Pray and ask God for wisdom on what’s next. You may have been following conventional wisdom, but God has an “other-side of the boat” moment for you. The key is obedience; when Jesus speaks, you must listen and follow through!', questions: '', confession: 'I will trust God’s direction for my family, work, and ministry! Seek God, and He will provide supernatural provision and strategy.' },
        { day: 7, reference: 'Romans 8:28 NIV', devotion: 'No matter what you’re facing, as a child of God, you can be confident that He is actively working all the good and the bad circumstances for your good. What you’re facing may not be good, but your God is good, and He is the great orchestrator of the timeline of history, bringing favor toward those who follow Him. One of the greatest lies of the enemy is that you’re on your own or that you’re forgotten by God because of your circumstances. But, many heroes in the Bible, like Daniel, looked to God’s goodness even in the terrifying face of the lions. God is using your current pain or joy for your good! And if you’re willing, for other’s good as well. Don’t quit; God is still working!', questions: '', confession: 'God is good and working good for me! I will trust Him in all circumstances!' },
        { day: 8, reference: 'Luke 18:1-8 NIV', devotion: 'Persistence in prayer is what Jesus is calling us to! What are you believing for? What do you need God to do in your life? It’s time to be faithful to pray and continue in prayer until the answer has come. Sometimes we’ll like the answer, and other times we won’t but don’t stop short of heaven’s answer. Spiritual fatigue in prayer is a common tactic of the enemy; if he can get us to back up and back down from prayer, then he’s got us. But, if we remember that God speaks and answers, we’ll persist in making requests of Him. The verses end by asking, “Will He find faith.” What a powerful and convicting line. Will He find faith in us, or will we quit? Faith will be revealed by our persistence in prayer!', questions: '', confession: 'I will pray and keep on praying until I see the victory!' },
        { day: 9, reference: 'James 5:14-15 NIV', devotion: 'Is “anyone” sick? This may seem like a simple question, but the Bible is telling us that it’s the heart and desire of God to heal everyone who is sick. This is important since there will be some Christian circles that suggest that God doesn’t heal today or that we don’t know if God wants you healed. But God’s instruction to the church is that anyone who is sick and wants to be healed should go to the church leaders and receive prayer. We’re often in the habit of going to everyone else for healing except God, who is our healer. If you’re sick, get the power of agreement and faith from your church community and stand on the promise of these verses! The sick will be made well!', questions: '', confession: 'When I’m sick, I will engage my church community and believe for supernatural healing!' },
        { day: 10, reference: '2 Chronicles 7:14-15 NIV', devotion: 'We often think of needing a personal miracle, but these verses also speak of a national miracle. When humility comes, then God will heal the nation. If your nation needs a spiritual awakening and revival, then take this passage of scripture and pray and stand for that miracle! Begin with personal repentance and humility, and then begin to cry out on behalf of your nation! We know that God hears humble and honest prayers of faith. This heart posture is key in all circumstances when we approach God. Don’t approach life in arrogance; humbly submit yourself, repent of your sins, and watch God bring healing and salvation to your home, city, and nation!', questions: '', confession: 'You are the healer of my life and nation! We humble ourselves before you! Bring healing and salvation!' },
        { day: 11, reference: '1 Kings 17:13-16 NIV', devotion: 'When God wants to get a miracle to you, He often calls on you to take a step of faith. This woman needed provision, but the prophet asked her to first bring a gift and make an offering from the little she had. This appears heartless on the surface, but the prophet was inviting her into miracle territory. If you need supernatural provision, pray about how you can serve others and bring a sacrificial offering to God. Heaven will always direct your focus from your own pain and lack toward serving others. We often can’t receive abundance from God because we hold so tightly to what we have; be generous with your little and watch God turn it into much!', questions: '', confession: 'God is my provider and protector! I will look to serve others and stay generous in all circumstances.' },
        { day: 12, reference: 'Proverbs 4:20-22 NIV', devotion: 'God’s Word brings life and light everywhere it’s sent! The Bible says that he sustains everything by the power of His Word! To keep healthy and strong in all areas of the natural and supernatural, we will need a constant intake of God’s Word. It’s vital that we don’t just see the Bible as a nice set of teachings and quotes that we can embrace or discard but as the source of life. Every time you open up the Bible, you pour life into your soul and body. Consider the quality of the way you speak on a regular basis; do your words line up with the Bible and faith or with fear and doubt? When you hear the Word, faith comes, and when you speak the Word, power is released!', questions: '', confession: 'God’s Word is life and healing to my body and soul! I will engage and speak His Word daily!' },
        { day: 13, reference: 'Acts 4:30-31 NIV', devotion: 'God’s arm is not too short to reach into your situation and display His power. The Bible is clear that all things are possible with God; it’s God who heals, but His power is released by faith through us who believe. We’re called to partner with God in seeing the Kingdom established and miracles released. We’re not trying to work miracles in our own strength or effort, but through faith, we exercise the authority we’ve been given in Christ. Notice that the Holy Spirit came and shook that place in response to prayer! There is a direct link to our personal devotion in prayer and miracles! As you pray, you’ll begin to walk in the boldness and power of the Holy Spirit!', questions: '', confession: 'Father, in Jesus\' name, stretch out your hand to provide, heal, and deliver!' },
        { day: 14, reference: 'Proverbs 17:22 NIV', devotion: 'God wants to restore Joy to people; laughter and peace are hallmarks of Christianity. The Bible says that where the Spirit of the Lord is, there is freedom. With so many facing anxiety and depression, they need to know that God can set them free and restore hope and joy. The enemy will work to keep us stuck in hurts, sorrow, and disappointments because he knows that a heavy heart will break us down spiritually and physically. You don’t have to stay in a state of depression; you can break free! When heaviness tries to set in, call on God to break off oppression; worship can be a powerful way to get free! Once you’re free, renew and transform your mind by meditating on God’s Word.', questions: '', confession: 'I will walk in the joy of the Lord! I won’t listen to the enemy\'s lies. I will walk in freedom and experience life!' },
        { day: 15, reference: '3 John 2 NIV', devotion: 'This scripture shows God’s desire for prosperity in your Spiritual and physical health and reveals the source of both: health and wealth flow from the overflow of a healthy spirit. God focuses first on the Spiritual, which flows into the natural; he desires to see your life healthy, healed, and prospering. God’s plan for you isn’t sickness, poverty, or loneliness; his plan for you is life, hope, and abundance. This requires patience because strength starts in our soul but usually takes a while before it surfaces in the natural. The Bible says don’t grow weary in doing well because you’ll be rewarded if you don’t quit. Focus on the health of your soul and watch abundance and health flow in your life.', questions: '', confession: 'Lord, purify and renew my heart so that I can walk in your ways! Let my life reflect the prosperity of my soul!' },
        { day: 16, reference: 'James 5:16 NIV', devotion: 'If you need healing, begin with confessing your sin; this will kick the devil out of your life so that healing can flow. Sometimes, people are held in physical sickness because of demonic and spiritual oppression. After confession, ask your fellow believers to pray with you and watch the healing begin to take place. Some healings are in the heart from past wounds we’ve experienced, and some are in the physical from birth, injury, or because of disease; in all cases, God can heal! This verse reminds us of the power of agreement! Your prayers are powerful and effective! Don’t think small about the ability you have to shift circumstances as you partner with God and others in prayer!', questions: '', confession: 'Lord, I confess my sin and ask that you purify me. My prayers are powerful because I’m your Child!' },
        { day: 17, reference: 'Psalm 107:19-21 NIV', devotion: 'The power of God is released in His Word! He sent His Word and healed them! He’s still doing the same today! He’s the healer and redeemer of His people! We are on the receiving end of His words of life, and we are privileged by God to be the ones who release His Word as well! When you need a miracle, take the time to dig into the Bible and ask The Holy Spirit to give you a Word that you can pray and stand on. Then, when God shows up, performs His Word, and does the miraculous, be quick to give God the glory and honor that He deserves. As King David said, I will extol the Lord at all times; his praise will always be on my lips.', questions: '', confession: 'Lord, you hear our cry for help! Now, send your Word and Heal! I will give you all the praise and glory!' },
        { day: 18, reference: 'Psalm 103:2-5 NIV', devotion: 'These few verses will inject faith and hope into your soul no matter what you’re facing! These are verses that you can hold onto and use to pray through any giants you’re facing. The key here is to begin by keeping a heart of thankfulness. He challenges his own soul not to forget the goodness of God! Then he starts listing out the good things: God will heal, forgive, restore, and satisfy your life. This is an incredible list of the benefits of being in relationship with God. Do you have difficulty reading and believing these verses are true? Then you need to read it daily until you can approach your heavenly Father as a good God who wants to fulfill His good promises to you!', questions: '', confession: 'You are my savior, healing, and redeemer! You love to do good to your children! I am satisfied in you!' },
        { day: 19, reference: 'John 10:10 NIV', devotion: 'There is an agenda of the enemy that is clear in this verse, so if you see stealing, killing, and destruction, then you know that satan is behind it; Jesus doesn’t bring those things to us. He desires to bring you life and life to the full. Jesus doesn’t do partial or half-hearted; He gives us the best and more than enough. Jesus could have just said, I came to give you life, but He amplifies it by saying, “To the Full.” So, as you’re facing life’s challenges, know that it’s God’s desire to move you in the direction of an abundant life. If your world doesn’t look like a full life, you can pray and ask God for wisdom, strategy, and supernatural power to see that life produced.', questions: '', confession: 'Jesus, you are the giver of the abundant life! Your desire is for me to have life to the full!' },
        { day: 20, reference: '1 Peter 2:24 NIV', devotion: 'Do you need healing? Are you sick? Jesus took all of our sins, sicknesses, and diseases on himself and put them to death on the cross. Jesus made the advanced payment for our sin and disease; now, we must learn to walk it out. We receive this promise of healing by faith and begin to pray and declare His word over our lives where something is out of order. Jesus has already paid the bill for your healing and freedom, but the enemy will do everything he can to make you think they’re stuck paying the bill. Instead, take your stand on the Word of God with the paid receipts for your salvation and healing! We’re dead to our sin and sickness but alive and healed in Jesus\' name!', questions: '', confession: 'Jesus has paid for my salvation and healing! Through His death on the cross, we now live free and healed!' },
        { day: 21, reference: 'Luke 17:17-19 NIV', devotion: 'Are you indifferent or thankful for God’s goodness? We may feel that’s an obvious yes, but it requires intentionality not to forget His blessings and move too quickly to familiarity. The Bible says that a lack of honor shuts down the power of God; when we lose thankfulness and appreciation, we limit the miracles that God will do in our lives. Take time today to write down all of the miracles God has done in your life and review them when you feel a lack of gratitude for His faithfulness. Yes, you may need a fresh miracle today, but have you forgotten His goodness to you in the past? Focus on those miracles and watch joy and faith rise for today’s miracle!', questions: '', confession: 'Thank you, Lord, for your kindness, goodness, and justice! You’re the healer and restorer of my life!' },
        { day: 22, reference: 'Luke 7:12-15 NIV', devotion: 'Jesus came to bring life in every sense of that word! He brought people back to life, and He rose from the dead to show that He was Lord over life and death. He conquered hell and the death. Jesus still brings dead things back to life! It wasn’t just in Biblical times; today, there are many stories of supernatural resurrection from death. It’s key that Christians don’t see death as final. Jesus spoke of death often as sleeping because there’s an afterlife beyond this earthly life. There may be natural or supernatural circumstances that need life breathed into them again, but it will require a man or woman of faith and courage to rise up and call life back into their body in Jesus\' name!', questions: '', confession: 'You are the life giver and restorer! You bring dead things back to life! You conquered death and the grave!' },
        { day: 23, reference: 'Matthew 4:23-24 NIV', devotion: 'How incredible that Jesus healed and delivered all those who came to Him! Jesus came preaching the Kingdom and began to cast out all that wasn’t in alignment with His will. We’re called to be ambassadors of His Kingdom! When a kingdom expands, you drive out the evil so there can be peace; if a King feels there’s a threat to the people in his Kingdom, He will send his officials to eject that enemy.  As children of God, we have been given the authority to drive out satan from our family, friends, and cities! If you’re oppressed by the devil, Jesus wants to set you free today! If the enemy is messing with your family or friends, step in and eject him from their lives.', questions: '', confession: 'Jesus heals and delivers everyone who comes to Him! In your name, we’ll establish your Kingdom!' },
        { day: 24, reference: 'Psalm 147:3 NIV', devotion: 'Jesus cares about the things that have wounded your soul. He sees the traumas that have left you feeling hurt and injured mentally and emotionally. Some of the trauma you have is from abuse done to you, the pain left by your own poor choices, the pain of missed opportunity, or the loss of a loved one; God is the healer of hearts. Therapy can help you process through pain, community can carry you through the darkest seasons, but only God can heal the brokenhearted and restore the human heart to health. If you’re hurting, run to Jesus! If you’re overwhelmed, put on worship and praise and shift the atmosphere over your life. God will see you through to strength again!', questions: '', confession: 'Lord, heal my heart, set me free from the pain of the past, and restore my soul so I can walk in peace.' },
        { day: 25, reference: 'Matthew 10:1 NIV', devotion: 'This verse should stir your faith massively! Jesus, our all-powerful Savior and Lord, allows and commissions us to release His power by delegating His authority to us! You don’t heal through good vibes or well wishes; you must learn to take your God-given authority and drive out the enemy. It’s important not to assume the devil leaves on his own; we must know that he’s a leach that will keep destroying unless you take a stand and kick him out! Consider where in your life there might be areas you’ve been passively allowing the devil to mess with your life. We have greater authority than him, so take your stand, resist the devil, and he must flee from you!', questions: '', confession: 'I have been entrusted with authority over demons and all diseases through the name of Jesus and will use it!' },
        { day: 26, reference: 'Luke 13:11-13 NIV', devotion: 'Notice first that it was a spirit that had been crippling her, not just a birth defect. The demonic hold on people\'s minds and bodies can be very real and challenging, which is why we must take authority and break off those demonic strongholds. Not all sickness is from that, but we pray for discernment to see the source of the illness so we can bring the healing needed. You’ll also notice that Jesus didn’t move toward her but called her to himself, which was to call her into a step of faith and take action on that faith. Jesus then declares her freedom and lays hands on her, and she receives healing!', questions: '', confession: 'Lord, give me discernment to see any demonic activity oppressing myself or those in my world. I will bring freedom to people crippled by demonic activity.' },
        { day: 27, reference: 'Isaiah 53:5 NIV', devotion: 'Jesus went to the cross and dealt with all areas where the curse affected humanity. The curse of sin was spiritual death and brings decay to God’s intended design. We need to see the work of Jesus on the cross as the purchase of freedom and healing for our present and future. His punishment brought us peace, and by his wounds, he purchased our healing. Most of us have no problem accepting that Jesus’ death on the cross paid for their salvation, but trusting that it covers our healing is often questioned or rejected. But look at the verse, memorize it, consider all the verses on healing, and know that God desires to see your life healed and whole! He paid for that on the cross!', questions: '', confession: 'Jesus paid the debt of my sin and sickness! I am healed because He overcame disease and death!' },
        { day: 28, reference: 'Jeremiah 33:6-7 NIV', devotion: 'Our Father is a restorer of what was lost. He restores sanity, freedom, possessions, and more. While we will face difficult seasons in life, God desires that you live in peace and security. He wants to defend and guard you from the attacks of the enemy and injustice by evil people. He’s also equipped us by His Spirit to resist and push back the enemy when He comes to steal, kill, and destroy. As you pray for your healing or the healing of others, remember that it’s His perfect will to bring health and healing to your life. It’s His will to rebuild and restore the promises and territory He’s given you. Go to God with confidence in His desire for your good! If He promised it, he’ll fulfill it!', questions: '', confession: 'Lord, bring freedom, healing, and restoration of all areas and things the enemy has stolen.' },
        { day: 29, reference: 'Psalm 146:7-8 NIV', devotion: 'You’ll notice a theme in these verses, “The Lord,” it’s vital to remember that we are not attempting to work miracles and freedom in our own strength, but it’s The Lord who is healing and holding you up through His Strength and power! For those feeling beaten down and oppressed by life or an individual, know that you have a defender who cares about your case. He\'s watchful and attentive to defending the cause of the widow, the orphan, the poor, and the needy in any and all circumstances. The Lord lifts up and blesses! No matter your lowly state, trust God, live right, and watch His deliverance and redemption. God’s great love for you is what drives Him to bring total freedom!', questions: '', confession: 'The Lord is the lifter and deliverer of my life! I will trust in his faithfulness!' },
        { day: 30, reference: 'Isaiah 57:18-19 NIV', devotion: 'God is so gracious to bring peace and healing to all who come to Him! Even when our actions and attitudes don’t deserve His love. It’s clear here that God is initiating healing, guidance, and restoration out of his grace as a means of drawing his people close. His desire is for his mercy and healing to produce praise on their lips. Something we need to keep front and center is our thankfulness and praise to God for his grace and intervention in all seasons of our lives. This is also a reminder that God’s Salvation is for all people in all nations. His protection and provision aren’t limited to one people group or one individual but to all who come close to Him!', questions: '', confession: 'You, Lord, are the giver of peace and healing! I will call on you and watch your work deliverance!' },
        { day: 31, reference: 'Matthew 9:35 NIV', devotion: 'A New Kingdom means a new King; with that new Lord comes new rules and ways of doing things. Jesus came to bring in a new Kingdom, which was more powerful than the previous one. The new kingdom brings life and hope, while the last kingdom is one of darkness and pain. As with any kingdom, the King can give authority as he sees fit. In the same way, Jesus is our King and gives or delegates authority to us to establish and facilitate His Kingdom on earth, which means that when something is out of alignment with His will, we must step in and use our God-given authority to drive out the enemy as Jesus did. Jesus proclaimed the good news and then healed all sickness.', questions: '', confession: 'I will proclaim the good news of your Kingdom! I will exercise the authority that you’ve given me!' },
        { day: 32, reference: 'Mark 5:25-29 NIV', devotion: 'This engagement that a suffering woman has with Jesus tells us so much. First, we all deal with this reality: the fatigue of trying and getting nowhere in your health or any area of your life. It’s easy to give up, but her persistence teaches us to never give up on our healing! She then hears that Jesus is coming through, and faith is stirred in her heart to believe that her life can change with just one touch from Jesus! In faith, she pushes past the acceptable norms of the day and the opinions of the crowd to fight for her miracle. Jesus rewards her faith; He heals and forgives her! Where do you need to strengthen your determination and believe again for a miraculous touch from Jesus?', questions: '', confession: 'One touch from Jesus can heal and restore all things!' },
        { day: 33, reference: 'Luke 4:18-19 NIV', devotion: 'Jesus came on a mission to establish the Kingdom of Heaven once again on earth; He came with a message of good news and with power! He didn’t come with just nice teachings, but with a miraculous demonstration of the Kingdom He was preaching. Jesus came to bring us a message of Good News, restoration, and freedom to those oppressed by the devil and to proclaim the season of God’s Favor! This is incredible! No matter what you’re facing right now, Jesus came anointed by God to fulfill and answer everything that plagues the world! He created you and knows the battle you’re in; He’s also powerfully equipped to meet your needs!', questions: '', confession: 'Jesus came with Good News and Power! We will preach the Good News and demonstrate its power!' },
        { day: 34, reference: 'Luke 4:38-39 NIV', devotion: 'I love that Jesus cares about the spectacular miracles like raising kids from the dead and the unseen miracle of healing a fever. This miracle reminds us that no matter what you’re facing, you can go to God and ask Him for it. He doesn’t dismiss your seemingly small requests; He is attentive to it all. Also, we get a window into how Jesus works miracles that we can engage with. Notice that Jesus speaks directly to the sickness, rebukes it, and tells it to leave. Is there a fever, cancer, fear, or anxiety? Lean in and rebuke that sickness or spirit and command it to go! Don’t be timid or soft with sickness; take your authority that Jesus gave you and rebuke it!', questions: '', confession: 'You care about all my requests! I will stand and use the authority you’ve given me to rebuke sickness!' },
        { day: 35, reference: 'Luke 4:34-35 NIV', devotion: 'There is a supernatural realm. The unseen realm isn’t just in the afterlife; it’s right now! The supernatural world is all around us. It is from the unseen that all of the visible has come. So, the demons we can\'t see were able to see that Jesus was not just a carpenter, but the Son of God. Jesus then had to confront and cast out the demon from the individual being tormented by the evil spirit. Don’t be fooled into thinking the only influences in the world are natural; there are unseen forces for good and for evil. The good news is that in Jesus, we have greater authority than any of the demonic interference that may try to come. It says Jesus prayed sternly; stir up your spirit and be bold!', questions: '', confession: 'The unseen has created the seen! We take authority over the natural and supernatural world in Jesus\' name!' },
        { day: 36, reference: 'Luke 4:40-41 NIV', devotion: 'If you’re sick or hurting from any ailment, come to Jesus! We don’t always know what to do or how we’re going to make it through, but decide now that your first move will always be to bring it to Jesus! It is important to note here that it doesn’t say He healed some who came to Him, but that He healed ALL! Read that over and over again to build your faith for the miraculous! Jesus healed a range of illnesses, letting us know that God doesn’t just heal some things, but others are beyond His reach; no, Jesus heals ALL sickness and disease! Nothing is beyond his concern and His power! Come to God boldly in prayer and bring your requests to Him. Jesus is our healer!', questions: '', confession: 'Jesus, you are the healer of every kind of sickness! Nothing is beyond your care and power!' },
        { day: 37, reference: 'Luke 6:19 NIV', devotion: 'Jesus has more than enough power for all to be healed and restored! It was faith that drew out the power from Jesus, and it’s the same today! Do you need a miracle? Go to Jesus with faith and expectation of healing! Notice also that there was a physical flow of a supernatural force. The healing power was invisible to the eye, but people physically experienced it as they were healed. It’s the same for you when you’re praying for someone to be healed; there will be a power from Heaven that flows out of your body as you pray. People experience it in different ways, and sometimes you may not feel it, but know that when you lay hands on people, there is a flow of power released in Jesus’ name!', questions: '', confession: 'Faith draws on the power of God! The Holy Spirit will flow through me to heal as I lay my hands on them!' },
        { day: 38, reference: 'Psalm 91:1-2 NIV', devotion: 'Do you or someone you know need rest? Do you need peace? You’ll find that when you rest in the shadow or presence of God. When you’re spending time in the presence of God through prayer, worship, and the Word, you’ll find that peace comes. We’re often weighed down by the never-ending tasks, to-dos, difficulty, and challenges, and the devil wants you overwhelmed and depressed because that slows down your calling and purpose. So, that’s where we must learn to trust and rest in the presence of the almighty! When I’m in His presence, I’m shielded from the shots of the enemy, and I get my strength renewed again. Take time to be with Jesus today!', questions: '', confession: 'God, I put my trust in you! I will rest in your presence and find hope as I wait on you!' },
        { day: 39, reference: 'Malachi 3:10-12 NIV', devotion: 'When praying for financial provision or breakthrough, it’s vital to ask the honor and tithing questions. Are you honoring God with the first 10% of all that you make? If you’re a tither, you can claim the promises and pray in alignment with the open heaven over your lives. You can also pray God’s promise of protection over your life! God promises to rebuke the devourer! If you’ve been having too many deals stolen from you and you’re a tither, I want to encourage you to call on God to rebuke the enemy off your life, finances, and business. Also, when was the last time you brought an offering beyond your tithe just to honor God? When you honor God, he says we’ll have a blessed and delightful land.', questions: '', confession: 'I will honor the Lord in faithfully bringing my tithes! I will stand on his promise of blessing and protection!' },
        { day: 40, reference: 'John 14:27 NIV', devotion: 'Peace! What a beautiful word; it feels like most of the world is chasing peace but often missing out on it. Why? Because we’re seeking peace from the wrong source. Even Christians will ask God for “material things,” assuming that when God does that miracle, then they will have peace, but that’s not how peace works. Peace is an inside-out work of God, not an outside-in work. If you’ve been fighting to create circumstances that will give you rest, it’s time to lay that down and focus on Jesus. He will break off demonic oppression and give you true peace. You don’t earn peace or work for peace; Jesus gives it to you as part of being with Him.', questions: '', confession: 'Jesus, I receive your peace! Nothing on earth can take my joy. I will put my trust in you!' },
        { day: 41, reference: 'Matthew 10:8 NIV', devotion: 'It’s your turn! Often, people assume that seeing someone get healed is only what the pastors or people with a lot of faith do, but Jesus tells all his disciples to heal the sick! To raise the dead! To drive out demons! This is the work available to all followers of Jesus! The world around us needs all believers to operate in the power we have available as ambassadors of the Kingdom of God. Notice the last part of the verse: freely you’ve received, freely give. The gift of supernatural power is something to freely exercise on others\' behalf. If you’ve received salvation, pass on the good news! Since you’ve received power, use that to heal and set others free in Jesus\' name!', questions: '', confession: 'I have power and authority over the enemy! I will bring freedom and healing in Jesus’ name!' },
        { day: 42, reference: 'Matthew 9:23-25 NIV', devotion: 'Because Jesus knew that death wasn’t final, He could see beyond the natural limitations of death. When we’re facing difficult diagnoses or tragedies, it’s key that we keep our words in alignment with God’s Word! Are you speaking words of life or death over your circumstances? When we read the Bible, we develop a faith-filled vocabulary. Notice how Jesus takes control of the atmosphere by kicking out the people without any faith. You may need to do that in your life when you’re believing for a miracle. Well-meaning people want to get into the depths of despair with you, but if you’re standing for life, put them out of the room and keep people close who will believe with you!', questions: '', confession: 'Lord, give us eyes to see how you see! We will stand in faith and pray in alignment with your Word!' },
        { day: 43, reference: 'Matthew 9:27-30 NIV', devotion: 'These blind men knew that the messiah was coming from King David’s line, so when they call him son of David, they are affirming His power and authority! What are you saying about who Jesus is? Also, notice that Jesus asks the men if they believe He can heal them. This is a key question that God asks any of us that come to him for a miracle. “Do you believe that God can do it?” Jesus always takes us on a journey of faith and trust with Him! When they declare, yes! I believe, then, He heals them and declares it was their faith that healed them. Well, technically, it was Jesus, but faith was the conduit to carry the healing from the supernatural to the natural.', questions: '', confession: 'Jesus, I believe that you are the Messiah! I trust that you are able and willing to heal and deliver!' },
        { day: 44, reference: 'Philippians 4:6-7 NIV', devotion: 'It’s so easy to rush into fear! It’s common to second guess yourself and even question God if we allow anxious thoughts to overtake and set up camp in our minds. We know anxious thoughts will come, but we don’t have to dwell on them. It says don’t be anxious but pray. That’s the act of facing God with faith and expectation. When we do that, we’ll find anxiety fades and peace and faith return. Also, make sure that in all your requests, you remain thankful and full of gratitude for what He’s done and all He will do. Then an incredible thing happens: your prayer and faith directed towards God will break off the spirit of fear and release a shield of peace that protects your life!', questions: '', confession: 'I will not live in fear; I will turn the attention of my mind and heart towards God and His goodness!' },
        { day: 45, reference: 'Matthew 17:14-18 NIV', devotion: 'Healing and deliverance is an act of mercy; we should never see someone suffering and not want to extend our hand to bring freedom. That is always the heart of God. This man and the disciples can’t get his son set free. Jesus then points to the perversion and faithless qualities of the culture as to why the boy wasn’t healed the first time. Jesus then rebukes the demon, and the boy is free! When you’re praying for others or your own breakthrough, ask the Holy Spirit for insight as to what the strong-hold is that’s keeping the bondage or sickness from breaking. Then go again in faith and expectation of a supernatural encounter with Jesus!', questions: '', confession: 'Lord, I confess any sin or unbelief that’s holding me back from ministering healing and freedom!' },
        { day: 46, reference: 'Mark 1:40-41 NIV', devotion: 'I love this passage! Jesus is insulted by this person’s question. His indignation comes in response to someone questioning his heart and desire to free them from their suffering. His reaction is because His good plans for people are in question. So, when you come to Jesus for healing or you’re praying for someone, don’t question Jesus’ desire to bring healing, freedom, and breakthrough for the individual. Like a good Father, He always wants the best for His kids. While there are times when God brings an answer a different route or at a different time than we expected, we should never question the heart of God to heal and bring restoration in this life or the next.', questions: '', confession: 'Jesus, you are good, and You do good things for your people! You are able and willing to heal and deliver!' },
        { day: 47, reference: 'Mark 3:1-5 NIV', devotion: 'You’d think this was a rhetorical question: is doing good or evil lawful? But they couldn’t answer the question because it challenged their stubborn unbelief. So, Jesus overrides their religious pre-conceived ideas about good and evil and brings healing to the man suffering. To activate the supernatural power of God in your life, you’ll need to reject wrong teaching that healing isn’t for today. Jesus heals, and he is a healer! Jesus heals all kinds of people as well. He heals Christians and people who reject him so they will wake up to the truth of the Gospel. Don’t let religious lies stop you from believing for your miracle or from praying for someone else’s miracle!', questions: '', confession: 'Jesus is the same yesterday, today, and forever! He was and is our healer!' },
        { day: 48, reference: 'Mark 6:4-5 NIV', devotion: 'God is all-powerful, yet this passage shows a season where His power was limited. This reveals that we are often the biggest limiter in God’s ability to work in and through our lives. Jesus says he did minimal healing work in this city due to the lack of honor. Because the people saw him as just the carpenter rather than Lord, it limited his power in their lives. Is your view of God limiting His power in your life? Do you give Jesus the honor and reverence due Him? Have you begun to treat Him as common and take him for granted? It may be time to stir up honor and worship again to put Jesus in His rightful place in your life so His power can flow to you!', questions: '', confession: 'Jesus, I honor you and put you first in my life! You are my Savior and King! My life is yours!' },
        { day: 49, reference: 'Matthew 8:6-10 NIV', devotion: 'What a powerful picture of someone who understood how the supernatural realm operates and who has authority. This leader saw Jesus as the King that He is; he saw Him as the one who could command the armies of Heaven and command demons and sickness to leave with just a Word! Jesus is shocked by this honor and faith enough to shout it out. In the Army, the word of the General is final, and the orders are to be obeyed. In the world, Jesus is the King, and we are His commanding officers to carry out His Will; our words are to be fully obeyed on His behalf. Demons must leave at your command, and sickness must go because of your submission to Jesus.', questions: '', confession: 'Jesus, you are The King; all heaven and earth respond at your command! Just Say The Word!' },
        { day: 50, reference: 'Acts 3:2-8 NIV', devotion: 'As followers of Christ, we carry something from Jesus that we have the authority to give away. We’ve received power from Him, and we have the ability to release it. Peter and John said, “What we have.” That’s a powerful statement and one to ask The Holy Spirit for a greater revelation of what you have to give. When you’re praying for someone, don’t just say, “Lord, give them,” but understand that Jesus already gave it to you, and now it’s your turn to give and release the Kingdom to them in Jesus\' name! It’s also a reminder that we need decrement to see people’s primary needs; the man asked for money, but they gave him a whole new life. Release to people what they really need from God!', questions: '', confession: 'Jesus, we will freely release the power of God to others that you’ve given to us! Lord, increase our faith!' },
        { day: 51, reference: 'John 14:12 NIV', devotion: 'Jesus wants you and me to boldly carry out the mission He gave us and walk in the full power and authority that He walked in. Jesus even goes as far as to say that we’ll do even greater works! I want you to fully embrace the bigness of this idea! I want you to confess this verse and meditate on it until you believe it! The more you stir up your faith to believe this passage, the more you’ll pray bold prayers, the more you’ll see people set free, and the greater provision you’ll see flowing into your life! Jesus is waiting to partner with you by His Spirit to do the miraculous works of the Kingdom; that’s why we’re called believers; we’re the ones who take Him at His Word and believe!', questions: '', confession: 'I choose to believe! His power is available to those who believe and step out in faith!' },
        { day: 52, reference: 'Revelation 21:4-5 NIV', devotion: 'We know that Jesus heals and that He came to bring the Kingdom of Heaven to Earth! In this life, we’re going to face trials, pain, sickness, and even death before our time. In this life, we’re going to take our stand against the work of the enemy, and we’ll experience both victories and defeats. But we are heading toward an eternity that is free from all sickness and disease! A new heaven and new earth that have ejected satan and death fully out. All of the Kingdoms of this world will become the Kingdoms of our God! We will not always have to contend with sin and death; there will be an eternal reconning and restoration of all things! Life will have the final word!', questions: '', confession: 'Jesus, we pray and work towards your soon return and the establishment of your Kingdom in full!' },
      ]
    },
    new_believer: {
      title: '52 Bible Verses for New Believers',
      subtitle: 'Fifty two devotionals to build your faith',
      cover: '/assets/plan-cover-new-believer.jpg',
      days: [
        { day: 1, reference: 'Genesis 1:1-3', devotion: 'These few verses give us confidence and clarity about our Creator and our intentional design. Many people live life confused and void of meaning because they’re looking for life’s answers everywhere but the Source. When you need answers and help, go to the Author and Creator; no one else can better lead and inform you. God is the all-powerful Creator, and He also chooses to be with us and invites us to connect and communicate with Him. God is powerful, and He’s also very present in this moment with you!', questions: 'Have you considered how incredible creation is? Have you stopped to thank God for life and all He’s created? Have you gone to Him with your questions?', confession: 'There is one true God! He made the heavens and the earth. By His Word, He created everything we see.' },
        { day: 2, reference: 'Genesis 1:26-27', devotion: 'You are not just an evolved animal or a cosmic explosion; you have been intentionally handcrafted by God to be in relationship with Him. No other being on earth has that honor. This is why we refer to God as our heavenly Father, because He created us. You have God’s identity, which is why humanity carries another level of worth and value than animal or plant life. This identity is also the main thing the devil tries to attack to get you to question your value and purpose. However, you can wake up every day with confidence knowing that you are valued and loved by God.', questions: 'How does it feel knowing that you were created with intention and design? What do you feel called to do?', confession: 'I am a child of God and carry His name. I walk out His mission here on earth.' },
        { day: 3, reference: 'Genesis 8:22', devotion: 'The world God created for us is not by chance or in chaos. God’s specific and intentional design holds the universe and the world in which we live in perfect harmony and peace. This is excellent news on a cosmic scale, but it also has very specific implications for your life. It’s important to remember that your life isn’t by chance; God has intentional plans for you. He created our world to support and provide for all life on earth until Jesus returns. You can trust Him!', questions: 'Are there ever times you feel out of control or uncertain about God’s plan or timing? How does it make you feel knowing God is so specific and intentional?', confession: 'God, you are specific and perfect in all that you do! All the principles you’ve established will succeed.' },
        { day: 4, reference: 'Romans 3:23-24', devotion: 'Adam and Eve were the first people God made, and He gave them the choice to love and obey His Word and live or to choose death by sinning against God. They chose to disobey, and as a result, we are all born into sin. The culture says, “Everyone is basically good.” While it’s true that everyone is loved, we are all sinful. Only a sinless sacrifice could take away our sins. The Good News is that we are *freely *made holy through what Jesus did on the cross. We don’t earn our way to God; He came and rescued us!', questions: 'What was your perception of sin growing up? Did anyone tell you about needing a Savior? Have you received the grace of Jesus to cover your sin?', confession: 'I was born into sin, but thank God I don’t have to stay in sin. I am free and forgiven because of Jesus.' },
        { day: 5, reference: 'John 3:16', devotion: 'This is one of the most well-known verses in the world because it gives us a simple overview of how valuable we are to God and what Jesus did to provide salvation for us. Jesus left heaven and came to earth as a man to pay the price for all of humanity’s sins. Jesus didn’t come to earth because He was mad at our sins but because He was in love with the sinners. God gave His very best to rescue us. We are not an afterthought to God. Even though it was our sin that separated us, it was His grace that brought us back.', questions: '', confession: 'I am loved and valuable. I have put my hope and faith in Jesus!' },
        { day: 6, reference: 'Ephesians 2:8-9', devotion: 'Your salvation from sin is not something that happens by being a good person. You may have heard that if your good deeds outweigh your bad deeds, that will get you into heaven. However, the Bible is clear that we’re saved and forgiven because of the grace of God displayed on the cross. Jesus’ innocent blood shed on the cross is what paid for the debt of our sins. So naturally, we want to live in a way that honors that sacrifice—but human efforts can’t save you; that’s why Jesus had to come!', questions: 'Did you know that your good deeds don’t save you? How does knowing that God paid for all your sin make you feel?', confession: 'I am loved and forgiven by God. His grace has saved me.' },
        { day: 7, reference: 'Romans 10:9-10', devotion: 'Choosing to follow Jesus moves you from the kingdom of Satan to the kingdom of light! We are born into cruel submission to sin and the devil; all that’s needed to step from darkness to light is to confess Jesus as Lord and believe what He did for you on the cross and that He rose from the dead—and you will be saved! This is incredible and kind news. It’s like the thief on the cross next to Jesus; he reached out to Jesus and said, “Remember me when you come into your kingdom” (Luke 23:42), and at that moment, he was saved because he aligned his life with the Kingdom of heaven.', questions: 'Have you confessed that Jesus is your Lord? When did you know that Jesus was calling you? Who have you told about your decision to be a Christian?', confession: 'I declare that Jesus is my Lord; I will live for Him.' },
        { day: 8, reference: 'Ephesians 6:10-14', devotion: 'There is a spiritual battle between demonic forces and the followers of Jesus here on earth. It’s not hyperbole; it’s a real battle—but the good news is that God didn’t leave us without armor and weapons for this battle. Read all of Ephesians 6:10-18 [^c2][^c3]to know all of the pieces of armor. You’ll notice that the armor is for defending and attacking. You aren’t defenseless against the devil’s plans to destroy you. It’s important to take your stand against the enemy’s attack on your life, family, city, church, and friends. When you stand up with the armor of God, you will defeat the enemy!', questions: 'Have you sensed the spiritual battle? Have you had a negative demonic encounter? What’s the main piece of armor that you need to work on?', confession: 'I am equipped to fight and defeat the enemy.' },
        { day: 9, reference: 'Luke 9:23-24', devotion: 'Being a Christian isn’t a multiple-choice box that you check on a heavenly entrance exam but then live your life however you want. Because He gave everything on the cross for us, we now live fully surrendered to His will and purpose. As a follower of Jesus, I’m laying down my life and picking up my cross to follow Jesus—daily. Don’t try to save your reputation and agenda; instead, lay them down in worship to Jesus. When you surrender your whole life to Jesus, you truly start living!', questions: 'Is there any part of your life you haven’t yet surrendered to God? What is the greatest sacrifice that you’ve had to make in following Jesus?', confession: 'Jesus, I will lay down my life and pick up my cross daily to follow you and fulfill your mission.' },
        { day: 10, reference: 'James 5:13-14', devotion: 'These verses are packed with instruction on worship, prayer, healing, and the power of the church community. We’ll focus on the truth that God wants you to come to Him when you’re in need. You don’t have to be afraid of coming close to God; you’re not bothering Him with your requests. When you pray, you enter a different kingdom where we pray instead of worry, we praise instead of fear, and we trade hopelessness for joy. Never lose your appreciation for His answered prayers.', questions: 'What do you need to pray to God about today? What’s one thing you’re thankful for today? What miracle are you praying for today?', confession: 'God, I am thankful for your goodness. When I call on your name, you will answer me.' },
        { day: 11, reference: 'Matthew 6:33', devotion: 'God has established order and priorities within the kingdom of God, and when you put the right things in the proper order, you’ll experience a greater flow and blessing. So, as a believer, when you shift your focus from building just your own life or kingdom and start asking, “How can I build the kingdom of God with my life?” that’s when your life, purpose, and dreams really begin. Initially, it will feel counterintuitive, but once you embrace a Kingdom-first mindset, you’ll unlock the flow of heaven.', questions: 'Is there anything taking greater priority in your life than God’s kingdom? What area do you need to adjust focus on: time, money, or something else?', confession: 'I will build and advance the kingdom of God on earth with my life, work, and relationships.' },
        { day: 12, reference: 'Colossians 2:12 (esv)', devotion: 'Jesus was baptized in water, and we as believers are called to follow His example and get water baptized. This means to be fully submerged underneath the water. Why? Because we are symbolically representing Jesus’ death, burial, and resurrection. When we get baptized, we publicly claim Jesus and commit to living fully surrendered to Him. Your life is not your own; you’re living for kingdom purpose.', questions: 'Have you taken the step to get water baptized yet? If yes, what was it like? Is there any area of your life that needs to be surrendered today?', confession: 'I am a follower of Jesus. I am dead to my old life of sin and alive to Jesus and His purpose!' },
        { day: 13, reference: 'Revelation 3:20', devotion: 'Jesus gives us a window into the heart of God for us. First, Jesus wants to come into your life. He doesn’t want to stay as a distant spectator; He wants to be personally engaged in your world. He also shows that we have to invite Him in. He’s knocking on the door; only you can choose to open it. And once you open the door, I love how He doesn’t just want to give you a salvation ticket to heaven and move on to the next door; no, He says, “I’ll come in and share a meal with you.” That’s the heart of God: to be with you!', questions: 'Have you invited Jesus into your heart? If not, today is an incredible day for it. Do you create space in your day to spend time with God?', confession: 'Jesus, you are welcome into every area of my life.' },
        { day: 14, reference: 'Psalm 100:1-5', devotion: 'You’ll find that when you come to God in worship and with a thankful heart, it brings you right into His presence. Worship, praise, and thankfulness are like a special access code to heaven. That’s the foundation of honor that so much of the kingdom of God is built on. Do you have a heart of thankfulness for all He’s done in your life? God does want to hear all your requests, needs, pains, and victories. But what is the first thing we bring to God: our complaints or our praise?', questions: 'How comfortable are you in worship? Have you taken the step to worship and sing in church? Reflect on who God is and praise Him this week.', confession: 'I will worship and honor God with everything that is within me.' },
        { day: 15, reference: 'Matthew 22:37-39', devotion: 'Jesus makes it very simple and clear as to what are the most important things we should know and do as a believer. First is to love God fully and passionately with all you have. How do we do that? By loving God with our work, with our family, with our dreams, and with everything. Then it’s to love others. God makes it clear that we can’t just love God and mistreat people. To love God is also to love His kids. Loving others the way God loves you is key to how we love Him.', questions: '', confession: 'I will love God with every part of my life, and I will love others selflessly.' },
        { day: 16, reference: 'Matthew 6:14-15', devotion: 'Forgiveness is one of the primary hallmarks of Christianity. Because Jesus forgave us fully and completely of our sins, He requires that we forgive others. While we didn’t earn our salvation or have to work for it, there is an expectation from God that we extend grace to others as He extended it to us. When you have difficulty letting go of what someone did to you, take time to pray and remember His goodness toward you. Ask God for peace and help to extend grace toward others. It’s not about them deserving your forgiveness, just as we didn’t deserve or earn Jesus’ forgiveness.', questions: 'Who in your life do you need to forgive today? How have you learned to overcome offenses?', confession: 'I have been forgiven and will extend grace to others.' },
        { day: 17, reference: 'Hebrews 11:6', devotion: 'Without faith, it’s impossible to please God. Faith is the currency of heaven. It’s the conduit for bringing things from heaven to earth. It pleases God because faith is believing He is who He says He is, and it’s drawing on Him in faith for the unseen or the impossible. God wants you to come to Him with great expectation. Never feel like you’re asking God for too much. Instead, pray and believe for that miracle, and trust Him to fulfill it. Pray like He’s about to answer your prayer!', questions: 'When was the last time you prayed a bold prayer of faith? What prayer did you stop praying because of fear that you need to start believing for again?', confession: 'God, I trust you and put my faith in you. You will fulfill what you said you would do.' },
        { day: 18, reference: 'Romans 12:2', devotion: 'Every day you have a choice as to what pattern you’re going to model your life after. Will it be the pattern of the world leading to death or the pattern from God found in the Bible that leads to life? As you follow Jesus and His ways, your life will be transformed little by little. God’s Word has a pattern to build great friendships, marriages, businesses, governments, and each area of our lives. The key is to stay committed to following God’s pattern even when you feel you’d rather follow the world’s pattern. Only one leads to life.', questions: 'What’s a key pattern of thinking or doing that you’ve changed since becoming a Christian? What’s one negative pattern you still need to change?', confession: 'I will build my life on the pattern of God’s Word. I will know and fulfill God’s will for my life.' },
        { day: 19, reference: 'Psalm 1:1-3', devotion: 'These verses end by letting you know that God’s desire is that you would produce fruit and that you would prosper. But so much of that hinges on who you allow into your world and what counsel you let in. Who are you walking with? Who are you sitting with? Be very intentional with the friends and associates you allow to speak into your life. The direction of our closest friends will impact the direction of our lives. So, observe the fruit or attitudes in people before you choose to listen to their counsel.', questions: 'Who are the closest friends or mentors speaking life into you? Is there anyone that you need to remove from your inner circle?', confession: 'I will walk with those who prioritize God’s ways. I will prosper and thrive in every season.' },
        { day: 20, reference: 'Matthew 7:24-27', devotion: 'What foundation are you building your life on? Jesus calls us to build on the only sure and solid foundation, which is His Word. Following the ideas and thoughts from this world is like building your house on a shaky and uncertain foundation. Your life, like a house, can only stand when it’s built on a rock-solid foundation. If you’ve been building on the lies of culture, the good news is you can change that by reading, listening to, and obeying the Bible in a way that will build your sure foundation.', questions: 'Is there any area of your life that seems to be falling apart and needs to be rebuilt on the foundation of God’s Word? [^c7]What Bible verses will you commit to memorize?', confession: 'My life will be built on the foundation of God’s Word.' },
        { day: 21, reference: 'Acts 1:8', devotion: 'Jesus didn’t just save us from sin and leave us powerless on our own; He sent us the Holy Spirit. When you are filled and baptized with the Holy Spirit, you’ll receive power, peace, wisdom, and all the fruit of the Spirit. The Bible calls the Holy Spirit our counselor, guide, comforter, and the one who gives us power. Through the Holy Spirit, we can operate in power and authority in Jesus’ name. He also empowers us to be His witnesses on earth so that many more can come to salvation in Jesus. Ask Jesus today to baptize you with the Holy Spirit and power!', questions: 'Have you been baptized with the Holy Spirit yet? How has it changed your life? Who can you share your faith with this week?', confession: 'I am filled with the Holy Spirit and will share my faith.' },
        { day: 22, reference: 'Luke 16:10', devotion: 'One of the vital principles of promotion in life is to be faithful with what you have now, even if it’s not much. God is good and doesn’t want to bless you beyond what you are ready for, so He’ll watch how you handle “little” before you’re promoted to “much.” Sometimes we assume that once we’re given more or blessed with more, then we’ll begin to level up our faithfulness with what we have, but God waits and watches how you care for the current friends you have or the job you have or the home you have or what you’ve done with the calling He’s given you so far; based on that, you’ll see the blessing of God!', questions: 'How are you currently handling what you have? Are you multiplying what you’ve been given?', confession: 'I will be faithful and multiply what I am given.' },
        { day: 23, reference: 'Psalm 119:11', devotion: 'When you put God’s Word into your heart, it has a way of guarding, insulating, and protecting your life against the enemy. The way that you hide God’s Word in your heart is by reading it often—daily if you can—and deciding what you’re going to apply from what you just read. Another great way is to choose key verses, like the ones in this book, to memorize. Then when you’re faced with difficult moments, the Holy Spirit will bring those verses to memory, and they will be a guard against the enemy.', questions: 'What’s your favorite verse in the Bible so far? When can you plan daily to read the Bible? Check out reading plans on the Following Jesus app.', confession: 'Your Word guards, protects, and guides my life.' },
        { day: 24, reference: 'Matthew 11:28', devotion: 'What an incredible invitation from Jesus! When you face difficulty, pain, tragedy, fatigue, bad news, or anything burdening you, Jesus says to come to Him! You don’t have to carry everything alone; you can bring it all to Jesus. What is your default when you face difficulty? Do you run to God and His Word, or do you turn inward and try to carry it all? Or do you turn to other vices to numb the pain? Get good at consistently bringing your fears and worries to God, and watch how your peace and joy return.', questions: 'What’s the biggest thing burdening you right now? What fears are trying to mess with your peace? Have you brought them to Him yet?', confession: 'I will bring my worries and fears to Jesus and find peace and strength.' },
        { day: 25, reference: '1 Corinthians 11:23-25', devotion: 'Jesus calls us to take communion consistently. What is that? It’s when you eat bread and drink wine or juice to represent what Jesus did for us on the cross. The church you go to may have the whole church take communion often, and you can also practice this on your own. But I want to encourage you not to take that moment lightly; it is a powerful declaration of the power of the blood of Jesus over your life and circumstances—because it’s the blood of Jesus that saves, heals, covers, and protects you. When facing oppression from the enemy, take communion and stand against his attack.', questions: '', confession: 'Jesus, your blood heals and covers my life.' },
        { day: 26, reference: 'John 13:35', devotion: 'Your faith isn’t supposed to be hidden or silent. There are many ways that our faith is made public, and how you love others is one of those key factors. When a non-believer sees the way you love them and the love the people in your church have for each other[^c9][^c10], that will be a massive testimony to them. The world bases love on performance and what others can do for you, but as believers, we love and receive everyone—which is so shocking, it attracts people to want to follow Jesus!', questions: 'Do you have close Christian friends? Are you displaying the love of God in the ways you treat and connect with your friends?', confession: 'I will live a life of love! I will love, honor, and encourage my friends and those in my world.' },
        { day: 27, reference: 'Acts 2:1-4', devotion: 'The Holy Spirit is not just some little voice on your shoulder trying to help you make better decisions; He is the Spirit of God! The Holy Spirit wants to empower and fill your life. Notice how the disciples were in unity and prayer, waiting for the Lord to send them the promised gift of comfort, help, and power. The Holy Spirit goes where He’s invited. So, wait on the leading and power of the Holy Spirit and begin to step into your day with confidence and authority that God’s Spirit is with you!', questions: '', confession: 'Holy Spirit, I invite you to come and fill every area of my life.' },
        { day: 28, reference: 'Ecclesiastes 4:9-12', devotion: 'We are designed by God for relationships. Having great people in your life isn’t just a nice idea; it’s essential for your development and for fulfilling your purpose and calling. Don’t try to be an island in life; don’t try to do it all alone. Find great people you can link arms with and go after your purpose. This is important in your time of need, but it is also so that you can position yourself as the friend someone else will need. Yes, there may be times when life feels faster on your own, but if you want to go the distance, it will require friends.', questions: 'When have you fallen and had a great friend help you back up? Who do you need to build a friendship with?', confession: 'Two are better than one. I will add value to others.' },
        { day: 29, reference: 'James 4:8', devotion: 'What an incredible invitation to all of us! The Creator of the heavens and the earth has called us to be close to Him. You don’t need to be religious or distant. Instead, come close to God. How do we do this? We get close to God by spending time with Him. We can spend time with God in prayer, in worship, and by reading the Bible. You’ll find that as you step closer to God, the presence and power of God will meet you and give you strength.', questions: 'Is there anything stopping you from spending time with Jesus? What is your favorite way to spend time with God?', confession: 'My heavenly Father wants to be close to me. I will chase after His presence.' },
        { day: 30, reference: 'Philippians 3:7-8', devotion: 'There’s nothing that compares to our ability to be in a relationship with God. No matter how many great accomplishments you might have over your life so far, remember that none of that earns your way to salvation; it’s only what Jesus has done that matters. So, like the Apostle Paul, choose Christ and the life He has for you over all earthly possessions. Nothing else will satisfy and bring fulfillment to your life like knowing Jesus!', questions: 'Was there anything you had to give up when you came to Christ? What’s the greatest accomplishment you’ve achieved from an earthly perspective?', confession: 'I surrender all of me to follow Jesus. Nothing is greater or more valuable than Him!' },
        { day: 31, reference: 'John 16:33', devotion: 'Becoming a Christian won’t necessarily make your life easier; there will always be trouble in our world because of sin. Yes, there is a lot of self-inflicted pain that we begin to avoid due to living according to the Bible. However, because Satan is still roaming the earth, there are going to be attacks that we need to be aware of and know how to deal with. Jesus says, “You’ll have trouble, but take heart or have courage and peace because I have already won the victory!” Now, all we need to do is fight the battle.', questions: 'Are you more naturally stressed out or at peace in life? What’s the battle you’re fighting right now that God is helping you overcome?', confession: 'No matter what trouble comes my way, I will have peace and walk out the victory Jesus has already won.' },
        { day: 32, reference: 'Mark 11:24', devotion: 'Jesus shows us the heart of God to engage and respond to us. First, He calls us to pray and ask Him for things. Don’t assume you’re bothering God, because your heavenly Father loves you and wants to respond. Then Jesus calls us to the next level by challenging us to believe. The fight for answered prayers is in the believing! Most things you ask God for will be contested by the devil and delays. Can we keep trusting God and believe He will do what He says even when the natural circumstances don’t look good?', questions: 'What are you praying and believing God for right now? Is there any prayer or dream God has given you that you’ve lost heart and stopped believing for?', confession: 'In faith, I will boldly ask God for my needs and desires.' },
        { day: 33, reference: 'Matthew 28:18-20', devotion: 'As followers of Jesus, we’re not just here taking up space; we’re on a mission. The mandate to increase and take dominion began in the Garden of Eden with Adam and Eve, but Jesus calls us back to that mission when He says to make and increase disciples on the earth. There are people that God has put us around who need the message of salvation through Jesus. We know that Jesus does the saving, and then it’s our responsibility to do the discipling, which is to teach people how to obey and follow Jesus and make more disciples.', questions: '', confession: 'I will own the great commission from Jesus to make disciples of all nations, starting with my family.' },
        { day: 34, reference: 'John 10:10', devotion: 'The signature of God is life! When you’re trying to determine if God is involved in something, look for signs of life. The enemy will continue to take from you; he’ll try to kill your life, your potential, and your hope. His tactics will be mostly subtle. He won’t come in and try to get you to accept his poison, but he’ll try to get you to think and speak thoughts and words of death. This scripture is also a way to reflect on your attitudes and actions to see if they are flowing from God or the enemy. Is what you’re doing in your life producing life or death in others around you?', questions: 'Is there any area of your life that keeps producing death? How has following Jesus changed your life?', confession: 'Jesus, all your ways produce life—life to the full.' },
        { day: 35, reference: 'Ephesians 1:20-23 (msg)', devotion: 'Jesus is[^c13][^c14] powerfully active on the earth today through the Church. The gathering of believers at church is not just a religious gathering but the active body and extension of Jesus here on earth! You are an essential part of the body of Jesus and His plan to seek and save the planet. Jesus has chosen to primarily speak and act through His Church on earth. While we go to a church weekly to worship and hear the teaching of God’s Word, we don’t just *go* to church—we *are* the Church. So, be ready to be used by God to speak, act, and extend His kingdom through your life.', questions: 'What church are you a part of, and how can you be more involved? How can you share Jesus?', confession: 'I am a vital part of the Church, fulfilling the mission Jesus gave us to accomplish.' },
        { day: 36, reference: 'Matthew 6:9-13', devotion: 'If you feel unsure how to pray, you’re in good company. The disciples asked Jesus to teach them how to pray, and these verses were His response. Jesus gives several specifics, but a few key highlights are coming to God with honor and worship, and believing that you are called to bring heaven to earth. Jesus highlights our need to forgive others and points us to ask God for what we need, teaching us to come to God as our Father and not as a distant religious deity. Come confidently to God, knowing He’s ready to listen and respond.', questions: 'How do you like to pray? What’s the greatest thing you’ve seen happen after you prayed?', confession: 'I will boldly approach my heavenly Father. Lord, your will be done on earth as it is in heaven.' },
        { day: 37, reference: 'Psalm 119:105', devotion: 'In this life, we can sometimes feel confused or uncertain about the next steps we should take. But that’s where God’s Word comes in. One of the ways to see the Bible is like a flashlight on the path of life. When we have the Bible closed, we will stumble in the darkness on the path and trip over things because we can’t see. But, when we open the Bible, it floods our life with light so we can see clearly. Most often, the confusion in the world and in our lives personally is because we don’t have the light of God’s Word lighting up our next step.', questions: 'What is your Bible reading approach? Have you started a good daily Bible reading plan? When has the Bible shed light on a decision you needed to make?', confession: 'God’s Word brings light and clarity to my daily decisions.' },
        { day: 38, reference: 'Philippians 2:3-4', devotion: 'These verses “hurt so good.” They are powerful in their effect on your life, but they require an initial step of self-sacrifice that is often uncomfortable or unnatural. Most of life’s challenges come from not applying this scripture. God designed life to work best when you stop focusing on yourself and focus more on meeting the needs of others. But, the spirit of this world wants you to make life all about you. This can even sound like wisdom sometimes, but it doesn’t work because God created the world to work best when we serve others just as He served us.', questions: 'How can you focus more on serving others? What’s one area of your life where you’ve been selfish? Surrender that to God right now and ask Him to help you seek humility instead. [^c15][^c16]', confession: 'I will focus on serving others’ needs before my own.' },
        { day: 39, reference: '1 Timothy 6:10-11', devotion: 'Money is a massive part of our lives because it’s how we live, build the economy, and engage with others. Money can be incredibly helpful, and money can corrupt and destroy. From these verses, we see the issue isn’t money but the love of it. The key here is found at the end of the last verse: pursue righteousness and love. Use money to pursue all that God has given you, rather than using what God has given you to pursue money and its trappings. A primary way to stay free from the love of money is to stay generous. Give often and give generously!', questions: 'Do you have a hard time being generous with money? When is the last time you helped a local outreach or a friend in need without expecting repayment?', confession: 'I will be generous with all God has blessed me with.' },
        { day: 40, reference: '1 Thessalonians 4:3-5', devotion: 'The world will try to tell you that we need to follow our impulses and desires, but God gives us the Holy Spirit to help us produce self-control. Because of our sinful nature, we will be pulled toward sin. Instead of giving in, we—by the power of God and courage—rise above to do what is right according to God’s Word versus doing what feels right according to the world and our instincts. We must honor God with how we handle ourselves sexually. We’re called to save sex for marriage, and nothing outside of sex between a man and woman is acceptable to God and His design.', questions: 'Did you know that God cares about what you do with your body? Are there any practices that you need to change in order to honor God?', confession: 'I will honor God by living in sexual purity.' },
        { day: 41, reference: 'Proverbs 10:4', devotion: 'While God loves you and wants to bless your life in many ways, that doesn’t mean He will just give you everything you want. His blessing is on the work of our hands. When you are faithful, diligent, effective, and productive, God’s blessing will be on that! When we’re lazy and assume the world owes us something or think that God should do all the work, we will come to poverty. No matter where you find yourself financially, you can rise up by applying God’s wealth principles found in the Bible. God won’t get behind laziness, but He accelerates hard work.', questions: 'Are you diligent with your work? Is there a way you can increase your value at your job or begin a new business?', confession: 'I will honor God by being faithful, diligent, and committed to my work.' },
        { day: 42, reference: 'Acts 5:29', devotion: 'While God calls us to love, serve, and prefer others above ourselves, there are times when you have to go against what others are saying, even when they are your authority. The disciples knew that if the word of the government ever contradicted the Word of God, they had to choose God over man. Being a Christian should mean that you carry more kindness and love than others, but it doesn’t mean you do whatever you’re told. It means you live by a moral code and convictions that drive you toward truth.', questions: 'Is there any command your government or boss has given you that causes you to ignore your biblical morality? How can you stand up to evil?', confession: 'I will obey God and speak the truth even when it’s inconvenient or even if I am persecuted.' },
        { day: 43, reference: 'Malachi 3:8-10', devotion: 'Tithing is a practice that God calls us to commit to, which is bringing God the first 10 percent of all we earn. This is about priorities, trust, and God’s economy. God doesn’t need our money; He wants our hearts and our trust. Calling us to bring this precious first portion of our income allows Him to test where we are at. And when we do, God promises to open the windows of heaven and pour out blessings in abundance. When we engage in giving, we are opening up the kingdom flow of giving and receiving.', questions: 'Have you heard of tithing before? Have you started tithing your full 10 percent to your church?', confession: 'I will trust God in my giving and see His blessing in my life. I am blessed so I can be a blessing!' },
        { day: 44, reference: 'Philippians 4:8', devotion: 'This is one of the greatest formulas in the Bible that will unlock God’s best for you. Learning to shift and choose what you consistently focus on will transform your life. Our thoughts are a primary driver of our emotions and our actions. So, what you focus on will determine where your life ends up. Will it be in strength, peace, and blessing? Or will you end up in pain, loneliness, and dysfunction? It primarily depends on focusing on this list from Philippians 4:8 in your life, your relationships, and your calling rather than on the negative.', questions: 'Do you tend to lean toward positivity or negativity? What areas of your life would improve if you started thinking about and speaking life?', confession: 'I will choose to focus on what is good.' },
        { day: 45, reference: 'Jude 20-21', devotion: 'Our relationship with Jesus is a journey that grows during our whole lives. We aren’t fully mature in our faith when we get saved, just like we’re not fully mature when we’re initially born. Growth is a process, and one of those key growth catalysts is the Holy Spirit, specifically praying in the Spirit[^c17][^c18]. All the difficult pressures and pains in life can cloud our judgment or overwhelm us, but God’s Word says that praying in the Spirit builds us up in a unique way so that we can overcome anything coming against us.', questions: 'Have you made praying in the Spirit a daily habit? Did you know that God wants your faith to grow? What has the Holy Spirit been speaking to you about?', confession: 'I will build up my faith as I pray in the Spirit.' },
        { day: 46, reference: 'Ephesians 4:11-13', devotion: 'God is Spirit, but He’s not chaos. God has established order, government, and leadership in everything He created—in heaven, in the nations, in families, and in the church. While all believers are equal in love and value to God, He has called some to step into the primary leadership roles within the Church. These are listed in Ephesians 4:11-13. You may be called by God to carry out one of those roles. If you do, lead with courage and grace. If you’re called to follow one of those primary leaders, follow with honor and grace.', questions: 'Do you feel called by God to one of the five primary church leadership roles? How are you currently serving at your church?', confession: 'I will honor those whom God calls to lead His Church. When called, I will lead with humility and courage.' },
        { day: 47, reference: 'Galatians 5:22-25', devotion: 'Fruit is the product of a seed. In the same way, when we open up our lives and hearts to the Spirit of God, He’ll plant seeds of love, joy, peace, and all those qualities mentioned in Galatians 5:22-23. As we keep cultivating those seeds, we’ll find they begin to produce that same life in us. From the beginning, God made seeds to produce after their kind. So, when you plant seeds from the world, they will produce death; when you plant the seeds of the Spirit from God’s Word, they will produce life!', questions: 'What seeds are you planting in your life right now? Are they from the Spirit or from the flesh or the world?', confession: 'I will walk in step with the Holy Spirit. As I follow the Holy Spirit, I will produce the fruit of the Spirit.' },
        { day: 48, reference: 'Esther 4:14', devotion: 'If you’re breathing, then you have a purpose! Take Esther’s story to heart: the challenges you see around you are not there just for you to feel sad about or just for you to pray about; maybe God positioned you in your workplace, neighborhood, school, or nation for such a time as this. As followers of Jesus, we’re not called to stick our heads in the sand and ignore the issues around us; we’ve been sent on assignment to be the solution. If you’re passionate or frustrated about something in the world, it’s most likely because God is calling you to be part of the solution.', questions: 'What frustrates or saddens you the most in the world right now? Is there something you can do to change it?', confession: 'I am positioned for such a time as this. I won’t be silent. I will engage and transform my world.' },
        { day: 49, reference: 'Romans 8:28', devotion: 'Not all things are good, and not all of the storms are from God—but He does promise us that in every and all circumstances, He is working it for your good. He will allow us to fight battles and go through difficulty, but He will never waste the pain you’re going through. Hold on to this truth like it’s a weapon to defeat the enemy. The devil will try to discourage you and get you to think you’re defeated, but trust God, keep doing what’s right, and watch God work out your story for His good!', questions: '', confession: 'God is good, and He is working all things for my good!' },
        { day: 50, reference: 'Mark 5:18-19', devotion: 'God has saved you and set you free, and now it’s your turn to go into your world and tell others the story of the goodness of God. Many people in your world may not come to church initially, but they can hear about Jesus and how He saves from you. You may feel like you’re not qualified to share your faith or lead someone to Jesus, but this man who was set free had no training; he simply had an encounter with Jesus. He was a witness to what Jesus did in his life. That’s the main thing that Jesus is asking from you—to tell your story!', questions: 'How has Jesus changed your life? Who can you tell your story to this week? Who can you invite to church?', confession: 'I will tell the story of God’s goodness and salvation in my life to the world around me.' },
        { day: 51, reference: '1 Thessalonians 4:1', devotion: 'The more you walk with Jesus, the more you’ll want to please Him with your life. It’s not something you’ll feel obligated to do; it’s just the natural response to His grace and goodness in your life. I love how the Apostle Paul calls us to take what we’ve been learning and keep growing more and more. Don’t stop and settle for your current level of maturity. This verse also reminds us that most of your faith journey won’t be a lot of new things you don’t know but continuing to develop and strengthen in the fundamentals of your faith.', questions: 'What are a few of the key fundamentals of following Jesus you’ve learned so far? What’s one area you could grow in right now?', confession: 'I will keep growing my faith and live to please God.!' },
        { day: 52, reference: 'Revelation 11:15 NIV', devotion: 'As we wrap up this book, it’s important to know that God has an ultimate plan to evict evil from the earth and reestablish His kingdom across the planet! Jesus won our salvation on the cross, and He will have the final victory over the devil and end his rule on earth once and for all. And all nations will submit to Jesus as our ultimate King and ruler. There will be no tribe or nation that’s outside of His rule. So you can rest in God’s plan and have great hope knowing that no matter what we face in our lifetime, God will bring judgment to Satan and restore the earth.', questions: 'Are you confident in the future? How are you working to establish His kingdom on earth until He comes back?', confession: 'There is one King, and His name is Jesus. He will reign and restore all the nations of the earth to Himself.' },
      ]
    },
    kids: {
      title: '52 Bible Verses to Teach Your Kids',
      subtitle: 'Fifty two devotions for your family',
      cover: '/assets/plan-cover-kids.jpg',
      days: [
        { day: 1, reference: 'Genesis 1:1 NIV', devotion: 'The whole earth and everyone on it were made by God. He is the author and designer of all life. From the grass in the field to the eagle in the sky and ultimately to Adam and Eve. The Bible teaches us that God brought you into the world not by accident but with intentional design. Just like the designer of a house or car is the best to give details and instruction on how to operate that car, your heavenly Father is the best one to direct and guide our lives.', questions: 'What’s your favorite animal that God made? What’s one place on earth you’d like to visit?', confession: 'Our God is the creator of the heavens and the earth and the designer of my life.' },
        { day: 2, reference: 'Psalm 119:105 NIV', devotion: 'When it’s dark out and you’re trying to walk somewhere, you need to get a flashlight to light up the path so you don’t go off track or trip over something along the way. The Bible is our flashlight. Because of sin, the world is dark and confusing and only the light of God’s Word can clarify, make sense and show the way through.', questions: 'What’s your favorite story or book of the Bible? And why? Maybe; King David, Esther, Paul.', confession: 'The Bible is my guide along the path of life. If I follow God’s Word I won’t stumble in the dark.' },
        { day: 3, reference: 'Proverbs 3:5-6 NIV', devotion: 'Imagine trying to hold yourself up from falling by leaning on a small twig. That stick would break and you would fall. Now instead imagine keeping yourself held up by leaning against a solid brick pillar. That’s the difference between leaning on God’s understanding or your own. When you put your confidence in God’s thoughts and truth over your own then you’ll find that it keeps you upright and solid.', questions: 'Did you ever have something break that you thought would hold you up? Do you trust God to take care of you?', confession: 'God’s thoughts are greater than mine. I will always choose God’s ways over my ways.' },
        { day: 4, reference: 'John 3:16 NIV', devotion: 'Sometimes people talk about God as being angry at humans, and while our sin must be paid for, The Bible is clear that Jesus came because He loved us not because he was angry at us. No matter what happens in life, if you doubt God’s love for you come back and read John 3:16 and be reminded that God sent his very best because of His great love for you and all humanity!', questions: 'Did you know that Jesus loved you that much? What family, friends, or teacher do you want to tell about Jesus and invite them to church?', confession: 'I am so loved and valuable to God that Jesus was willing to come to earth and save me from the penalty of sin.' },
        { day: 5, reference: 'Matthew 22:37-39 NIV', devotion: 'The Bible is full of simple but powerful principles like this. If you correctly follow them, it makes the rest of life work the way God intended. So, Jesus is teaching us priorities. Loving God is the main thing and source of life. Obedience to what God says in the Bible is one of the greatest ways who show God we love him. And loving your neighbor and people around you is an overflow of your relationship with God.', questions: 'What do you love the most about being a child of God? What’s one way you can show people you love them?', confession: 'I will love God and obey His Word. He will have my whole heart. And I will choose to love others even when it isn’t convenient.' },
        { day: 6, reference: 'James 4:8a NIV', devotion: 'This is one of my favorite promises in The Bible. It reminds us that God wants to be close to us. He’s not interested in just a long-distance relationship He wants to be near you. Notice also how God invites us to take that step of closeness with him. Some of the ways that we “come close to God” are by reading the Bible, spending time in worship, and taking time to pray.', questions: 'What is your favorite way to spend time with God? Prayer? Bible reading? Church? What’s your favorite worship song?', confession: 'My God wants to be close to me and invites me to talk with Him.' },
        { day: 7, reference: 'Matthew 6:9-13 NIV', devotion: 'Jesus showed His disciples to pray, so we as His disciples today can also learn from it. First, you’ll notice Jesus show them to address God more personally as Father. He then shows us to not make prayer just about what we want but about God’s kingdom. Be intentional to pray for God’s will to be done in your city and nation. Then you focus on talking to God about your needs; He wants to hear and provide. Jesus shows us how important it is to forgive others and to invite God to help us fight temptation.', questions: 'What’s something you need God to do for you? Did you pray about it? Is there anyone you need to forgive?', confession: 'I will pray with confidence knowing my Father in heaven hears me. God hears and responds to my prayers. I will pray for God’s will to be done in my city.' },
        { day: 8, reference: 'Galatians 5:22-23 NIV', devotion: 'Life is less about forcing things to happen and more about growing into what God has for you. An orange tree doesn’t try hard to grow oranges, it’s just what an orange tree does. If the roots and soil are good, the fruit will grow. In the same way, the fruit of the Spirit isn’t something we force but something that is a normal overflow of your relationship with Jesus. The more time you spend with God, the more fruit will flow.', questions: 'Which fruit of the Spirit do you find most difficult? Which fruit of the Spirit is easiest for you to show?', confession: 'As I spend time with Jesus and study The Bible the fruit of the Spirit will grow in my life.‬‬' },
        { day: 9, reference: '1 John 3:1 NIV', devotion: 'You aren’t just partially loved or tolerated, you’re loved with an over-the-top kind of love. A love so passionate that it would move God to adopt you as a son or daughter into the family of God. You went from being an enemy of God in regards to your sin to being in the family with all of the privileges that come with being a child of the King.', questions: 'Did you know that God brought you into His family? What’s one fun thing you want to do with God when you get to heaven?', confession: 'I am a child of God who is greatly loved by my heavenly Father.' },
        { day: 10, reference: 'Matthew 28:19-20 NIV', devotion: 'As followers of Jesus, we know that our lives are not just about living for our personal plans or dreams. But, in addition to our life goals, we have a larger vision from Jesus to share the good news to the whole world and to make disciples. Many live striving for meaning and value because all they focus on is themselves, but when you live for the greater purpose and the great commission from Jesus, you’ll find purpose, peace, and joy.', questions: 'Did you know that Jesus asked you to make disciples? How can you show your friends how to follow Jesus? Who can you invite to church?', confession: 'My mission is part of the larger mission Jesus gave us. I will live for more than just myself. I will show people how to follow Jesus.‬‬' },
        { day: 11, reference: 'Ephesians 6:13-18 NIV', devotion: 'When a soldier goes into a battle, they make sure to put on their armor and choose their weapons. In the same way, we are in a spiritual battle and must armor up. Satan wants to stop God’s plans and cause damage to God’s people, but we have been given powerful weapons and armor. We don’t have to be pushed around by the devil, we can rise, armor up, and defeat the enemy. God gives you both armor for protection and weapons to go on the attack against the enemy.', questions: 'What’s your favorite part of the armor of God? Did you know that The Bible is your spiritual sword?', confession: 'Jesus has given me authority over the devil. God gave us armor to defend against the devil’s attacks and gave us weapons to defeat him.' },
        { day: 12, reference: 'Joshua 1:9 NIV', devotion: 'Courage comes from knowing who your heavenly father is and knowing that he’s on your side. God will be with you. No difficulty or challenge can overcome you if the Lord is on your side. This verse shows us the fact that in life you will face difficult times and even discouraging times, but those challenges don’t have to cause you to lose hope because no matter the challenge God will always be with you.', questions: 'What’s the bravest thing that you’ve ever done? What do you do when you feel afraid?', confession: 'I will be strong and courageous. I will not back down from my purpose or calling no matter the challenge. The Lord is with me!' },
        { day: 13, reference: 'Psalm 46:1 NIV', devotion: 'When a tornado comes, we look for a storm shelter that is strong enough to protect us in the storm. In the storms of life, God has promised to be that place of refuge and covering. No matter what you’re facing, run to Jesus! The last part of that verse says that He is a “present” help, which means he is right there, he’s not distracted or distant from you but close to you. Not only is God close, but he wants to help and He is able.', questions: 'The Bible tells us that God is all-powerful, He’s everywhere, He hears us and protects us. How does that give you the confidence to face life’s challenges?', confession: 'I will run to Jesus not away from him in the difficulties of life. God is my help and strength.' },
        { day: 14, reference: 'Psalm 107:1 NIV', devotion: 'So often we base our thankfulness on circumstances being good, but King David understood the source of his thankfulness was not circumstances but the love of God. He had come to know that not only did God love and create you but His love is never-ending. It has no limit, no end and you can count on it. While God deals with evil very harshly, he deals with his kids with great kindness.', questions: 'Was there ever a time you thought that God didn’t love you? Why did you feel that? Does God’s love ever end?', confession: 'I will be thankful because God is good and his love never ends.' },
        { day: 15, reference: 'Psalm 139:14 NIV', devotion: 'God created the whole world in all its glory and He hand-formed and created you. You weren’t just thrown together but wonderfully and specifically made. Made in His image and made with incredible value and purpose. In life, you might find that people try to speak negatively about you or others because they don’t know their value. Learn to forgive them and continue to speak words of life over yourself and others.', questions: 'What’s your favorite thing about how God made you? You are one of a kind! How do you think God will use you to change the World?', confession: 'I will value my life and every human life. All people are hand-made by God in their mother’s womb with great intentionality and purpose.' },
        { day: 16, reference: 'Proverbs 13:20 NIV', devotion: 'The friends that you hang out with the most are who you become like. We want to be friendly and kind to everyone but choose your close friends wisely. When we hang with people who are following Jesus then you’ll start seeing your life grow and be healthy but if you hang out with foolish people who keep making bad choices then you’ll find yourself doing the same.', questions: 'Who is the smartest person you know? Are there any friends that have been a bad influence on you? How can you be a better friend?', confession: 'My friends will impact my life for good or bad. I will choose friends wisely and I will grow to be a wise friend others want to hang out with.' },
        { day: 17, reference: 'Isaiah 40:28 NIV', devotion: 'Because we as humans get tired and sometimes overwhelmed we may unintentionally assume that God feels similar, but no matter what is happening in the world and your life, He’s not weary or tired in a physical way. He doesn’t need a break or a vacation, He’s fully ready and able to handle all that comes your way. This verse also reminds us that His wisdom and commands are beyond our understanding and our greatest form of wisdom is to trust His Word and follow it fully.', questions: 'What’s the latest that you’ve stayed up without sleeping? God knows everything, what’s one question you’d like to ask God?', confession: 'My God is strong and never grows tired. His ways and thoughts are true and higher than mine.' },
        { day: 18, reference: 'Jeremiah 29:11 NIV', devotion: 'Asking someone what they want to be when they grow up and what their plans are for the future can be common questions. But did you know that God has plans for you as well? He’s got a purpose and plan for your life and future. And the even better news is that His plans are always good! God doesn’t create us to leave us in pain or despair, but He created you with good plans in mind. In all of life’s circumstances, He is working out all things for your good.', questions: 'What do you want to do when you grow up? What do you feel God is calling you to do? How does it make you feel that God has good plans for you?', confession: 'God is good and He has good plans for me. I will walk in His ways and fulfill His purpose for my life.' },
        { day: 19, reference: 'Luke 6:31 NIV', devotion: 'Our human instinct is to try and treat people the way they are treating us. If someone is rude or mean to us then we want to be mean back to them, but Jesus calls us to look past how we’re being treated and work to treat people how we would want them to treat us. This can be difficult, but you can with God’s help. It may take some time to change how people are treating you but start by focusing first on how you’re treating them and watch how God begins to change their heart and behavior.', questions: 'Has anyone ever treated you badly? How did you respond? How do you want people to treat you?', confession: 'I will treat others the way I want to be treated no matter how they are treating me.' },
        { day: 20, reference: '2 Corinthians 9:7 NIV', devotion: 'The life of a believer should be marked by generosity. God gave everything on the cross and forgave everyone who had wronged him. He calls us to live in generosity in all things. God created the world to work best in response to your giving. Sowing and reaping. If we want to walk in the blessing of God then we need to develop a life and heart of giving.', questions: 'What’s the best gift you’ve given to your family or friends? Do you find it hard or easy to give? Have you started giving your tithe (10% of income) to your church yet?', confession: 'I love to give. God gave me everything and I will be generous and a blessing to others.' },
        { day: 21, reference: 'Ephesians 4:32 NIV', devotion: 'Forgiving someone who wronged you can often feel like something that they must earn or deserve, but Jesus calls us to radical forgiveness; showing grace towards others even when they don’t deserve it. Our command to forgive is based on Jesus forgiving us, not on whether or not others apologize for what they did to us. Since Jesus forgave you then you must also show mercy. Begin to pray for those who have hurt you and keep forgiving and showing grace to them.', questions: 'What are ways that we can show kindness to others? Is there anyone that you need to forgive?', confession: 'I am thankful for the mercy of God that forgave my sin. I choose to forgive those who have wronged me.' },
        { day: 22, reference: 'Philippians 4:6 NIV', devotion: 'As a child of God, we’re able to take on the adventures of life differently than those who don’t have hope. Some may watch the news or hear about tragedies in the World and start freaking out, but you don’t have to be like that. When you start feeling anxious or afraid, get into the habit of going quickly to God. This verse reminds us that God wants us to bring our needs and request to him. God isn’t bothered by your asking. He sees your faith and trust to come to Him as a great thing!', questions: 'Do you ever worry? What do you worry about? Have you brought that to God in prayer?', confession: 'When I’m feeling afraid, I will go to God first! God wants to hear me pray and ask for help!' },
        { day: 23, reference: 'Philippians 4:13 NIV', devotion: 'In the old cartoon, Popeye, he would get strength from eating spinach. But, for you and I, our strength to overcome is found in the strength that Jesus provides. And since we serve the God of the impossible that means that nothing is impossible if God has called you to do it. Trust God, and step out in faith! Even when the situation seems like it can’t happen, keep trusting God.', questions: 'If you could do anything, what would you do? What’s something you want to do that you need God’s help with?', confession: 'I will not speak fear when God has called me to faith. I will speak in alignment with God’s Word about my life and calling.' },
        { day: 24, reference: 'Colossians 3:20 NIV', devotion: 'God has entrusted parents with the amazing responsibility to care for, protect and teach their children. And as a child, when you honor your parents and follow their instructions you’ll find a blessing in that and God’s grace on it. As we’re growing and learning the Bible, God has entrusted our parents with wisdom that is beyond ours, so trust God by first learning to obey your parents as they teach you the Bible.', questions: 'Do you find it hard or easy to obey your parents? Why or why not? Why do you think it’s important to listen to your parents?', confession: 'I love and honor my parents. I will obey my parents and grow up to be a great parent that shows my kids God’s ways.' },
        { day: 25, reference: '1 Peter 5:8 NIV', devotion: 'Some deny there’s a supernatural world with an enemy called Satan, but if we’re honest we can see evil today trying to harm humanity and we see that throughout the Bible. That might seem scary but the good news is that the Bible gives us some clues to how the enemy operates which gives us an advantage in defeating him in our lives. Remember that because you’re a follower of Jesus, the devil cannot defeat you. The verse above says that the devil roars “like” a lion, but we serve the true Lion of the tribe of Judah!', questions: 'Did you know that with Jesus you have more power than the devil? Have you ever felt like you could feel something evil? Did you pray in Jesus’ name to stop it?', confession: 'There is a devil, but the Holy Spirit in me is stronger. \n\nI will walk in power and authority in Jesus name.' },
        { day: 26, reference: '1 John 4:19 NIV', devotion: 'I’m so thankful for this truth! God didn’t come to you and love you because you earned it or proved you were good enough for His love. He came to earth and died on the cross because He loved us! Jesus went first! And the love and grace and forgiveness we have all flow because He loves us. The love I can have for others is because I’m overflowing with God’s love.', questions: 'How does that make you feel knowing that God loves you? Who is someone you can show love to today?', confession: 'I am loved by God. I will love others as Jesus loves me.' },
        { day: 27, reference: 'Luke 6:38  NIV', devotion: 'If you need to receive something or you need an increase in an area of your life, don’t focus on getting or keeping what you have, focus on giving. We must keep giving. It’s similar to farming. If you want more corn, then you need to give or plant corn into the ground. If you don’t plant then you won’t have anything to harvest. This verse reminds us as well that God always outdoes your generosity. When you give, he’ll bring it back into your life but with extra and overflowing.', questions: 'Did you know you can expect a response to your giving? How can you be more generous to God and others? What is something you’re expecting?', confession: 'I am generous like my heavenly Father is. I will give and God will multiply it.' },
        { day: 28, reference: 'Micah 6:8 NIV', devotion: 'I love it when God spells things out in the Bible very specifically for us. Often God calls us to follow in faith without always seeing, but in this verse, He gives us specific things that God desires from us. To act justly, which is to do what’s right. To love mercy, which is to have a bend towards showing grace. And to engage with God in humility. Which means to look to God as your ultimate authority. Do those simple things and watch God’s favor flow in your life.', questions: 'How do you know what the right thing to do is? Is there someone who made you mad that you need to show mercy?', confession: 'I will do what is Biblically right. I will show mercy to others. I will submit to God and His Word.' },
        { day: 29, reference: 'Galatians 6:7 NIV', devotion: 'At first look, this verse might seem like a negative thing like God is watching and ready to make sure you reap bad things from your bad decisions. And yes, you will reap pain from the negative or sinful seeds that you sow, but this verse is also a promise. You can be confident that you will reap what you sow. When you keep sowing good, even if it takes a while,  you will reap good things. It may feel like your reward is delayed but this is a guaranteed principle that you will see the rewards of your effort.', questions: 'Is there anything in your life you want to see get better? What can you start doing or sowing to see that happen?', confession: 'I will reap what I sow. I will see good things in my life as I apply God’s good word.‬‬' },
        { day: 30, reference: 'Acts 1:8 NIV', devotion: 'The most incredible news is that when Jesus left earth to take His place on the throne in heaven, He didn’t leave us alone, instead, his leaving would allow Him to send the Holy Spirit. When the follower of Jesus is baptized with the Holy Spirit there is an unleashing of new power and authority over the enemy. When you receive the Holy Spirit you’ll speak in tongues and that heavenly langue will bring you incredible closeness to God and the Holy Spirit will empower you to be His witness and to operate in the powerful gifts of the Spirit.', questions: 'Have you been filled with the power of the Holy Spirit? Have you ever told someone about Jesus?', confession: 'Thank you Holy Spirit for your power and joy. I will step out and activate the gifts you’ve given me.' },
        { day: 31, reference: 'Romans 12:2 NIV', devotion: 'This verse is one of the most important. Which pattern are you building your life on? Just like a construction worker needs blueprints and plans to build the house, in our lives, we build our lives based on blueprints. But the question is, where are you getting your plans? From the world? Or from The Bible? God’s plans will bring life but the devil’s plans or this world’s patterns will bring death. If you’ve been building with bad plans, choose today to throw those out and begin to embrace God’s plans for your life.\n\nquestionS\n\nHave you ever started doing the wrong thing because of watching a friend or show? What patterns have you seen in media/movies that are the wrong pattern?', questions: '', confession: 'I will build my life according to God’s plans, not the current culture.' },
        { day: 32, reference: 'Psalm 84:11 NIV', devotion: 'God is our protector and covering and he desires to release all of His goodness in your life. In the beginning, God created absolute perfection for Adam and Eve to live in, which gives us a window into the heart of God to always give His kids the best. God doesn’t withhold any good thing. That doesn’t mean that we won’t have trials or struggles in life but know the heart and intention of God is always for good in your life.', questions: 'What does it mean to walk blamelessly? What good things has God done for you?', confession: 'I will walk in the favor and honor the Lord provides. I will walk with integrity.' },
        { day: 33, reference: 'Proverbs 1:7 NIV', devotion: 'Any chaos in this world is the result of people not fearing the Lord. What does that mean to fear the Lord? It means to revere and respect and honor the Lord. It means to see that God and His thoughts take authority and priority over your own. When we as humans decide that we know better than God and reject the Bible as our guide then we’ll end up experiencing pain and brokenness that God never intended. Wise people build their lives on God’s truth.', questions: 'Have you ever ignored the wisdom of your parents, pastor, or teacher? What happened? Who is the ultimate authority in your life?', confession: 'I trust God and His Word above all other human wisdom. His Word has the final authority in my life.' },
        { day: 34, reference: 'John 14:6 NIV', devotion: 'Many claim different pathways to God. But God gave us His Word to guide us to the true path. If there were many paths the Bible would have told us but the Bible reveals only one way to eternal life and that is through Jesus Christ. He is not a way, Jesus is THE way. He is the Son of God and through His blood spilled on the cross we now come to the Father.', questions: 'Have you had any friends talk about other religions or ways to God? Have you made the decision to follow Jesus?', confession: 'Jesus is the only way to the Father. I will follow Jesus and His ways my whole life!' },
        { day: 35, reference: 'Genesis 1:28 NIV', devotion: 'Every person is driven to find their purpose. While there may be specific and unique things that God will ask you to do, He has also given us the big picture of His will for all humanity. You and I have been given charge of taking dominion on the earth and expanding God’s Kingdom. We are not to just exist, but to be fruitful and multiply on the earth. Whatever God has given you or called you to, take that and grow it and make it better.', questions: 'Did you know that God had a plan for all humans? What job have your parents given you? How can you do it better?', confession: 'We are called to care for the Earth. We are called to rule the earth. I will increase and multiply what I’ve been given.' },
        { day: 36, reference: '2 Corinthians 3:17 NIV', devotion: 'Freedom is at the core of Christianity. When you see and experience freedom you know that God is in it. Wherever freedom is growing it means that Biblical principles are at play. But when there’s a restricting and controlling state, it means the devil is at work. This is true in governments but also this is true to your relationship with Jesus. Church or Christianity that is more focused on rules and human perfection usually means that we’re losing connection with the Spirit.', questions: 'Freedom is what God is known for, what is something you’re known for? Have you invited the Holy Spirit to be with you?', confession: 'The Holy Spirit brings freedom everywhere He is. I will not control but empower.' },
        { day: 37, reference: 'John 10:10 NIV', devotion: 'The devil is a thief and a liar. He plans to destroy and take your life. All sin and rejection of God’s truth leads to death in the spirit and the natural. Adam and Eve experienced this spiritual death. They didn’t die in the natural when they followed the devil but they died spiritually and were separated from God. But, when you follow Jesus you’ll find more life, and not just any life, it’s a full life! You’ll experience greater joy and peace.', questions: 'Have you seen bad things happen to you or others when they follow the devil’s way? Jesus said He came that we would have an amazing life, what does that look like to you?', confession: 'I will not follow the way of the enemy, but I will have and live the full life that Jesus has for me.' },
        { day: 38, reference: 'Psalm 37:4 NIV', devotion: 'Alignment with God’s heart releases the blessing of God. When we come to Jesus, he saves us, heals us, and sets us free to live in Him. Often when we come to Jesus our desires are more focused on ourselves and how it will benefit us. But, when you allow God to transform your heart, you’ll find that the desires visions, and dreams in your heart will be transformed. They may not change but those desires will be purified so that in their fulfillment it brings Glory to God and serves others along the way.', questions: 'What’s your favorite part about following Jesus? What is something fun or meaningful you want to do in life?', confession: 'My heart and desire is to do the will of God. I will serve others with what God has given me.' },
        { day: 39, reference: 'James 4:10 NIV', devotion: 'Don’t worry too much about “getting ahead.” Focus more on humbly serving God and others. When you live submitted to God then you’ll see God elevate and promote you in the right way and the right timing. Too often we try to self-promote and strive to get ahead but that doesn’t fulfill and never lasts. When God promotes you then nothing can stop you. The reason the Bible calls us to humble ourselves before God is because it’s a choice of faith to trust God’s goodness, timing more than yours.', questions: 'Have you ever wanted to be famous? Should we focus on being popular or helping others? What does it mean to be humble?', confession: 'I will trust God’s timing and promotion. God’s Word and timing are perfect.' },
        { day: 40, reference: 'Deuteronomy 31:6 NIV', devotion: 'The lack of fear is not that there are not scary things. It’s that the God you serve is greater than anything you’re scared of. God will be with you and promises never to leave you. Allow this truth to stay close to you in all seasons of life. Whether in the valley in hard times of life or on the mountain top where everything is going well. You’re not alone, He will be with you.', questions: 'Tell us about a time you felt the presence of God with you. What do you do when you’re afraid?', confession: 'My God will never leave me on my own. Even in hard times He’s with me and will give me strength.' },
        { day: 41, reference: 'Matthew 7:3-5 NIV', devotion: 'We tend to focus more on the flaws and issues of our family and friends than on our issues. Jesus is teaching us to focus inwardly first when it comes to dealing with sin. When we try to do surgery on others while being blind it’s messy. First, allow God to do the work in your heart. Let Him remove those big logs and stones in your eyes. Then, you’ll be able to see clearly to help others. Your friends do need you to help them make changes but make sure you deal with your issues first.', questions: 'Have you ever been guilty of being mad at your family or friends for something you do also? What is something you know God wants you to change?', confession: 'I will deal with the sin and issues in my heart first. Lord, heal me so I can help others get healed.' },
        { day: 42, reference: 'Hebrews 13:8 NIV', devotion: 'It’s almost hard to wrap our heads around a perfect God who has always been and will continue to be. Since we are constantly changing and growing, we might assume that God is like that. But, his character and Word was, is, and will continue to be perfect. Which means it’s reliable. It’s something that you can put your confidence in. That’s great news even if we sin and mess up and even directly hurt the heart of God, he is not like us, he doesn’t end his love or mercy because we change, he is consistent in love and truth in all seasons.', questions: 'Have you ever changed your mind on something? Did you know God never changes? How do you trust God?', confession: 'God is perfect and never changes. His grace and truth are constant and forever. He is faithful even if I’m not.' },
        { day: 43, reference: 'Hebrews 11:6 NIV', devotion: 'I love this verse, it packs so much gold in it. First, we get a clue into how to live in a way that pleases God. I want to please God with my life and what is the key to pleasing God? Faith. He calls us into a life of faith and trust in Him. He calls us to believe and put action to our faith. A key display of your faith is to expect good from your heavenly Father. Faith is pleasing to God because it expects that God will respond and reward those who come to Him. Don’t come to God without the expectation that He’ll hear and respond!', questions: 'What does faith mean? Do you believe that God responds when you pray? What are you praying and expecting God to do in your life?', confession: 'I put my faith in God! He hears and rewards as I seek and follow Him.' },
        { day: 44, reference: 'Proverbs 30:5 NIV', devotion: 'God’s Word is not just good ideas or interesting stories. The Bible gives us complete and perfect wisdom for life. Throughout the last several thousand years, scientific, historical, and psychological discoveries continue to echo and prove Biblical accuracy. No other document can be trusted like God’s Word. I love how it describes God’s Word as a protective shield. It’s true, when you live according to The Bible, it guards you against all kinds of evil.', questions: 'Have you ever had to hide in a shelter during a storm? How does God’s Word shield us from life’s storms?', confession: 'God’s Words are perfect. I will live according to The Bible’s instruction.' },
        { day: 45, reference: 'Philippians 2:3-4 NIV', devotion: 'What are you living for? Is life just about you and how you can get what you want? Is it just about how you can get ahead in life? The Bible calls us to live differently than that. We’re called not to live with selfish ambition but to live in a way that is focused on others before ourselves. That’s a little counterintuitive these days, but when you focus less on making yourself happy and more on serving others then you’ll find that God brings into your life all that you need and more.', questions: 'Do you always play the game or watch the movie you want or do you let your friends choose first? What’s something you could do for your family or friends to help their lives be better?', confession: 'I will live to serve others above myself. As I focus on others God will take care of me.' },
        { day: 46, reference: 'Psalm 103:2-5 NIV', devotion: 'We don’t serve and follow Jesus just for what He can do for us, but the truth is that there are incredible blessings associated with serving God. He forgives all your sin! That’s the most important and amazing thing. He heals all your diseases! What a promise of the supernatural overcoming our natural limitations. I’ve seen so many getting healed of pain from headaches to cancer. He Redeems you! Which means He won you back from the enemy! And He blesses and satisfies your life! These are just some of the incredible benefits to your life when you follow Jesus!', questions: 'Did you know God can heal and forgive? Do you or someone you know need a miracle? Have you prayed?', confession: 'Serving God brings with it great benefits in this life and the life to come. I am blessed and walk in His favor.' },
        { day: 47, reference: 'Romans 5:8 NIV', devotion: 'God always goes first. He loves first, He forgives first! And Jesus displays the most unreal heart of God by dying on the cross for us even before we chose to follow Him. That’s how valuable you are to Him that He was willing to leave heaven and risk it all to bring you close to Himself again. This level of extravagance by Jesus is what drives us to live the same way. To take the love of Jesus and go into all the world and love others even before they deserve it.', questions: 'Did God wait until you loved him before He died for you? Who has been rude to you that you can show grace to even before they are nice to you?', confession: 'Thank you, Jesus, for dying for me even while I was against you and now I follow and surrendered to you.' },
        { day: 48, reference: '2 Timothy 2:22 NIV', devotion: 'This verse is a huge key to living pure and in a way that honors God. When it comes to temptation, we need to focus more on running from sin rather than trying to fight it. The apostle Paul tells Timothy to run from sin. Joseph in the Bible runs from temptation. And in your life, stay away from people or situations that might lead you to sin. Instead, fill your mind heart, and attention with chasing after the things of God. Fill your life so full of the good things that you won’t have any room for sin.', questions: 'Are there any sins that you get tempted by? How do you fight to keep doing the right thing even when you want to do the wrong thing?', confession: 'I will live with purity before God. I will run from sin and run after the things of God.' },
        { day: 49, reference: 'Ephesians 2:8-9 NIV', devotion: 'How do we get saved? How can we pay the debt of our sin? It’s not in our hard work or good efforts but it’s by grace through faith. It’s by the Grace of God extended to us through Jesus. We put our faith in Jesus. This is the incredible free gift of salvation that is offered to us. Each person must decide if they are going to receive or reject this gift. If you reject it, you will live in hell eternally away from God. If you accept and put your faith in Jesus then you’re saved and secure and will spend eternity in Heaven with your heavenly Father as He intended.', questions: 'Do we get to heaven by good works? Or by God’s grace? Have you opened that gift of salvation?', confession: 'I am saved by God’s grace not my good deeds. I put my faith in Jesus and what He did on the cross.' },
        { day: 50, reference: 'Exodus 20:3-17 NIV', devotion: 'The ten commandments that were given to Moses are the foundations of every healthy life and nation. When we embrace God’s ways of engaging Him and others, then we’ll build peace-filled and purposeful life and society. Jesus later sums up all the commands and laws into Loving God and loving others, but that’s built on the understanding about God’s desires for us to worship Him only and His command to treat others with dignity and respect. God’s commands always bring us life!', questions: 'Is there anything in your life that you’re giving more priority to than God? How many generations does God show us His love?', confession: 'I will put no other god before the one true God! I will honor others and live according to His commands.' },
        { day: 51, reference: 'Galatians 2:20 NIV', devotion: 'Before Jesus, we were trapped by sin and not just trapped but truly spiritually dead. Then Jesus came along and breathed life in us. He brought us back to life! And now, we’re no longer living for just ourselves but we’re living for and in Christ. This doesn’t mean that Jesus is going to tell you every little detail of your life and control you, but it does mean that you and I are living for His purpose and that you and I are yielded to God’s will as a priority. He gives you dreams and ability and wants you to run with it but have an open heart ready to pause, listen and respond to His leading.', questions: 'What does it mean to be crucified with Christ? How do we live by faith? What has God asked you to do?', confession: 'I will live each day to honor Jesus and build His Kingdom. Not my will by God’s will be done!' },
        { day: 52, reference: 'Matthew 4:19 NIV', devotion: 'This is the greatest and most incredible call in the Bible, to Follow Jesus! It’s what Jesus said to His disciples and it’s the same call that comes to each of us. First, the call is to come close to him, to walk with him to be near him to have a restored relationship. And secondly to be released out into the great purpose of fishing or reaching others with the message about Jesus. When you follow Jesus He will make something great out of you. He invites all to come as we are but He doesn’t leave us the way he found us.', questions: 'When did you choose to follow Jesus? Or are you ready to do that now? Who are one or two people you’re praying to know Jesus and get saved?', confession: 'I hear Jesus calling me to follow and I will respond with a massive yes! Wherever God calls me I will go!' },
      ]
    },
    men: {
      title: '52 Bible Verses for Men',
      subtitle: 'Devotionals that will unlock your purpose',
      cover: '/assets/plan-cover-men.jpg',
      days: [
        { day: 1, reference: 'Genesis 2:7', devotion: 'Our God is the most incredible designer; everywhere you look, creation is a megaphone for His power, creativity, and goodness. However, His best work is humanity. You were formed uniquely in His likeness; you carry an authority that no other creation has. God formed you to create, lead, and produce. The first man was given an assignment and a mission, and we carry that same mandate today. But God didn’t leave us on our own; He breathed His Spirit into us. We carry His authority and His power with us. Use it well!', questions: 'When was the last time you created something new? What is your primary calling and purpose? What are three key goals you’re going after this year?', confession: 'I am created in the image of God. I carry His authority and power. I live with purpose and intention.' },
        { day: 2, reference: '1 Corinthians 15:57-58', devotion: 'We are followers of a great champion. Jesus is not a dead or conquered teacher but the creator and Lord of all the earth and the one who overcame sin and death. In that same winning and overcoming spirit, we as men have been called and commissioned. These verses call us to be unmovable! It’s an essential role of men to be the stabilizing force in a home and society. We are co-laborers with Christ and are called to lead our homes toward the work of the Lord.', questions: 'Do you see yourself as a winner or a victim? Do you stand up for others who are being oppressed? How do you handle pressure?', confession: 'In Jesus, I have victory over all the power of the enemy. I will not be moved by difficulty; I will stay in faith!' },
        { day: 3, reference: '1 Corinthians 16:13-14', devotion: 'We are called to operate in strength and authority, but the great Apostle Paul called us to top off all of our courage and strength with love. True masculinity as God designed it knows how to be strong, but also to love strong. We are courageous because of love, not in spite of it. Jesus was motivated by love when He courageously came to rescue humanity. As the verses state, we defend, believe, and take our stand from the viewpoint of love. We discipline and correct out of love as well. The key is to consider what spirit you are operating in—fear, anger, jealousy, or love?', questions: 'Are you hanging out with men who inspire courage or fear? In what areas do you need to operate more in love?', confession: 'I am a man of courage who pushes past fear to walk in faith! I will do everything in love.' },
        { day: 4, reference: 'Genesis 1:26', devotion: 'From day one, you and I were designed and called to care for and rule over the earth. God wants us to think big about our role. You’re not designed to be afraid of the world but to rule over it. Take the dominion of Jesus to every area that you rule: your home, your work, your city, and your nation. It’s important to see yourself as made and designed in His image and to take on rulership on His behalf. Do not wait around for God to do what He’s called you to do[^c0][^c1]; own your calling and lead on His behalf.', questions: 'What’s an area of your life that needs dominion? How could you grow and stretch in your personal, business, or ministry life? Where have you settled for less than God’s best?', confession: 'I have been formed in His likeness and am called to represent and extend His kingdom on earth.' },
        { day: 5, reference: '1 Peter 5:8-9', devotion: 'Yes, we have an enemy that roars like a lion, but the good news is he’s not a lion. He will try to scare and harass you and ultimately devour you if you let him. He’s looking for someone who’s not paying attention and is unaware of the uppercut that’s coming their way. But in Jesus’ name, you have more authority than him. However, even though you have greater authority, he still has to be resisted. Today, stand firm in your convictions and in your authority as a son of God and resist the devil. Pray and command him to go in Jesus’ name!', questions: 'What areas in your life are most susceptible to the enemy’s attack? What are you doing to strengthen your stance against the devil?', confession: 'I am alert, aware, and ready to defeat the attacks of the enemy. I will stand firm in my faith and resist' },
        { day: 6, reference: '1 Peter 5:7', devotion: 'As men, the weight of the world can feel like it’s resting on our shoulders. While God has designed us to carry the weight of our family, finances, and future, God invites us to partner with Him to bear the load. Feeling anxious or overwhelmed when we’re facing great pressure and new challenges can be common, which is why we must learn to cast those fears on God. You’ll find those anxieties fade as you spend more time in prayer, worship, and the Word. Spending time with God will remind you that He is greater than any challenges you’re facing.', questions: '', confession: 'God cares about every detail of my life. I will bring my worries to Jesus daily in prayer!' },
        { day: 7, reference: 'Genesis 2:19', devotion: 'One of the first things God did with Adam before He brought Eve into his life was to teach him to name the animals. Whatever Adam called them, that was their name. It’s similar in our lives. God is going to teach you the power of the words you use and the labels that you put on people. Too often men grow up with fathers or father figures who didn’t know how to speak life into them, and then they repeat the cycle in their homes. If you want to have a home of joy, peace, strength, and confidence, then you have to learn to speak words of life.', questions: 'How do you use the power of your words? Have you learned to name your wife, kids, or friends in a way that is bringing life?', confession: 'I am thankful for life. I will use my voice to speak life over everyone in my world.' },
        { day: 8, reference: '1 Timothy 4:8', devotion: 'The decisions and choices we make hold within them different promises. In this passage, the Apostle Paul said the decision to be physically fit holds value for this life, and spiritual exercise holds promises for both this life and the next life. This isn’t a devotion to devalue exercise, because we should honor God by taking care of the body He gave so it can carry us to fulfill our purpose. But, when you look at the body and the spirit, it’s building up your spirit that has the most value. Working out your faith muscle is the priority.', questions: 'What are you doing to be physically healthy? What are you doing to grow your relationship with God? How are you prioritizing your faith?', confession: 'I will prioritize my relationship with God above all else. I will be healthy in mind, body, and spirit.' },
        { day: 9, reference: 'Genesis 2:18', devotion: 'As men, we tend to be fine being on our own more often than women, but it’s not good for us to isolate. We’re designed for relationships, and the more we embrace great friends, the more we’ll find fulfillment and strength. We must surround ourselves with godly men who make us better, and it’s essential that we find a godly wife. Your wife is a partner and a complement[^c19][^c20] to you. It’s important that you embrace the full potential that your wife brings—not only for your sexual fulfillment but as a primary partner in your purpose.', questions: 'How can you increase the quality of people in your friend circle? How can you connect with your wife? Or if you are single, how can you prepare to find a wife?', confession: 'I will not do life alone. I' },
        { day: 10, reference: 'Deuteronomy 8:3', devotion: 'God calls us into purpose and dominion. As men, we can get arrogant and start thinking our dominion is all our own doing. So, if you’re facing a season of testing and struggle, it may be God’s grace pulling you out beyond your own ability so you can learn to trust God again. We don’t overcome by our strength, but through God and His Word. His Word is life to us and feeds our souls and our bodies. Learn to go to God’s Word daily and watch your strength increase!', questions: 'Have you made reading or listening to the Bible a part of your daily routine? How do you best like to engage with the Bible? What’s a key thing that the Holy Spirit has been highlighting in your reading?', confession: 'I do not live by my strength alone; I am dependent on the Word of God for courage, hope, and life!' },
        { day: 11, reference: 'Deuteronomy 8:5', devotion: 'God disciplines us because He loves us. He doesn’t want to see us left where we are but instead wants to challenge and call us out of our dysfunctions. God corrects us a few ways, through life’s circumstances and challenges, and sometimes He speaks directly to us to by His Word and Spirit.[^c49] This verse also challenges us to be good fathers who commit to disciplining our children. True love isn’t letting them live without correction; we must correct and develop them toward their purpose.', questions: 'How do you respond to correction? Is there a biblical mandate/command you need to obey? What is one area in which you need to discipline your child?', confession: 'I will be open and receptive to the discipline that God and my leaders bring into my life!' },
        { day: 12, reference: 'Galatians 1:10', devotion: 'Who are you trying to please? One of the greatest dangers in life is trying to attain the approval of others. We should live in a way that fulfills our calling, and if we’re in school or on the job, we honor God by excelling at what we’ve been given. But working hard is different from working to earn your value. Your value is not something you earn; it’s something given to you by God. The more revelation you get from the Bible about your value and your secure position in the family of God, the more you can live with peace in your work.', questions: 'Do you primarily make decisions based on pleasing God, others, or yourself? How have you learned to break free from chasing the approval of others?', confession: 'I honor God and man, but I will live to please God with all that I think, say, and do.' },
        { day: 13, reference: 'Hebrews 4:12-13', devotion: 'As men, we’re often the ones with the tool or weapon in our hands taking care of business, but have we opened up our lives to the sword of God? It’s not just any kind of weapon; it’s both powerful and precise. This weapon is the Word of God. It’s the thing that God uses to cut through the noise around us and get straight to the heart of the matter. It’s also the weapon that God gives us to use. When you take hold of the Word of God and begin to meditate on it and then speak it out, you’ll see your life transform and the devil flee!', questions: 'What’s the most challenging thing God is speaking to you right now? What verse are you meditating on?', confession: 'God’s Word is alive and active in my life! I will submit to and boldly speak the Word of God.' },
        { day: 14, reference: 'James 5:16', devotion: 'We often try to carry our issues and challenges on our own, but this will ultimately break us. God calls us to confess our sins to others so that times of healing can come. Yes, we first go to God with our sins, but being vulnerable and bringing our junk to the men in our lives will create the full process of healing, refreshing, and strengthening. You’re not designed to do life on your own. You’re not designed to face your battles on your own either. Confess your sins to a trusted friend or pastor, and watch your life and peace accelerate.', questions: '', confession: 'I will confess my sin, submit to God, and pray powerful and effective prayers!' },
        { day: 15, reference: 'Joshua 1:9', devotion: 'We are commanded by God to be strong and courageous. Why? Because life can be overwhelming, and it’s a choice to live with courage. The difficult seasons that we face are going to constantly try to drain our strength. Don’t be caught off guard by the challenges of life. Feeling pressure and fatigue is normal; however, submitting to the pain and giving up is not what you were designed for. Your family and city are awaiting your courage. It’s why God intentionally sent you to earth in this hour. Be strong!', questions: 'Do you find it difficult to remain confident and courageous? How do you work to stir up courage in your life? What’s your greatest fear right now?', confession: 'I will not be afraid or discouraged by my circumstances; I will put my confidence in Jesus and boldly take action!' },
        { day: 16, reference: 'Luke 10:27', devotion: 'The strength of a man flows from his connection to his heavenly Father. Jesus reminded us that our primary focus must be to love and honor God with our lives. It’s the thing that should guide and govern our choices. If we make honoring God an afterthought, we’ll live spinning our wheels and chasing things that don’t matter. Jesus gave us a priorities prescription that will set up every area of our life to thrive. When loving God is not first, it creates chaos in the rest of what we do. Adjust your life to put loving God and others first.', questions: 'Is the life I’m building bringing honor to God and serving other people? Is there any part of my life that I’ve been holding back from God?', confession: 'I will love God with all my heart, soul, strength, and mind! Love for others flows from loving God.' },
        { day: 17, reference: 'Micah 6:8', devotion: 'In this verse, God gets super clear on the values that He wants us to live by. We must act justly. This means that we’re walking with integrity in all that we do and in how we treat others. Then we are to love mercy. As followers of Jesus, we should be the most merciful people, giving forgiveness freely and an abundance of second chances. Finally, we must walk humbly before God. This means that we engage God from a place of submission to His way over ours. These three items are values to build your life on!', questions: 'Is there any injustice around you that you can fix? Is there anyone you can show mercy to? Is there any area where pride is sabotaging you?', confession: 'I will treat people fairly. I will extend forgiveness. I will honor God’s thoughts above my own.' },
        { day: 18, reference: 'Proverbs 20:7', devotion: 'What you do and how you live matter. The choices that we as men make will impact those around us and will leave a legacy of strength or pain for our children. When we live righteously, which is in alignment with God’s Word, we’ll see our children blessed. Think of the difficulties that have been passed down to you from your parents. How have those battles been? And think of the blessings that have been handed down to you from your parents. Now, what do you want to pass on to your children? Each godly decision you make today will set the course for a new legacy for your family!', questions: 'Is there a dysfunction you don’t want passed down to your children? How can you live right before God?', confession: 'With God’s help, I will live a righteous and pure life. My wife, children, and friends will be blessed!' },
        { day: 19, reference: 'Proverbs 27:17', devotion: 'When iron strikes iron, sparks begin to fly! It can be the same with us as men. When you’re in close connection and mentorship with another man, those times of discipleship and confrontation are the iron-striking-iron moments that cause us to be sharp. If we don’t like being challenged and confronted, we may try to avoid the discomfort of the sharpening, but that leaves us dull and ineffective. Lean into the tension. Put yourself in environments that challenge you to grow!', questions: 'Who are you being intentional to sharpen and mentor? Who are you speaking the truth to? Is there anyone who can call you out on your issues?', confession: 'I will not avoid confrontation or correction. I will embrace the input of my friends and mentors so I can grow!' },
        { day: 20, reference: 'Proverbs 24:5-6', devotion: 'Wisdom unlocks your power and potential. Many men try to push and strive their way through to victory, but those who are wise will listen to counsel, coaching, and advice that will allow them to unlock their giftings and abilities. Because victory doesn’t always go to the strongest but instead to the wisest, we must use wisdom to outwit our enemy. While we don’t face our enemies on a literal battlefield, they often come in the form of economic struggles, addictions, and challenges within work, relationships, and culture. We need wisdom to overcome!', questions: 'Do you have a coach to help you advance your business? Is there any battle you’re facing that you need to get input on?', confession: 'I will lead with wisdom and courage! I will seek the coaching of mentors before I charge into battle.' },
        { day: 21, reference: '1 Corinthians 10:12-13', devotion: 'We’d all like to think we’re invincible against sin and temptation, but if we’re honest, we each have areas of potential weakness. Now, what the devil would like you to think is that you’re abnormal and alone in your temptations. The truth is that, like the Bible says, it’s common. So, we need to learn to open up and invite other men into our world to help us break free and walk away from temptation. God will always provide a way out. God takes you through storms—but out of temptation!', questions: 'What’s the biggest temptation that you face? Have you opened up to another man about it? Have you asked God for strength and wisdom?', confession: 'I am not alone in my temptations. God has provided a way out, and with the help of my brothers in Christ, I will take it!' },
        { day: 22, reference: 'Matthew 6:19-21', devotion: 'Having an eternal perspective [^c66][^c67]is key to a fulfilled life on earth. Why? Because the eternal provides the context and purpose for this life. Many live aimlessly and, therefore, make no impact. But, when you live and do everything from a biblical perspective, it brings life into focus. The supernatural provides clarity for the natural. Making money is not what provides meaning; living a life of meaning and purpose is what will produce prosperity.', questions: 'Are you investing your money into the kingdom of God? How can you serve others? How are you making an impact with your work and life?', confession: 'I will store up treasures in heaven by investing my time and resources into the things on earth that are eternal.' },
        { day: 23, reference: 'Romans 12:1-2', devotion: 'What patterns are you building your life on? Every home needs blueprints for the crew to review and build from, and each of us is building our lives based on a set of patterns or blueprints. The challenge is that some people get defensive or protective about their patterns rather than checking and asking the question “Where did I get these blueprints, and are they working?” If our plans aren’t working, how do we course correct? It’s one thought at a time—by reading and applying God’s Word. Each time you apply it, it transforms you.', questions: 'Does your life look more like the world or like God’s Word? Is there any area of your life that isn’t working that you need to find God’s pattern for?', confession: 'I will give my life as a living sacrifice to God! I will not live for myself, but for Jesus and His kingdom.' },
        { day: 24, reference: 'Hebrews 10:23-25', devotion: 'Who are you inspiring toward good? Sometimes we’re taught to keep to ourselves and not interfere with someone else’s personal business, but that keeps us as bystanders and makes us useless to God. The truth is that we’re responsible to speak up for others and to encourage others in our world. Obviously, if you try to help someone and they don’t want it, that’s up to them, but if you see that they need help and do nothing, then that’s going to fall back on you. We have a responsibility to speak the truth to our world.', questions: 'Name three people who you can encourage today. Are you consistently taking yourself and your family to church? Are you and your family serving at church?', confession: 'I will speak the truth that people need. I will encourage others toward good works.' },
        { day: 25, reference: 'James 1:19-20', devotion: 'Often our frustrations or anger can be the result of not taking time to listen before we jump to conclusions. Taking the time to slow down, gather more information, and then make a call is huge. Not only do quick judgments lead to wrong or harmful assumptions, but they breed frustration and anger in your children. We lose trust with our friends, kids, and wife when we jump to conclusions and lose our temper. Don’t take things personally; step back, listen, and respond in a way that will be helpful.', questions: 'Do you have a difficult time not jumping to conclusions? Do you assume the best or worst about people? How would you rate your listening ability? [^c82]', confession: 'I will focus on the best in others. I will be patient and listen before I speak into a situation that frustrates me.' },
        { day: 26, reference: '1 Timothy 6:11-12', devotion: 'As a man after God’s heart, it’s not just about fleeing sin but about what we’re pursuing. All of the great men of faith in the Bible aren’t in there because they didn’t sin. As a matter of fact, there are some pretty horrific things that many of them did in their lives. But, they were all marked by qualities of repentance, grace, pursuing justice, defending the oppressed, and establishing God’s kingdom. Don’t make your goal to just not do the wrong things; make it your goal to pursue the list the Apostle Paul gave to Timothy in these verses. As you chase after the right things, you’ll find your desire for sin will fade.', questions: 'What boundaries can you set to keep yourself away from sin? What good habit are you working on today?', confession: 'I hate sin and love God’s Word. I will live with purity, faith, and courage.' },
        { day: 27, reference: 'Mark 10:42-45', devotion: 'As men, we’re called to lead in our homes and in our world. Jesus set the example and called us to lead by serving. This simple but powerful approach will take your impact to a new level with your family, coworkers, staff, and the world around you. Servant leadership changes how you engage people. Rather than seeing those in your world as a stepping stone to where you want to go, you begin to see your role as helping others get to where they’re called to go. God design in life is for you to succeed when you help others win.', questions: 'Is there an area of your life where you could step into more of a leadership role? How are you doing with serving your wife? Kids? Clients?', confession: 'I will not hold back from a leadership role in my family, work, and church. I will help others succeed.' },
        { day: 28, reference: 'Psalm 1:1-3', devotion: 'The key to prospering is to make God’s Word the focus and meditation of your heart and mind. That means it’s the central and core guidance of your life. When you make God’s Word your focus, it will begin to shape your life and decisions. When you make biblically based decisions, you’ll find that your life begins to grow and stay fresh like a tree planted by the water. That tree thrives because it’s getting consistent nutrients that the water brings; in the same way, God’s Word brings fresh insight that causes you to grow!', questions: 'Are you a part of the community at your local church? How often are you feeding on God’s Word? How would you describe your circle of friends?', confession: 'I will plant my life close to God’s Word and His people so I can thrive in all that I do.' },
        { day: 29, reference: 'Psalm 118:6-9', devotion: 'The Lord is with you! This truth will create peace and confidence through seasons where it feels like life and people are against you. The Bible reminds us that you don’t need to fear humans and what they can do to you; you just need to fear God and what He can do. No plan of man can override the plan that God has for you. While we honor and serve people, we do not live in fear of them or metaphorically bow to their pressure. Put your trust in God!', questions: 'Where have I been putting too much trust in people for my provision, peace, and purpose? Do you go to God or people first when trouble comes?', confession: 'God is with me so I will not fear! I will put my hope and confidence in God.' },
        { day: 30, reference: 'John 16:33', devotion: 'Jesus doesn’t promise us a life of ease, but He does promise a life of peace. When your mind and attention are focused on and consumed by the challenges and difficulties of this life, fear and hopelessness begin to rise. But, when you are focused on Jesus and the fact that He is holding all things together by the power of His Word, it shoots peace and courage into your soul. If you lack peace, it just means that you’re giving the storm too much attention.', questions: 'What areas do I need to turn over to Jesus? What have I been worrying about that I need to be praying about? What victories has God brought into my life?', confession: 'I will have peace no matter the difficulty I’m facing. My confidence isn’t in my circumstances but in Jesus.' },
        { day: 31, reference: 'Proverbs 3:5-6', devotion: 'When we submit our life decisions to God, we find that things begin to straighten out. We can get caught in cycles of dysfunction because we’re stuck in a rut of doing what has always been done even though it’s not working. Following Jesus as our Lord means we filter all of our decisions through God’s Word. Over time you’ll begin to instinctively think and act in alignment with the Bible, which will cause the promises and blessings of God to flow into and through your life.', questions: 'What way of thinking from your past or family upbringing do you need to change? What command from God’s Word do you need to follow? What promise do you need to believe again?', confession: 'I will trust God’s Word over my own. I will be stable and unshakable as I lean on His truth.' },
        { day: 32, reference: 'Exodus 15:3', devotion: 'We were created in the image of a Warrior! Being a warrior doesn’t always mean being violent, but anyone who is a warrior is willing to do whatever is necessary to protect and defend those they love—even to their own pain. As men, we need to carry a warrior spirit, not allowing life’s circumstances and difficulties to get us to quit. A warrior is loving to his wife but ruthless with the enemy. As warriors of our homes, we must be full of love for our family and aggressive in resisting the attempts of the devil to steal, kill, and destroy.', questions: '', confession: 'The Lord is a Warrior, and so am I! I will face the valleys and the mountains with courage.' },
        { day: 33, reference: '2 Corinthians 4:16-18', devotion: 'Trouble produces either strength or bitterness in our lives, but it will always produce something. The key is for us as believers to keep the right perspective and right focus. When you approach difficulty as a chance to grow and allow God to teach you something, you’ll see incredible dividends. When life gets difficult, remember that while God is shaping you, He’s also going to use the pain and victory story as a testimony that will guide people to Jesus!', questions: 'How has God used difficulty to shape your life? Have you ever lost heart in difficulty? How did you get it back? What is God doing in your current season?', confession: 'I trust that God is working in the seen and unseen moments to bring about His purpose in my life!' },
        { day: 34, reference: '1 Corinthians 15:58', devotion: '“Let nothing move you.” What a challenge this verse presents to our often fluctuating thoughts and emotions. No matter the circumstance, stand in faith. Our world constantly wants us to be moved and sent off course by our feelings, but God is calling us to dig down and solidify our position in His Word. In the second half of the verse, the Apostle Paul said to “give yourselves fully to the work of the Lord.” Part of what focuses you and stabilizes you is the mission God has given you. It’s easier for the enemy to take you down when you get off mission. Keep taking ground for the kingdom of God!', questions: '', confession: 'I will fulfill my calling, and nothing will move me off my God-given mission!' },
        { day: 35, reference: 'Acts 1:8', devotion: 'While on earth, Jesus told His disciples to go into all the world, but first He told them to stay and wait. I’m sure it felt counterintuitive since He had been preparing them for action. But Jesus was telling them, “You have the mission, but you still need the power.” In our lives as well, we can’t fulfill our God-given assignments without first being filled with the power of the Holy Spirit. To resist the devil and accomplish your mission, you need to ask Jesus to baptize you with His Spirit!', questions: 'Are you baptized in the Holy Spirit? Have you begun to speak in tongues,[^c94][^c95] also known as praying “in the Spirit”? Pray in the Spirit daily to build up your faith!', confession: 'I invite the Holy Spirit into every area of my life. He will empower me to do God’s will.' },
        { day: 36, reference: 'James 1:2-3', devotion: 'A tree that has to grow with the wind pushing against it tends to be strong because its roots go down deep. The resistance makes it grow stronger, which is why James encouraged us to consider the trials of life a joy. That’s a bold statement! Pressure calls the strength out of you. As men, there will be times when we must carry more of the weight of the difficulties that come our way to cover our wives and children. Ready yourself by not running from difficulty but embracing it!', questions: 'How did you handle your most recent trial? What did God teach you? What will you do differently next time?', confession: 'God is using the difficulties in life to shape me for His purpose. I will embrace trials with joy!' },
        { day: 37, reference: 'Joshua 24:15', devotion: 'Part of your role as a man is to stand against the lies, mediocrity, and pressures that the enemy and culture send your way. There will always be forces from the enemy trying to get us to slip into compromise, and it’s the man who is called to step up and declare that he and his family will go after God’s heart. Remember when Eve ate the fruit and sinned, the Bible says that Adam was there, but silent. As men, let’s not be silent; let’s step up and into our roles. Make going to church a nonnegotiable part of your week. Model for your family an authentic relationship with God.', questions: 'Have you made the decisive choice to serve and follow Jesus? Have you been leading your family to Jesus? How are you helping your family to connect and serve at church?', confession: 'As for me and my family, we will serve the Lord!' },
        { day: 38, reference: 'Ephesians 5:25-26', devotion: 'What a vivid picture of how we are to love our wives! “As Christ loved the church” means that we are to focus on leading, loving, protecting, and sacrificing for our bride. You are putting her needs before your own. These verses don’t mean that you just need to do whatever she wants, but that you’ll do whatever is needed. Being a great husband means leading your wife and family toward the truth of God’s Word and His ways even if they don’t want to hear it. Your family needs you to lead in love and truth through every season.', questions: 'On a scale of 1 to 5[^c102][^c103], how well are you loving your wife? Are you leading with her in mind?', confession: 'I will love my wife as Jesus loves the church' },
        { day: 39, reference: 'Psalm 37:23-24', devotion: 'There’s a priority principle in these verses. When you make God’s ways a priority, He makes your ways secure. Often we want security or guarantees from God before we start applying His Word. But, it’s actually the application of His Word that stabilizes our lives. Does that mean that as a follower of Jesus I’ll never have issues? No, but the Bible says, even if you stumble, you will not fall because God holds you up. As we learn to love, honor, and prioritize God’s ways, then He will cause all of life to begin to flow in the right direction.', questions: 'Are any of your priorities out of order? Has there been a time when you stumbled but God held you up? Or helped you back up?', confession: 'I will make God’s plans my priority, and He will establish my steps.' },
        { day: 40, reference: '1 Timothy 5:8', devotion: 'God calls us to be our brother’s keeper. The world may try to communicate a narrative that you don’t have to worry about anyone but yourself, but the truth is that God designed a world that runs off serving, sacrifice, generosity, and love. If we are going to claim Jesus, then we must live by His principles. This means that we take care of others. We cannot neglect a core value of the kingdom, which is sacrifice and generosity, and expect God to approve. How you treat your family, loved ones, the unlovable, the rich, and the poor reflects on you.', questions: 'How are you serving others around you? How are you providing for your family and parents?', confession: 'I am a producer and provider for those in my life whom God has called me to serve.' },
        { day: 41, reference: 'Isaiah 40:28-31', devotion: 'The generation God placed you in [^c107][^c108]demands your strength! But, there are times when we get tired, weary, or discouraged and feel defeated. These verses give us a powerful view of God and hold the key to getting our strength back. To assume that we can go through life and not get weary is a false expectation. What we must do is learn how to stay encouraged and how to recharge our batteries when they get low. Where is your hope? In your work, economy, yourself? Or is it in God? When we put our attention on Jesus and His Word, we’ll begin to see hope and strength return!', questions: 'How do you recharge? How do you keep your hope focused on Jesus? How are you avoiding burnout?', confession: 'God is not overwhelmed or weary by my challenges. When I get overwhelmed, I will run to Jesus!' },
        { day: 42, reference: 'Proverbs 16:9', devotion: 'Plan your steps and submit them to God. Man was created to increase and rule, but we are not a law unto ourselves. We are empowered to the level that we’re submitted to God. For optimal success in life, we must learn to submit our plans to God. Why attempt anything that wouldn’t require the blessing of heaven? We can all make plans, but God establishes them. Invite God into the design and execution of your plans. It’s easy to make critical errors when you don’t include the leading of the Holy Spirit.', questions: 'Do you have dreams for the future? Take time to write out your goals. Have you invited God into your dreams and vision for the future?', confession: 'I will pray and plan. I want my plans to echo God’s heart and be sustained by His strength!' },
        { day: 43, reference: 'Philippians 1:6', devotion: 'As men, we’re born to compete and conquer! This is why we get discouraged when we focus too much on what we’re not, or on what we haven’t achieved yet. Allow this verse to breathe peace into your soul; you can be confident that if God began a good work in you, He will be faithful to complete it. Trust God’s timing with how you are being developed. Don’t live trapped in comparison; it’s time to embrace God’s process. If you’re still breathing, then you still have a purpose. He will fulfill the promises and finish the work He began!', questions: 'Do you find it easy to slip into the comparison trap? What’s a key area that God has you “in process”? How has God been faithful to you?', confession: 'God, thank you for all that you’ve done in my life. You will finish in me what you started.' },
        { day: 44, reference: 'Psalm 18:13-14', devotion: 'Life is filled with circumstances that are beyond our control. How do you respond to pain, disaster, loss, the economy, or a health diagnosis? When things seem too difficult or beyond your control, what do you do? The Bible reminds us that we should look to the one who thunders from heaven. God has placed in our hands the strength and gifts to alter history and resist the enemy, but sometimes all we can do is humbly come to God and call on His name and mercy to fight the enemy. God sees the injustice and will send His arrows.', questions: 'Have you postured yourself in a place of humility or resistance toward God? Are you focused on your humanity or His power?', confession: 'God is all-powerful, and I am submitted to His leading. He will right the wrongs done against me.' },
        { day: 45, reference: 'Psalm 31:19', devotion: 'This is a powerful reminder of the good intentions of our heavenly Father. He has goodness stored up for you! He is the Good Shepherd, who will not leave you alone or abandon you but will give you an inheritance of His kingdom. We are heirs and recipients of His kingdom, and when we honor God and put Him in the rightful place in our lives, it unlocks the blessing and goodness of heaven over our lives. The enemy will try to get us to doubt God’s good plans, but the Bible constantly reminds us of the good He has planned for us. Begin to live in that revelation!', questions: 'Did you grow up believing God had good things for you? What are you asking God to do for you today?', confession: 'My heavenly Father has intentional and good plans for my future!' },
        { day: 46, reference: 'Philippians 4:6-7', devotion: 'The peace of God is powerful! It can guard us against the attack of the enemy. When we bring our doubts, fears, and challenges to God, He will send us peace. When we fix our eyes on other issues, we’ll find ourselves wide open to the enemy sending in his arrows of fear and anxiety. But when we keep our eyes on Jesus, it puts up a shield of protection. Prayer, worship, Bible reading, and praying in the Spirit are all ways to keep our eyes focused on the good.', questions: 'Do you struggle with anxiety? What do you need God to do for you that you haven’t prayed about yet? Write down a list of things you’re thankful for.', confession: 'When fear and anxiety try to get the best of me, I will go to God in prayer, and His peace will guard me!' },
        { day: 47, reference: 'Deuteronomy 31:6', devotion: 'What could possibly be stronger than God’s Word in your life? The answer is nothing! No matter who or what tries to come against you, take it with courage and peace, knowing that God’s promise is for you—He will never forsake you! He will not leave you alone or on your own. God is not a passive onlooker; He is close and ready to respond on your behalf. It’s time to step out in courage! No more messing around with insecurity; step up and be bold because of who is behind you. It’s like when you were a kid and you were bold because your bigger brother was behind you.[^c115][^c116]', questions: 'Has fear of abandonment been a challenge for you? How can you give courage to those around you?', confession: 'I will be strong and face my purpose because God is going with me on this journey!' },
        { day: 48, reference: '1 John 4:4', devotion: 'What are you made of? This is a massive question! As children of God, we don’t have to answer this in our own strength or ability but in our God-given identity. What we have in us is greater than what’s in the world! What we have in us has overcome the enemy! You can wake up every day and head out with courage and boldness to continue Jesus’ dominance over Satan. If there’s anywhere in your life right now that the enemy is messing with you, it’s time to remind yourself—and him—that you are in Christ, and in that Name, you will drive the enemy out of your life!', questions: '', confession: 'I am a child of God, made in His image! With God, I will overcome every challenge.' },
        { day: 49, reference: 'Psalm 46:1', devotion: 'When we go to God, we should approach Him with great confidence in His ability! We don’t just go to Him as a ritual; He is present, and He is able to help. God provides wisdom, strength, and protection in our lives. The refuge is a covering. What are you allowing to cover you? God wants to be that covering and guard in your life. Are you willing to allow Him to protect you? He will guard you with His Word and wWisdom, and by His powerful presence.', questions: 'What do you need God to do in your life today? [^c119][^c120]What’s one miracle that you’re believing God for?', confession: 'God is present with me today, and He has the power to help me face every battle.' },
        { day: 50, reference: '1 Chronicles 16:11-12', devotion: 'It’s so easy to forget the good and hold onto the negative things that have happened to us. But God’s Word constantly reminds us to call to memory the good. Remember the miracles, the moments where God came through, the wisdom and creativity that He brought, the justice that was done. Take time to thank God for all of the goodness He’s shown you in small and large ways. When we forget God, we start living small, but when we keep engaged with the memory of His greatness, it will call us into the purpose and calling He has for us.', questions: 'Have you experienced a supernatural miracle? How can you stay thankful for God’s goodness?', confession: 'I will look to God and remember His goodness! I will praise Him for all His wisdom and miracles.' },
        { day: 51, reference: '1 Peter 5:5-6', devotion: 'Submission to God and the authority He placed in your life is the beginning of unlocking your strength. There are few things that the Bible says God opposes, and pride is one of them. Learn to humble yourself before God, and wait for His timing and promotion. We thrive under healthy submission and boundaries. When we walk in humility, it’s not weakness but an understanding of where our strength comes from. Honor and submission are what release our strength and authority.', questions: 'Who do you let speak into your life? Who can correct you? Who are you mentoring and encouraging?', confession: 'I will walk in humility and grace. I will receive input and correction. I will walk in God’s favor!' },
        { day: 52, reference: 'Numbers 13:30', devotion: 'We will conclude by reading about the courage of Caleb. The other ten spies were convincing Moses and the Israelites that the Promised Land was too dangerous and the people too strong. Then Caleb stepped up, challenged their fear, and called the people to believe the promises of God again! I pray that would be true of you. Face fear head-on, challenge it, and don’t let people slip back into small living because of fear. Call them to believe the promises of God!', questions: 'Who around you has been acting in fear that God wants you to challenge and encourage to live with boldness? What dream, project, or mission is still left to be done in your life?', confession: 'With God, we can and will fulfill all that He has called us to accomplish!' },
      ]
    },
    youth: {
      title: '52 Bible Verses for Youth',
      subtitle: 'Fifty two verses to build your life on',
      cover: '/assets/plan-cover-youth.jpg',
      days: [
        { day: 1, reference: '1 Timothy 4:12 NIV', devotion: 'It’s easy to assume that you have to wait till you’re an adult before you can set the example. But, this verse and many stories throughout the Bible show us that God often chose young people to take on bold and courageous missions. Heroes like David, Esther, Josiah, Mary, and most of the disciples were young when God called them and all of them change their generation! Never doubt what God can do with your life in your teenage years!', questions: 'Did you know that God wants to do something great in your life now? Not just when you’re older? How can you set a better example for others in your world?', confession: 'My youth doesn’t disqualify me. I can lead the way even while I’m young. God often uses young people to change the world!' },
        { day: 2, reference: 'Proverbs 12:26 NIV', devotion: 'One of the most important choices we make in life is who our friends will be. While you may be naturally connected with certain friends because of school or a sport, the truth is that we have to be specific about the kind of friends we spend the most time with. Before becoming close friends with someone, look at the fruit of their lives. This means looking at their attitudes, how they treat their parents or other friends and what their relationship with God is like. Choosing great friends will set up your future!', questions: 'Are your closest friends a positive or negative influence on your life? How can you become a better friend?', confession: 'I will be a Godly friend that others can count on and I will choose friends that are passionate followers of Jesus.' },
        { day: 3, reference: 'Psalms 139:13-16 NIV', devotion: 'You are NOT an accident. You are intentionally planned and designed by your Heavenly Father. You have a call and purpose. We often hear from the world that we have no creator or that we’re a random collection of material, but The Bible teaches us that even before the world gets to you see you, God saw and formed you with great care. You can live each day with confidence knowing you are loved and created.', questions: 'Have you ever built, painted, or designed something you were majorly proud of? What was it? Has there ever been a time you didn’t feel loved or valuable? What did you do to remind yourself of God’s love?', confession: 'I am loved and hand-formed by God. I am valuable and have been made for a great purpose.' },
        { day: 4, reference: 'Galatians 1:10 NIV', devotion: 'The approval trap is a massive issue in our world. When we live to always get approval from others it will end up tripping us up and often harming our lives. Rather, like the Apostle Paul is saying, we want to learn to live for the approval of God, not of people. That doesn’t mean we shouldn’t care about what others say but it’s the foundational principle that we’re here to please God before people. Often you can do both, but if you have to choose, always choose the way that pleases God.', questions: 'Have you ever made a bad decision because of trying to impress a friend? Is there anything you’re doing that doesn’t please God that you need to change?', confession: 'I am a servant of Christ. I will live to please Him before all others no matter the personal cost.' },
        { day: 5, reference: 'Acts 1:8 NIV', devotion: 'Life isn’t always easy but the good news is that God doesn’t leave us to do it all on our own. Jesus sent the Holy Spirit to empower us! When you invite the Holy Spirit to fill your life, you find you’ll have the courage to take on challenges and battles that might come your way. Ask Jesus to baptize you with the power of the Holy Spirit and then as you take on each day invite Him to speak and lead and guide your life. He’ll empower you for your mission and purpose and give you the strength to share your faith!', questions: 'Have you been baptized in the Holy Spirit? Share or write about it. Have you invited anyone to church with you recently? What was that like?', confession: 'I will walk in the power of the Holy Spirit and fulfill the mission that He has given me.' },
        { day: 6, reference: 'John 10:10 NIV', devotion: 'How can you tell if something is good or evil? Or how do you know if it’s from God versus if it’s from the devil? Well, one of the biggest ways is to see if it’s producing life or death. Jesus came to bring the Kingdom of Heaven way of life! So, if it’s producing the fruits of the Spirit then it’s from God. Also, remember not to settle for less than what Jesus came to give you. Don’t believe the lie that “God might bless others but that’s not for me”, because Jesus said He came to give you “life and life to the full!”', questions: 'When you read about the “full life”, what does that look like to you? Is there anything or anyone trying to rob that life? Is there any area that you’ve settled?', confession: 'Everything from God produces life. I will not settle for less than the full life that Jesus came to bring to me.' },
        { day: 7, reference: 'Matthew 25:21 NIV', devotion: 'Did you know that God expects you to grow and multiply what He’s given you? Some might assume that God doesn’t care about what we do as long as we’re “good people.” But, God has given you certain skills, gifts, and callings that He expects you to be faithful with. It’s key to know that being faithful doesn’t just mean that you are consistent but that you are growing and multiplying it.', questions: 'What gifts and talents do you have that you need to start developing? Is there anything your parents or pastors or coaches have asked you to do that you need to put more effort into?', confession: 'I will be faithful with what God has given me! When I faithfully multiply what I’m given, He will give me more.' },
        { day: 8, reference: 'Luke 6:38 NIV', devotion: 'Life is way more about what you’re giving than what you’re getting. The world’s system can often be about how much you’re growing and increasing for yourself, but as a follower of Jesus, we know that the secret is in giving. It’s a powerful promise that when you give it’s going to come back. God’s promises are sure and consistent. This Biblical call to giving is to be applied in church settings in tithes and offerings and also beyond that, by looking for ways to be generous to others.', questions: 'When is the last time you paid for a meal, gave a gift to someone else? Have you been consistent in bringing your tithes to Church?', confession: 'As I give I will also receive. God is faithful to generously bless those who live generously.' },
        { day: 9, reference: 'Joshua 1:9 NIV', devotion: 'Do Not be afraid! A common phrase God speaks to comfort and encourage us as we face life’s challenges. One of the main attacks of the enemy is to get us to live in fear and expectation of bad, but God constantly calls us to live with courage as we trust Him. In your life, you’re going to face challenges and come against enemies in the natural and spiritual which is going to require you to dig deep and courageously do what needs to be done even when it’s not easy. But when you step out in courage God will meet you with power!', questions: 'Is there anything you’ve been afraid to do? Decide to trust God, be bold, ask a friend to pray, and then step out in faith!', confession: 'No matter the circumstances I will be courageous! As I step in faith, God will give me courage!' },
        { day: 10, reference: 'Matthew 7:24 NIV', devotion: 'If we put God’s Word into practice that’s when everything changes! Christianity isn’t just about saying or knowing the right things but about living and doing the right things. And when we put His Word into practice we can expect that our lives will begin to reflect what we see in The Bible. When we don’t build on the rock-solid foundation of the Word of God we’ll find that our world will be unstable. Ask The Holy Spirit to help you build a life based on His Word!', questions: 'Is there anything from God’s Word that you know but that you’re not currently following? Have you ever disobeyed God’s Word? What happened?', confession: 'I will listen and obey God’s Word fully and completely. As I apply God’s Word it will create an unshakable life.' },
        { day: 11, reference: '2 Corinthians 6:14 NIV', devotion: 'What does the Bible mean by yoked? It’s a term for the harness that goes over two animals plowing a field. To get the maximum potential out of the ox or horse you’ll need to select two animals that are similar in height so that they pull at similar strength. When an animal is unevenly yoked it can cause problems. In the same way, we want to be careful not to link up with people who are not on the same page with us Spiritually. This is true for friendship, dating, and marriage. Choose to date only those who share your passion for Jesus.', questions: 'Are you a passionate follower of Jesus? Do your close friends share that passion? Is there anyone in your world you should spend more or less time with?', confession: 'I will choose the relationships that share my passion for Jesus, life, and calling.' },
        { day: 12, reference: '1 Corinthians 6:18 NIV', devotion: 'This verse is truly a life hack. Often when trying to live for Christ we can accidentally focus too much on not sinning rather than on doing what’s right. The Apostle Paul tells us to flee from sin. Instead of staying in the middle of a tempting situation that you have to work really hard to avoid sinning, choose to get out of that situation, and even better yet is to learn to avoid those situations altogether. And as the verse points out, it’s more about what we’re running towards than what we’re running from. Christianity is more about chasing after righteousness than just trying to avoid sin.', questions: 'Have you ever been tempted to do the wrong thing? How have you learned to avoid that? What’s the biggest temptation you face now?', confession: 'I will run after God and live a righteous life.' },
        { day: 13, reference: 'Esther 4:12-14 NIV', devotion: 'There’s so much to be said about the story of Esther that relates to your life. But, the key I’ll focus on now is that you’re going to be called by God to step up and speak out on causes that are facing your world today. Many try to avoid conflict and just stay silent but Esther is challenged not to stay silent but to speak up. If you remain silent, God’s plan will not be stopped, but it will create pain in others and the call will move on to someone who is willing and obedient.', questions: 'Is there something that you have heard God call you to do? What issues in this world make you the most upset? What issue do you need to start speaking up about?', confession: 'I will not remain silent when I have the truth that this world needs to know. I will speak up!' },
        { day: 14, reference: 'Hebrews 4:12-13 NIV', devotion: 'The Bible has been called the road map, the manual for life, and more and it’s the only book in all of the World and all of History that is more than a book is the Bible. The Bible is alive and working today as it was when it was first written because it’s God’s Word. The Bible has a way of getting right to the core of the matter. It opens up the truth and gives us a pathway to choose it. When you read The Bible, take it on as a truth that is to be fully obeyed!', questions: 'Do you read the Bible often? What’s your Bible reading strategy? Have you ever had a preacher share a message that felt like it was just for you?', confession: 'God’s Word is alive and active. I will embrace it as The Truth and follow it fully.' },
        { day: 15, reference: 'James 5:16 NIV', devotion: 'There’s a lot packed into this verse. First, be quick to confess your sins. Like Adam and Eve, our instinct is often to want to hide our issues but when we open up and confess to God and the trusted people in our lives it will bring life and healing! The fastest way to freedom is confession. Then it reminds us of the power of prayer! As followers of Jesus, we have a power in prayer that many underestimate. When you pray, you’re not just doing a ritual, you’re affecting change! Pray and declare God’s Word with confidence and authority!', questions: 'Do you have someone in your life that you can talk to when you’re struggling with sin? Is there anything you need to confess this week? Do you pray bold or timid?', confession: 'I will quickly confess my sins and find freedom! When I pray it shifts and changes things.' },
        { day: 16, reference: 'John 8:32 NIV', devotion: 'God’s Word is Truth. But the culture around you is hurting, broken, and in bondage, because it doesn’t know or receive that truth. Only the truths in the Bible can answer life’s toughest questions and give hope and purpose. Now, you may have been told that you need to keep your truth to yourself, but think about it, if you have the answer to someone\'s pain and you keep it to yourself, I would call that selfish. Instead, as those who have the truth, let’s freely share the truth so that others can find freedom! Keep sharing the truth and even more importantly living the truth.', questions: 'Do you have friends who reject the Bible? How’s their life? Have you seen God’s truth bring healing and freedom to someone?', confession: 'I will submit to God’s truth and walk in freedom.' },
        { day: 17, reference: 'Malachi 3:10 NIV', devotion: 'Tithing is a term that means to give the first 10% of all that you make to the Lord. While God does use tithing as the primary funding of the work and ministry of the Church, it’s so much more than that. Because you work hard for your money it becomes an incredible sacrifice and display of trust and honor to God. It’s a principle that you want to get right when you’re young because it will position your life under the open heaven of God’s provision and protection.', questions: 'Have you ever given a tithe? Is there anything holding you back from giving? What was that like the first time you gave your 10% in the offering?', confession: 'I trust God and will bring my whole tithe to the house of God! I will live under the open heaven of God’s blessing.' },
        { day: 18, reference: 'Proverbs 27:17 NIV', devotion: 'When we learn this it’s a game-changer. While we want to be friendly with everyone and kind to all in showing them the love of Jesus, we should not get close to everyone. To sharpen iron you don’t use wood or other types of material, you use iron. So, to grow, sharpen and increase as the man or women God has called you to be, you’ll need to get around other people with that same heart for God and passion to follow God’s Word.', questions: 'Who do you have in your life that sharpens and makes you better? Or who do you need to spend less time with and who could you choose to start spending more time with?', confession: 'I will put myself around others who make me better even if it intimidates me.' },
        { day: 19, reference: 'Proverbs 27:18 NIV', devotion: 'In a world of self-promotion, God’s word calls us to something different. This Proverb holds a major key to life and success. Instead of your primary focus being how you can get ahead or how others can help you, look to see first how you can serve and help someone else’s dream come to pass. When you serve and honor your leaders and make their vision happen, God will be sure honor flows towards you. Often the dream in your heart will come to pass as a part of helping your parents, mentors, and pastors’ visions get fulfilled.', questions: 'What’s a major dream you have in your heart? How can you help make the dream of your leaders a reality?', confession: 'I will look to fulfill the vision of those God has put in my life first. As I honor others, honor will flow to me.' },
        { day: 20, reference: 'Romans 12:1-2 NIV', devotion: 'The world, as in the culture that doesn’t believe in Jesus or even aggressively opposes God’s ways, has a pattern. The Bible is God’s pattern. A pattern is like a blueprint on a home. The construction workers take the blueprints and build the home. The world has blueprints that will end up leading you to build a life of pain and dysfunction. But, God’s pattern or blueprints will always lead towards life. It doesn’t mean that being a Christian will always be easy but it will always lead towards your good.', questions: 'Have you noticed any destructive patterns from music, movies, teachers, or celebrities? How do you avoid following the patterns of the world?', confession: 'God’s Word leads towards life. I will reject the world’s pattern and follow the Bible with all my heart!' },
        { day: 21, reference: 'James 1:22 NIV', devotion: 'It’s not good enough to just know what the Bible says. Even the devil knows what the Bible says and he most likely knows it more than you do. The real power of God’s Word is released when we act on it. Don’t be someone who comes to church and doesn’t apply it. Have you ever noticed that some people are new to following Jesus but they are mature and others may even have been a Christian for a while but still very dysfunctional? That’s because they aren’t applying the Bible to their lives.', questions: 'Is there anything in the Bible that you know you need to start doing? What’s stopping you? What’s your favorite Biblical character?', confession: 'I will listen and obey God’s Word fully. When I follow God’s Words it unlocks all of God’s promises!' },
        { day: 22, reference: 'Proverbs 11:24-25 NIV', devotion: 'God’s kingdom flows through giving. Jesus said it’s more blessed to give than to receive. When we posture our lives in a giving, serving mode it will expand and unlock our life. Many people live in fear of losing. Maybe losing money, or friends, or influence or their career. And when you live to not lose, you end up losing. But, when you live to serve and help others thrive then you’ll find that your life is more blessed than when you tried to hold onto everything. Growth is not found in holding on but in letting go.', questions: 'Who can you be kind and generous to this week? Is there someone you can give to with your time or money? Is there an organization that you can serve?', confession: 'I will live a big and generous life. I will focus more on giving than receiving.' },
        { day: 23, reference: 'Psalms 1:1-3 NIV', devotion: 'Whoever you’re walking next to in life is who you will end up becoming like. King David gives us a powerful strategy to live a thriving, growing, and fulfilled life. He says, don’t walk with or keep the company of sinners and those intent on wickedness. Now that doesn’t mean that all of your friends have to be perfect or none of us would have friends. But, what is the goal of their hearts? Is it to please God or their sinful desires? Then David says after you put yourself around the right people; focus and meditate on God’s laws and principles. God’s word will produce life!', questions: 'Identify two people that make your life better. How can you thank them? Start a Bible reading plan today.', confession: 'I will surround myself with friends that are committed to God’s ways. Together we will live to please God.' },
        { day: 24, reference: 'Psalms 119:9-11 NIV', devotion: 'Purity isn’t often a word we hear a lot about in normal conversations but God calls us to live with purity. The Bible calls us to sexual purity by keeping sex within the boundaries of marriage. The devil is constantly trying to get you to compromise your values and live impure because he knows that it will destroy your life. Living pure is less about not doing the wrong thing and more about focusing on doing the right things. David says we live pure by engaging and getting God’s Word deep down in our hearts.', questions: 'How are you pursuing your calling and dream daily? What boundaries can you set up in your relationships to live with purity?', confession: 'I will live with sexual purity in thought and in action. I will live according to Your Word.' },
        { day: 25, reference: 'John 3:16-17 NIV', devotion: 'Why did Jesus come to earth? Was it because He was mad at us? As you can see above, Jesus was sent by God because He loved us so much! He came because He loved you so much not because He’s mad at you for sinning. This should put great hope in your heart and thankfulness that even though God could have just left us in our sin, He chose to leave Heaven and come to earth on the greatest rescue mission of all time! You are incredibly loved by God and He’s going to work through you to introduce your friends to God’s love.', questions: 'Is God more interested in judging you or loving you? What was Jesus’ reason for coming to the earth? Have you decided to put your faith in Jesus?', confession: 'God so loved me that He gave His very best! Jesus came to earth to rescue me from sin and death.' },
        { day: 26, reference: 'Philippians 4:6-7 NIV', devotion: 'There are so many things and situations that we can end up being worried about; at home, school, social media, or in the news. But, as a follower of Jesus, this verse gives us a formula that can guard our minds against worry. When you have fear or worry pray! Take your thoughts and doubts and fears to God and trust Him with it. When we’re trying to solve all of life’s challenges it’s overwhelming, but when we pray, it invites the peace of God to move in and protect us.', questions: 'What is the biggest thing you worry about? Have you talked to God about it yet? What is God saying to you? In Jesus’ name, command the devil to leave your mind and heart!', confession: 'I will trust God in all things. When I’m worried I will pray and not doubt. He will give me peace!' },
        { day: 27, reference: '1 Corinthians 10:13 NIV', devotion: 'The devil will bring temptations into your life that he knows to have the potential to derail you and cause you to sin. But, God’s word promises that He will always provide a way out of that situation. The big question is, will we take the way out or are we going to allow the devil to win in our lives? The first key to getting out of temptation is to stay far away from the trap in the first place. Don’t go near a situation that could take you out. Instead, be intentional to position your life in a place that is linked in with Godly people.', questions: 'What temptations could cause you to sin? Be honest. What are some ways you can stay away from them? Who can you confess to if you do sin?', confession: 'I choose to follow God’s way. When I’m tempted, with God’s help I’ll choose the way of life.' },
        { day: 28, reference: '1 John 4:4 NIV', devotion: 'No matter what challenges you face or what the devil tries to bring your way, you can be bold and confident knowing that nothing is more powerful than the Holy Spirit living in you! We are often tricked into believing that the enemy is winning or that the situation is too hopeless to even try, but we must remember that we have all authority from heaven. As followers of Jesus, we still have challenges and battles that we have to fight but, we can fight with confidence that Jesus has already overcome all the work of the enemy!', questions: 'Will you take the authority that God has given you or will you leave it on the shelf and be silent? What does it look like to pray with authority?', confession: 'Because of Jesus, I have overcome the world! Nothing on earth can stop God’s purpose in my life.' },
        { day: 29, reference: 'John 14:6 NIV', devotion: 'The culture around you is often confused about what is true or even if we’re able to know what truth is. But, know that there are absolute truths revealed in nature and confirmed by God in the Bible. There is truth and lies. There’s right and wrong. And Jesus makes a strong claim, He says He is the way and the truth. He’s not just one way of many other gods or religions, He is THE WAY. There is no other path to God apart from Jesus. He’s the only way for people to have their sins forgiven and make peace with God.', questions: 'What other theories have you heard from friends on heaven or God? Have you decided to commit to God’s Word fully? Who can you invite to church this week?', confession: 'Jesus is the only way to Heaven! God’s Word is the final truth and authority we live our lives by!' },
        { day: 30, reference: '2 Timothy 1:7 NIV', devotion: 'Since we know that God’s Spirit is greater than all other spirits on the planet, it should give you boldness and courage! Fear, insecurity, and intimidation are not a normal or acceptable part of Christianity. Satan causes fears and insecurities but Jesus’ Spirit always causes us to walk fearlessly and courageously! Next time you feel afraid, stop and focus on Jesus and His strength. Then remind yourself that the God who created the heavens and the earth has given you power and authority!', questions: 'Have you ever been scared of something? Remember a time when you overcame the fear and did it anyway! Pray and ask God to fill you with the Spirit of Power!', confession: 'I carry the Spirit of faith! I will not live in fear or be intimidated, but will act with courage!' },
        { day: 31, reference: 'Ephesians 6:10-11 NIV', devotion: 'We don’t often think of being in a war, but we are fighting spiritual battles, that require spiritual weapons. God equips us with exactly the resources we need to stand our ground. Again, even though we bring up the devil scheming against you, it doesn’t have to make you afraid because in Jesus’ name and the armor He’s given, you have the authority to fight and win! Read through the full armor of God in Ephesians 6 and don’t leave for your day with suiting up in your spiritual armor!\n\nquestionS\n\nHave you ever felt as if you were in a spiritual attack? What did you do? What part of the armor of God do you feel you use most often?', questions: '', confession: 'God has given me armor and I will use it to take a stand! I will resist the work of the devil!' },
        { day: 32, reference: 'Philippians 4:8 NIV', devotion: 'This is one of those verses you’ll want to memorize. This is a guide to living a great life. What we focus on and think about continually is what we end up producing more of in our lives. The Apostle Paul is challenging us to use this list as the guide for what to put my attention on. The way we do this, is to take the list of admirable, lovely, praiseworthy, excellent and ask yourself are the thoughts I’m thinking about myself or others fitting that list? If not, begin to focus on those things. It will enhance your relationships so massively!', questions: 'Do most of your thoughts line up with the Philippians 4:8 list? What can you do to start focusing on the good?', confession: 'I will choose to focus my thoughts and attention on what is lovely, admirable, excellent, and praiseworthy.' },
        { day: 33, reference: 'Jeremiah 29:11 NIV', devotion: 'There are promises throughout The Bible that speak to the heart and desires of God towards you. One of those overarching themes is that God wants good for your life. The plan and intention of heaven for your life are the prosper you and to give you a future full of hope! That doesn’t mean those good plans will happen without a fight or resistance, but you can be confident that before you were even born, God has marked out good things for you and your future! Trust God! And if your current situation isn’t good, don’t settle there, keep pushing towards what God has for you!', questions: 'What dream has God given you? Did you ever have a plan not work out? What did God teach you in that?', confession: 'I am loved by God and He has good plans to prosper me and give me hope!' },
        { day: 34, reference: 'Proverbs 4:23 NIV', devotion: 'The Bible doesn’t make many of these statements of extreme importance. So, we want to take note when it says “above all.” We need to realize that all good and evil flows out of the heart. So, that means you want to be extra specific about what you allow to come into your heart. How do things enter our hearts? Through what I see, hear, and experience. You want to review things that you watch, listen to, and the circle of people around you. Begin to use a Biblical filter for what you decide to watch, listen to, and do.', questions: 'Do you feel like your heart has been hurt a lot? Are there some changes you want to make in what you put in your heart?', confession: 'Life flows from my heart! I will guard and protect it by using a Biblical filter on what I listen to, watch and do.' },
        { day: 35, reference: 'Romans 8:1-2 NIV', devotion: 'This is one of the really good news verses in the Bible. Because of what Jesus did by taking on the punishment of our sin, we don’t have to live under shame and condemnation for our sin that we have confessed to Jesus. It can be common to feel like we have to mope around or look depressed because of our sins in the past or present. While we do need to confess and turn from those sins, we can then hold our heads up high and approach God with full confidence because of what Jesus has done for us on the cross.', questions: 'Do you find yourself struggling with mistakes you made? Have you taken the time to confess past or present sin?', confession: 'In Jesus, I am forgiven and free! I don’t need to live in regret or shame. I am a child of God!' },
        { day: 36, reference: 'Ephesians 6:1-3 NIV', devotion: 'This verse is powerful for those willing to embrace it. Honoring your parents is the first command with a promise of God’s protection and provision. There’s something incredible when we honor. And this verse doesn’t suggest that you only honor if your parents are good people. We’re honoring who they are and the position of authority in our lives. It’s easy to discard or downplay the role of parents in today’s culture, but a healthy family is at the core of a strong life. Look to honor your parents and watch God’s favor on your life.', questions: 'Do you feel like you’re honoring your parents well? What does that look like for you? Do you need to repent for dishonor?', confession: 'I will bless and honor my parents. I will be a great parent in the future that loves my children well.' },
        { day: 37, reference: 'Ephesians 6:12 NIV', devotion: 'Did you know that the evil and dark forces trying to destroy you, aren’t just for theatrics in a movie? There is a real devil who hates God and therefore hates all who follow Him. So, there are going to be times when demonic presence is trying to work against you. But, the good news is that you don’t have to be intimidated by that but you do need to take a stand and resist the enemy. Don’t let you or your family or your calling be pushed around by a defeated enemy. Resist the devil in Jesus’ name!', questions: 'Have you ever felt or sensed something evil trying to resist you or mess with you? What did you do? What can you do next time?', confession: 'There is an enemy but I do not need to fight him by natural means but in the power of God!' },
        { day: 38, reference: 'Proverbs 1:7 NIV', devotion: 'This is another one of those absolute foundations! You might be wondering why we should be afraid of God? God is so awesome and powerful that having a little fear and trembling isn’t a bad thing, but this verse is more about putting God in His proper place in your life. Wisdom flows when we start from the foundation that God is the first and the last! He is the creator and sustainer of everything! And that He is the leader and authority over my life that I must submit to. When you see God properly then all of life makes sense from there. When you reject God, then confusion flows.', questions: 'Are you submitted to His Word? Will you choose to follow your feelings and culture or The Bible?', confession: 'God is the final authority and has the final say in my life. I choose to fear and trust God and His Word!' },
        { day: 39, reference: 'James 4:7-8 NIV', devotion: 'There’s too much goodness in these verses! First off, all the promises in these verses begin with the recognition and submission to God and His authority in your life. When we are properly positioned under God’s authority, which means we listen and obey His Word, then we get the rest of these verses. We have the authority to resist the devil only when we submit to God’s authority. And I love God’s promises to come close to you when you reach out to Him!', questions: 'Is there any area of your life that you haven’t submitted to God? When is the last time you spent time with Jesus in worship and prayer?', confession: 'I submit my whole life to you, God! I will come close to you and I will kick the devil out of my life!' },
        { day: 40, reference: '2 Timothy 2:22 NIV', devotion: 'Evil desires and temptations are going to come. We often try to fight temptation when The Bible more often calls us to run from it or avoid it. Most of the sins we fall into can be avoided by staying away. King Solomon warned us to stay away from the home of the temptress. But, it’s not just about running away, it’s about what you’re running to. The goal in life isn’t just to not sin, but it’s to live for God and fulfill our purpose! As you run after God’s purpose you’ll usually be running away from sin as well.', questions: 'What tempting situations do you need to stop putting yourself in? How can you pursue faith, love, and peace?', confession: 'I will run from temptation and give my life to pursue the purposes of God.' },
        { day: 41, reference: 'Ephesians 3:17-19 NIV', devotion: 'The Apostle Paul begins by calling us to be planted in Christ and let our roots go down deep! Just like a fruit tree must be planted to produce fruit, we must be planted to stand strong and remain fruitful in all seasons. He goes on to pray that we would grasp how God’s love is so far beyond comprehension. His love is so incredible that it’s often beyond our ability to comprehend it. It’s not an earned love or a love that grows cold, it’s a constant love that never fails and never ends.', questions: 'When was the first time you felt the love of God? Can you even imagine how wide and deep God’s love is for you? How are you staying planted in your faith?', confession: 'I am committed and planted in the Church! God’s love is never-ending and never failing!' },
        { day: 42, reference: 'Ephesians 4:29 NIV', devotion: 'Our words are a powerful and creative force in our lives and the lives of those around us! When you constantly let harsh and cutting words come out of your mouth it is literally like going into the middle of a forest and then starting that forest on fire. Be mindful and intentional about the words you speak. You won’t be perfect, but make it your goal that the way you speak to your parents, siblings, friends teachers, or anyone is packed with life and encouragement rather than cutting and negative comments.', questions: 'Do you find it harder to say nice or mean things? Is there anyone you need to apologize to for your words? Who can you encourage today?', confession: 'My words have life or death. I will choose to make my words life and strength to others.' },
        { day: 43, reference: 'Luke 2:52 NIV', devotion: 'As Jesus was fully God and fully human, He still had to go through the growing-up phases of life through childhood and teenage years. Luke 2:52 gives us a snapshot of the four areas that He developed in. Wisdom, stature, favor with God and with Man. These are great areas to see your own life develop in. You might rate yourself and set growth goals in those four areas. Are you continuing to increase in your wisdom and problem-solving? Are you keeping health a priority? How’s your time with God? Are you learning to serve others?', questions: 'How would you rate your growth in each of the four areas that Jesus grew in? Set a growth goal in each area.', confession: 'I will continue to grow and strengthen my mind, body, soul, and spirit!' },
        { day: 44, reference: 'Matthew 5:14-16 NIV', devotion: 'Your relationship with God is personal but it’s not meant to stay private or hidden. Jesus saved you and put His light inside your life and now He wants to set you up as a light that guides people back home. You don’t have to be perfect to shine your light. Sometimes we feel the need to have it all figured out or we’re afraid we don’t know what to say. But our role primarily is to carry the light of God’s love and let it shine through all that we do. That in itself will draw people to God.', questions: 'Have you told anyone lately that you’re a Christian? When is the last time you invited someone to a church? Is there anything stopping your light from shining?', confession: 'I will shine bright and point people to Jesus! I will not hide the good news. I will live out my faith in all areas!' },
        { day: 45, reference: 'Matthew 6:9-13 NIV', devotion: 'Jesus begins to teach his disciples how to pray. There’s so much that Jesus brings up in these verses, but let’s focus on how He has you start. He teaches us to address God as Father. Not just some distant creator-type force, but a close and personal Father. He’s open and ready to listen and respond to you. Also, Jesus calls us to focus on God’s Kingdom. Make sure that all your prayer time isn’t just about what you need but also praying for God’s will to be done in your city and nation.', questions: 'Do you enjoy taking time to pray? How often do you find yourself praying? What is one issue in your city or state that you’re praying for God’s will to be done?', confession: 'As a child of God, I boldly come to Him in prayer. He hears and responds! Let Your Will be Done On Earth!' },
        { day: 46, reference: 'Matthew 6:24 NIV', devotion: 'The truth is that many in our world have made money their god. Getting more and having more or holding on to every dollar because of fear of not having any money are all forms of the love of money. One of the greatest ways to know if you’re serving God or money is how easy it is for you to give your money. Generosity is the greatest antidote to greed. God’s promises will produce financial blessings when you apply them, but we have to be good with that money. Keep your life more about giving and blessing others. No matter how wealthy you become you can stay free from greed and keep Jesus at the center when you stay generous.', questions: 'Is God or money your master? List 3 ways you can create wealth. What are some ways to stay generous?', confession: 'God is my master and money is my servant.' },
        { day: 47, reference: 'Romans 10:9-10 NIV', devotion: 'Many initially come to Christ because they know they need to be saved from their sins. Which is true and important to understand. But, we must move on to maturity and understand that my life is no longer just mine but His. When I turn to Jesus as Lord, it means that I am looking to Him as my ultimate authority in all areas of life. He empowers us to think, grow and take dominion on earth, but we do all of that with the understanding that He has the final word. Lord means that it’s His way over my way. You cannot have Jesus without Him being Lord.', questions: 'Have you confessed that Jesus is your Lord? Have you had to choose between your way and God’s Way?', confession: 'I confess Jesus as the Lord of my life. Not my will, but His will be done in and through me.' },
        { day: 48, reference: 'James 1:5 NIV', devotion: 'The Bible says He will generously give you wisdom. The Holy Spirit is our guide, comforter, and leader. He’s wanting to guide you along the path of truth. Don’t try to struggle and push your way through life without asking for help from God. He’s available to you and wants to speak to you. And just so you know, He doesn’t just give wisdom to spiritual questions, God can guide in all circumstances. Ask for wisdom at your school, job, with your friends, in dating, and all areas. He will guide us through His Spirit, His Word, and His people.', questions: 'What area of life do you need wisdom? Have you asked God for help? Have you asked a mentor for help?', confession: 'God is willing and ready to guide and give me wisdom on all occasions.' },
        { day: 49, reference: 'Matthew 6:31-33 NIV', devotion: 'First things first! There’s an order to life. When things are in order and alignment they tend to work better. When you put God’s kingdom first, there’s less need to worry about your situation. It’s easy to get all caught up in worrying about what the rest of the world is worrying about but Jesus tells us to stop that and put the Kingdom first! When you’re planning for your future, invite God into it and ask Him what He wants you to do.', questions: 'What are things you tend to worry a lot about? What are you doing to advance the Kingdom of God? Like, sharing your faith, serving on a team at church, leading a small group, and disciplining others?', confession: 'I will seek first His Kingdom and His will for my life! I will be blessed as I put His will first!' },
        { day: 50, reference: 'Galatians 6:9 NIV', devotion: 'Don’t quit! This is one of life’s biggest lessons. Great influence, success, and fulfillment aren’t usually going to the smartest and most gifted people, but to those who were committed to not giving up! This verse is a promise from God that if you keep doing the right things, it will produce in your life if you don’t give up. Many people give up too soon on their calling or dream because of struggle. Trust God, if you stay in the game, if you keep His commands, God will reward you.', questions: 'Do you remember a time when you wanted to quit but kept going? How did that feel? Have you ever quit too early? What’s something that you’re chasing right now that you’ve been tempted to quit but you’ll keep going?', confession: 'I will not quit on my calling and purpose! God will bring the harvest of my efforts if I stay faithful.' },
        { day: 51, reference: 'Psalms 23:1-4 NIV', devotion: 'These are great verses to read often. It speaks of God’s desire to bring us peace and to lead us into good things. He desires that you lack nothing! These verses give us a promise, that no matter what dark and painful season we may be facing, God will never leave us. He will keep guiding with His rod and staff. That means there will be some correcting moments and many comforting words from Jesus to keep calling you forward to green pastures. Because God is with you, even if all the world seems like it’s falling apart, you don’t have to be in fear or worry. Stay close to Jesus!', questions: 'What’s the most difficult time you’ve faced so far? Looking back, can you see how God was still with you?', confession: 'I will follow the leading of the Good Shepherd. I will not live in fear because He is with me!' },
        { day: 52, reference: 'Romans 8:28 NIV', devotion: 'This is a big one! In ALL things. So, no matter if your life is good right now or you feel like you’re in the fight of your life, God is going to work all of it for your good because you’re His child. That doesn’t mean that God is causing your pain or that all tragedy is good, it just means that whether good or bad circumstances, God can and is actively causing them to all work together for your good. God is even able to take our failures and turn them around for your good and His Glory!', questions: 'Has there been anything difficult in life that you now see how God used it for good? What are you going through right now that you are praying works for good?', confession: 'God is causing everything in my life to work out for my good and His Glory.' },
      ]
    },
  };


const CACHE_SECONDS = 86400; // this content is fully static -- 24 hours is plenty

exports.handler = async function (event, context) {
  const headers = {
    'Content-Type': 'application/json',
    'Cache-Control': `public, max-age=${CACHE_SECONDS}`,
    'Access-Control-Allow-Origin': '*'
  };

  const planKey = event.queryStringParameters && event.queryStringParameters.plan;
  if (!planKey || !DEVOTIONAL_PLANS[planKey]) {
    return {
      statusCode: 400,
      headers,
      body: JSON.stringify({ error: 'Unknown or missing plan key', validKeys: Object.keys(DEVOTIONAL_PLANS) })
    };
  }

  return {
    statusCode: 200,
    headers,
    body: JSON.stringify(DEVOTIONAL_PLANS[planKey])
  };
};
